/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20101026-9","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"文教委員会","time":"午前１０時０２分～午後１時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２２年特別区人事委員会勧告","agenda":"の平成２２年特別区人事委員会勧告","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"総務委員会のところとかかわるかと思いますが、若干教えていただいてもいいですか。ここに書かれてあるのでちょっと聞きたいのは、最後のページのメンタルヘルスの推進のところで、ここで書かれているのは当然なんですけれども、品川区は、今回は４３名のところしかかかわらないんですかね。教職員のところもそうですけれども、この辺の状況をちょっと聞かせていただければと思います。","respondent":"田村庶務課長","answer":"ですから、いつでも相談窓口は開いていますので、早いうちに専門医療の方につなげるということで、まさに勧告の内容を早くから取り入れて、実施しているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なところをお聞きしたかったのですが、特にメンタルヘルスのところは、社会全体でもすごく注目されているというか、何とかしなくちゃいけないというようなことで、教職員の方々、管理職の方をはじめとして、すごく多忙な中、体調を崩されている方もかなりお見受けするので、ぜひ力を入れていただきたいということでよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"の保幼小ジョイント期カリキュラム","agenda":"の保幼小ジョイント期カリキュラム","exchanges":[{"speaker":"井上委員","kind":"質問","question":"内容に入る前に、前にも指摘したことなんですが、この冊子についてとても立派なものができているわけですけれども、１冊のコストと、印刷の契約なんかがもう少し、こういう財政難の折にこういったところの視点も必要であるという観点からお聞きしますけれども、どういったところでつくられていて、これをこれからどういうところに配って使っていくようにしていくかもあわせてお聞かせください。","respondent":"冠木指導課長","answer":"それからあわせて、私立の保育園、私立の幼稚園にも相当数を配布させていただきまして、品川区の子どもたちの支援のためにあてていただくというように考えております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"冊子の発行数がトータルで幾らなのかということと、ちなみに教育委員会でこういった冊子をつくるときに、印刷料というのは契約がどういうふうになっているのか、これに限らず、わかれば教えてください。","respondent":"冠木指導課長","answer":"こういった冊子を一般につくるときの考え方としては、一般競争入札でやっております。発行部数は確認します。","voiceIndex":14,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"桑野先生についても、選考されるときに幼児教育も含めて、今までの取り組みも含めて選考されたというふうに次長からは内容を伺ったんですが、これはどうして平成２１年度は２人の先生になられて変更になっているのか。作業部会の方でも、部長として選ばれたこの方が酒井先生に変わっているわけですが、どういった状況でこのようになっているのでしょうか。","respondent":"冠木指導課長","answer":"桑野委員につきましては、今年度４月の人事異動で他の区に異動しておりまして、そういった関係で、基本的にはこの就学前教育に対して造詣が深いといいますか。","voiceIndex":16,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"検討会の方では平成２１年度中に変更していますけれども、なぜこういった状況になったのでしょうか。","respondent":"冠木指導課長","answer":"これは平成２１年度の委員、平成２２年度の委員という意味ですので、途中で変わったというわけではなくて、年度の切り替えのところでの変更という意味あいです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"小学校長の代表という方は、当時１人ではなかったかなと思うんです。平成２１年度に桑野先生が初めになられていて、そのときにやはり違うと思うんですけど、傍聴に行ったときにも違っていらっしゃるので、平成２１年度中に変わっているという表記だと思うんですがいかがでしょうか。","respondent":"冠木指導課長","answer":"平成２１年度に変更したという事実はございません。桑野委員については平成２１年度いっぱい委員をやっていただいております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"井上委員","kind":"確認","question":"小学校の校長先生は、平成２１年度は２人いらして、平成２２年度は１人に変わったという理解でよろしいのか確認をさせてください。","respondent":"冠木指導課長","answer":"平成２１年度は桑野委員と岸委員、平成２２年度は酒井委員です。","voiceIndex":22,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"基本的にここまでいろいろ示さなければいけないのかなというところについて、どういうふうな議論の中でまとめられているのかちょっとお伺いしたいと思います。","respondent":"冠木指導課長","answer":"このジョイント期の子どもたちの状況についてはさまざまな課題があるんですけれども、それを小学校側としましては、今までも、例えば経験豊かな担任の先生を配慮して担任とするとか、幼稚園や保育園からの情報をいただいて。","voiceIndex":24,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"せっかくつくられた冊子がただ配られただけで終わらないように、その後も見ていく必要があると思うんですが、今、おっしゃられたように、親の理解が得られないという部分でもし共通ガイドにできるのであれば、親の方にも何らかのこういったものがあるというようなお知らせとか、目に触れる機会があった方が、保育園や幼稚園でされていることについてちょっと違うんじゃないかといったときにも。","respondent":"冠木指導課長","answer":"それからもちろん、さらにもっと広い意味で家庭への啓発等々は必要だと考えていますので、この事業については保育課と私どもの方で連携してやっている事業ですので、保育課で来年保護者向けのリーフレット的なものを考えているというような情報もいただいているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"この中に子どもたちの自立というのがあるのでしょうか。そうすると、入学式は４月６日とかそのぐらいじゃないですか。自立というのがどこまで入っているのかなというのを聞きたかったのですが、なぜかというと、学校に１人で行けますかと。そういう意味で、小学校１年生になったら最低限の自立というのはあるので、そこら辺をどこまで盛り込んでいくのかなというのをお聞きしたいと思います。","respondent":"吉岡保育課長","answer":"それから私立幼稚園へのアプローチですけれども、実は先週私立幼稚園の園長会がありまして、でき上がったばかりのものを持参いたしまして、教育委員会の指導主事と私とで、私立幼稚園の園長さんには「こういうものをつくりましたので。","voiceIndex":28,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"自立というところもお聞きしたいんですけど、ちょっとやさしすぎると思います。基本的なことですから。当たり前のことですから。これはほとんど家庭内の仕事なんです。できない、生活環境の中で非常に難しいという親御さんに対してどうフォローしていくかということの方が私は大切だと思いますので、そこのフォローをどう考えるのか。自立ということがどこまで入っているのかもお伺いします。","respondent":"吉岡保育課長、冠木指導課長","answer":"ただし、内容につきましては、先ほど指導課長からもご説明したように、区としても十分自信を持って、これがジョイント期の指導の基礎になるものだと考えていますので、私立幼稚園に対しても、この辺の区の考え方をご説明しまして。自立といいますと非常に広い意味あいがありますので、障害であるとか、そういう部分もあるんですけれども、そういった意味で。","voiceIndex":30,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"私立のお子さんは少なくなるんです。なので、その目的というのは、私立から入ってきてもこれだけは守ってねという原則ですよ、品川区の小学校１年生はこのぐらいが現実なんですよということははっきりしておいてほしいなと思います。そこに対しての保育園側の指導というんですか、それをどのように考えているか。その人たちに対してどういうふうに考えていきますかということをお聞きして終わりにします。","respondent":"吉岡保育課長","answer":"保育園の保護者、そのうちのできない親といいますか、対応がなかなか難しい親御さんたちにどう対応するのかということですが、これはまさに個別の問題になってしまうと思うんですが。","voiceIndex":33,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういう考えでいらっしゃるのかなと。中身的にはこれから見るので、後でまたゆっくりお伺いしたいと思っていますが、こういった品川区の今行われているジョイント期、のりしろと言われていますけれども、注目はされていますし、どういう方法がいいのかというのはさまざまな検討やご意見をいただきたいと思うんですね。もう１回これの生かし方というか、位置づけをお伺いしたいと思います。","respondent":"冠木指導課長","answer":"こちら平成２０年につくりました「のびのび育つしながわっこ」、これがベースになっていることは申すまでもございません。考え方としては、今日お渡しした文教委員会資料、Ａ４横判の一番上に、「のびのび育つしながわっこ」で０歳児から就学前までの指導がなされてくる。","voiceIndex":35,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日、ぱらぱらっとご説明していただいたり、課長の発言からすると、指導課というところでどちらかというと小学校の部分の教育でいろいろな問題も抱えていらっしゃるのでそっちの方が強いのかなと思ってお話を伺っていたんですが、ベースが「のびのび育つしながわっこ」であるというところにおいては、今、本当に子どもの育ちの問題でいろいろな問題が噴出していますし。","respondent":"冠木指導課長","answer":"小１プロブレムにつきましては、今、説明をしましたような生活する力、かかわる力、学ぶ力、こうした力を子どもたちが十分に獲得していくことによって、そういった部分についての１つの予防策になる、そして子どもたちが社会性を培っていくところで。","voiceIndex":37,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうところにおいては何者にも邪魔されなくて、自由にそれができて、それからだんだんいろいろな規制とかルールを学んでいくものなので、現実的には最初から「こうやって学ぶ」「ああやって学ぶ」とか、そういうものではなくて、もっとフリーで、おおらかで、ゆったりしたものが遊びだというとらえ方がまずおおもとにあるんだというのをとらえた上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"そうしたときに、この基本的な、本当に細かく共有する考え方、これをベースにしていくんですが、多分今まで先生たちはこういうことは常々されていることだと思いますし、だから新しくこれができたから新しいことを始めなきゃいけないというようなとらえ方ではなくて、常々やっていらっしゃることを自信を持ってやっていただきながら、さらにもっと踏み込んで。","respondent":"冠木指導課長、吉岡保育課長、若月教育長","answer":"委員のお話しされたことは本当にそのとおりでございまして、私どももそのために、例えば教育研修であるとかという取り組みはするんですけれども。これは例えば、先ほど飯沼委員がお話しになっていましたけれども、例えば小１プロブレムの背景は何かというと。","voiceIndex":40,"id":"exchange-017"},{"speaker":"金野委員","kind":"提案","question":"そういう毎年毎年小学校へ送る子どもたちの状況を、小学校の先生と幼稚園・保育園の先生の交流の機会を持っていらっしゃるのかどうか、そういう交流の時期、特に年度末の切り替えの時には、担任の先生が決まる時期だったりするこの時期というのは、交流を持つ時期ではないかなと思うので、そういった先生たちの情報交換の場所があったらいいのではないかなと提案をいたしますが、どうでしょうか。","respondent":"冠木指導課長","answer":"非常に重要なファクターでございまして、せっかくいいものができてもそれが伝わらない、それぞれの立場でそれぞれの取り組みがないと子どもたちの成長というのはなかなか進んでいかないということがありますので、これは保育園ももちろんですけれども。","voiceIndex":44,"id":"exchange-018"},{"speaker":"金野委員","kind":"提案","question":"今の質問で、教育委員会と保育課との連携を図りながらジョイント期を進めていくに当たるこの冊子が、子どもたちの教育のこれからの、今すぐには結果が出るというものではなく、これから先の子どもたちの教育に大きく寄与できるように見守りながら、これからもいろいろなところで提案をしていきたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"確認","question":"となるならば、将来の見直しをしていくことはあるんですか。そのことの確認を一つ。これはテストで平均点を出すよりも、もっと簡単に子どもたちの様子を観察することができるし、もっと簡単に客観的な評価ができるわけじゃないですか。確認したいのは、効果の測定をするのかどうかですね。そしてその結果、ＰＤＣＡサイクルとかあるけれども、それをどうしていくかということ。","respondent":"冠木指導課長","answer":"それから２点目の検証につきましては、実は説明をする中で、今年の１月からモデル実施をやりました。保育園・幼稚園側でもやりました。小学校でもやりました。","voiceIndex":47,"id":"exchange-020"}]},{"id":"topic-03","title":"の品川地区幼保一体施設の概要","agenda":"の品川地区幼保一体施設の概要","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今回、平成２３年４月から御殿山幼稚園がここを使うということで、御殿山幼稚園の子どもたちにとって、ここに来て何か変わることはあるんでしょうか。","respondent":"吉岡保育課長","answer":"そうしますと、従来の幼稚園では４、５歳児だけで完結しておりましたところ、０歳から３歳の、いわば下の小さい子どもたちが一緒の空間の中で学び育つということになりますので、その辺のところでの幼保一体施設としての特質を生かしまして。","voiceIndex":54,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"幼保一体型のところに幼稚園ということは、預かり保育も行うということで、給食体系は、御殿山幼稚園の子どもたちはどのようにこれから進めようとしているんでしょうか。","respondent":"吉岡保育課長","answer":"給食につきましては、従来の幼保一体施設と同様に、週２回程度の給食の体験、それから預かり保育につきましても給食の提供を予定しています。","voiceIndex":56,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"今まで御殿山幼稚園のところで預かり保育をやっていた場合ではお弁当を持ってということだと思うんですけれども、今回は給食が週２回提供されることになって、預かり保育をしたいという子どもに対しては、きのうの浜川幼稚園のお話もあったんですけれども、お弁当を持ってきて預かり保育をするというような、その辺をしっかりとどういう体系で進めようとしているのかお伺いします。","respondent":"吉岡保育課長","answer":"浜川幼稚園の方は、単独の幼稚園ですから給食の施設がございません。その中での預かり保育の場合については、必要であればお弁当をご持参いただくというように考えています。","voiceIndex":58,"id":"exchange-023"},{"speaker":"井上委員","kind":"確認","question":"先のことになるかと思うんですけれども、御殿山幼稚園が新園舎に移転した先のところで、この部分も第二保育園の園児が優先的に幼稚園の方に行くということは、多分そのように進められるのかなと思うんですが、そこのところの確認と、そのときに、保育園から上がってきた子どもたちがそのまま幼保一体施設に行くというときには、給食があっての就労ということになっているかと思うんですが。","respondent":"吉岡保育課長","answer":"保育園から上がっていった子は、当然就労しておりますので、給食を食べて、延長が必要であれば１９時半まで延長するわけですけれども、それと同時に、幼稚園での預かり保育で、必要があって残るお子さんがいらっしゃれば、それは運営の形態の中で。","voiceIndex":60,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"そこに１５人の幼稚園に入園した子どもも、就労として預かり保育をしながらそこに入りたいと思ったお子さんについて、そこの給食の提供というのがどういうふうな基準でされるのかというのは、はっきりとルールがないと、就労だからということで、たまたま預かりをした人は混乱すると思うんですけど、その整理が保護者の方にはよくわからないと思うんですがいかがでしょうか。","respondent":"吉岡保育課長","answer":"ただし、幼稚園の基本的な教育時間だけでお帰りになる、就労していない親御さんのお子さんについては、週２回程度の給食以外はお弁当を持参していただくという考え方です。","voiceIndex":62,"id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"給食をお願いしたい」ということになればオーケーなんだけれども、台場の方で明日ということになると、１週間前とかでないと食材の都合でできませんということで、同じすこやか園でも違うようにされているというところに保護者の方の混乱があるんですけれども、そこのところについて、園のやり方ですというのか、区としてこういう方針を持っていますというのがあるのか。","respondent":"吉岡保育課長","answer":"二葉と台場でやり方が違うというお話ですけれども、実際の運営の中で若干違う部分はあるかと思いますが、それぞれの園で運営していますので、二葉の方が台場のことで混乱するということはないのかなと考えています。","voiceIndex":64,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"２のところで、年齢区分型幼保一体施設と書いてありますけれども、このところ幼保一体施設、並列型も出ている中で、ここが年齢区分型というのは、どういう考えで選択をするのかというのを一つお伺いしたいのと、この御殿山幼稚園が再開発区域に戻った後、４、５歳の幼稚園がなくなるわけですけれども、保育園のところは０歳から３歳までですよね。この辺はどういうふうになるのか教えてください。","respondent":"吉岡保育課長","answer":"基本的に、幼保一体型施設を始めたときの考え方は、二葉すこやか園も、のびっこ園台場も、年齢区分型で０歳から３歳までの保育園があるのと、その上に４歳、５歳の幼稚園があって、保育園を終わって幼稚園に行くときは優先的に入れるということで考えていたわけですけれども。","voiceIndex":66,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安心しました。今のところはまだまだニーズがあるなというのと、３歳で後の行き場が突然なくなってしまったときにどうするのかなと思っていたので、そのまま保育園ということですね。わかりました。その辺は安心をいたしました。図面を大分前に見たんですけれども、ここのところの給食はどこでつくるのか、ちょっと教えていただきたいと思います。","respondent":"吉岡保育課長","answer":"給食につきましては、ほかの幼保一体施設や保育園と同様ですけれども、施設内の厨房でつくるということになります。","voiceIndex":70,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"施設内の厨房でということですけれども、幼稚園部分の預かり保育を希望される方のところも、学校の方じゃなくてそこでつくるということでしょうか。","respondent":"吉岡保育課長","answer":"ご指摘のとおりでございまして、幼稚園の就労支援の預かり保育の給食につきましても、同じ幼保一体施設の厨房でつくります。","voiceIndex":72,"id":"exchange-029"},{"speaker":"金野委員","kind":"質問","question":"関連なんですが、まずそこからお聞きします。一時的に御殿山幼稚園がここに入って、そして新設をされた後に戻るということですが、そのときに保育園は０歳から５歳までの保育園になりますよということは、年齢区分型の幼保一体施設という、この「幼」という部分はどうなるんでしょうか。","respondent":"吉岡保育課長","answer":"ただし、残った保育園をどういう保育園にしていくのかはまだちょっと先のことでもありますし、検討の余地はあろうかと思うんですけれども、基本的には０歳から５歳の保育園というように考えているところなので、残った保育園の方は。","voiceIndex":74,"id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"ということは、今の事業開始は６月１日なので、そのときまでは幼保一体施設の幼稚園と保育園で、そののちは保育園だけになるということでいいですか。","respondent":"古川子ども未来事業部長","answer":"そもそもこの地区に、教育に重点を置いた保育的な施設をということがございました。そのときに私は、本会議でもご説明申し上げたんですが、必ずしも幼保一体施設というようには申し上げられなかったんですね。","voiceIndex":76,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"わかりました。そうすると、今、この２つの保育園と幼稚園ですから、園長先生は２人いらっしゃるということの理解でいいでしょうか。それが１点と、あと、この預かり保育、きのうも預かり保育の延長のご報告をいただきましたが、それと同じような考え方で、いわゆる預かり保育料というものを設定するのでしょうか。","respondent":"吉岡保育課長","answer":"預かり保育につきましては、幼稚園の教育時間にプラスするサービス提供になりますので、別途、預かり保育料を徴収する予定です。","voiceIndex":78,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"これは何年ぐらいまでここにいるんですか。それと、その後どういう施設になるかわかりませんよということで、この間並列型とか、それから年齢区分型が出てきたということで、年齢区分型は、０、１、２歳が保育園になるんですよね。これから何をどういうふうにするのか、全くわからない状況なのか、将来的にはこういうことを想定した形で今いろいろやっているんだとか、そこら辺どう考えているんですか。","respondent":"吉岡保育課長","answer":"いずれにしても、年齢区分型にしても並列型にしても、形態の違いはありますけれども、４歳、５歳の幼児教育を行う年齢において、その保育園の保育のノウハウもありますし、幼稚園の幼児教育のノウハウもありますので。","voiceIndex":80,"id":"exchange-033"},{"speaker":"西本委員","kind":"意見","question":"これからいろいろ検討されていくんだろうなと思うんですが、二葉もそうですけれども、２つに分かれるんですよね。その保育園と幼稚園の中身が一緒になってくるということなのかなと。だからそこの部分はきちんと、いろいろな機会をとらえて交流を持ってもらうという必要があると思っているんですけれども、保護者がそういう話をしているかどうかわからないんですが、その辺はどうされますか。","respondent":"吉岡保育課長","answer":"ただし、同じ幼保一体施設、同じすこやか園に預ける親の立場としては同じ立場に立って子どもたちを見守っているわけですから、その中で、当然就労時間等の制約等々はありますけれども、その部分はお互いが補い合いながら進めていただくようにお願いもしているところですし。","voiceIndex":82,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"それで、方針を変えたというふうにとらえられるんですけれども、幼保一体施設ではなくなって、平成２６年に北品川第二保育園ということになるだろうという前提を決定したのは、いつの時点でそういう決定がされたのか、ここはちょっと明確にしていただかないと、審議の様子を追っていってもわからなくなってしまうので、お知らせください。","respondent":"吉岡保育課長","answer":"それで、平成２６年度の見込みですけれども、御殿山幼稚園が戻った後の保育施設がどういう形態になるかにつきましては、まだ今後検討する内容ですので、今現在では、教育的な要素を強く持った保育施設というようにお考えいただければよろしいかなです。","voiceIndex":84,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"そこがどこなのかというのは、内部的に決定したところがあると思いますので、そこを教えていただきたい。もう一つ、平成２６年の中で検討する内容であるということは、どういうことを検討して、どういうふうに結果を導こうとしているのか。どういうものかというものかはまだわかりませんとおっしゃる、検討の先の項目という部分が何なのか、先でなきゃわからないではなくて、ちょっと明確にしていただきたい。","respondent":"古川子ども未来事業部長","answer":"そういう中で、先ほど来申し上げておりますとおり、まずは０歳から３歳の保育園がありますので、当然その上の４、５歳というものは考えていくだろうということは、保育園的なものは当然に考えざるを得ないだろうです。","voiceIndex":86,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"今後の動向の具体的なものというのは、どういうものなのか教えてください。","respondent":"古川子ども未来事業部長","answer":"幼稚園につきましては、今の時点では、何らかの別な要素がありますが、少なくとも御殿山幼稚園が移転した後に、新設の幼稚園は入れませんと考えています。","voiceIndex":88,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"今の部長のご答弁で、幼稚園がなくなった部分の後については難しいというところ、もうちょっとそこのところを教えてください。","respondent":"古川子ども未来事業部長","answer":"戻った後には、今区立幼稚園は９園ありますが、新たに区立幼稚園を増やす考えはございませんので、必然的に保育園型の４歳、５歳児を含めた施設になるだろう。したがいまして、保育園であることは間違いない。ただし今、認定こども園という考え方は、制度としてはあります。","voiceIndex":90,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"民主党の政権が、今、子どもについての新システムをすごく早急に進めようとしている中で、幼稚園が幼稚園でなくなる、保育園が保育園でなくなる、認定こども園制度とか、まだよく中身が伝わってこないんですけれども、すごく微妙であるということですかね。そういうのを含めつつ、今、考えていただけているんでしょうか。ちょっと難しいとは思うんですが、その辺が気になるんですよ。","respondent":"吉岡保育課長","answer":"それからその法律が成立をした暁には、平成２５年度から実施されるですけれども、まだそれ以上に具体的な内容につきましては今後のことになると思います。","voiceIndex":92,"id":"exchange-039"}]},{"id":"topic-04","title":"の２、その他を議題に供します。 まず、(1)の所管質問","agenda":"の２、その他を議題に供します。 まず、(1)の所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"それで、その部分について具体的にどういう研修を、いつ、何回行ったのかという詳細について伺いたいと思います。大きなところで、この電話が入ったときに、２４時間見守りホットラインはどういう流れでつながっていくのかというところから、まずはお知らせいただきたいと思います。","respondent":"安井子育て支援課長","answer":"２４時間受付をしますよということで、我々が勤務している時間以外にも、夜、そういう通報があったら、そういう通報については必ず漏らさず受けて、うちの方で対応しますということなんですけれども、緊急の場合などは。","voiceIndex":97,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"１０月１日から開始したので、現状何件ぐらい、どういう電話が入っているのかということを、平日と夜間に分けて教えてください。","respondent":"安井子育て支援課長","answer":"幸いということなのかわからないんですけれども、今のところ通報は１件も入っておりません。","voiceIndex":99,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"児童虐待、ＤＶ、高齢者虐待ということで、平日の場合は、この電話をかけたときに受け手としてどういった人がここに待機されているのか。児童虐待の方は子育て支援課の方に電話が行くと思うので、高齢者はちょっと置いておきまして、そちらの部分だけでお伺いします。これはだれが受けることになっているんでしょうか。","respondent":"安井子育て支援課長","answer":"相手が特定できていればいいんですが、マンションのどこら辺とかという話だと、具体的にどこら辺になりますかねというような話を聞かないと、うちでも後のフォローがなかなかできませんので、そこら辺を重点的に聞かせていただくということ。それからどのような状況であるか。","voiceIndex":101,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"こういったものをすごく大きく出してやる以上、そういうふうになっていった方がいいと思うんですね。２４時間をうたうのであれば、夜間の人たちをもうちょっと、児童虐待に対しての知識とか対応とかというのを含めてやった人が受けなければ、これは効果的ではないように思うんですが、その辺についてどういう検討をされたのか。そしてどういうふうに進めていかれるのかお伺いします。","respondent":"古川子ども未来事業部長","answer":"そうではないものについても、私どもは間違いなく一人一人のご意見をしっかり受けとめて、もちろん後日になる可能性は非常に大きいんですが、対応してまいりますよということでございまして、それを１０月から始めている。","voiceIndex":103,"id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"私たちは、当事者の相談のところと思っていたんですけれども、まずは気づきというところで、地域の人がどこに電話していいかわからないというところの情報収集の一つとして、この事業を始めたという考えであるということでよろしいんでしょうか。","respondent":"安井子育て支援課長","answer":"そういったことで、こちらで専用回線をつくって、そちらにお電話いただければ、より早く対応ができるというようなことで設けたです。","voiceIndex":105,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"じゃあ、これと離れて、先ほどこの電話番号では今のところ相談がないということでしたけれども、子育て支援課の方にそういう問題として、今、自分が困っているとか、そういう電話の状況というのはどういう状況にあるのか。推移とか変化があったら教えてください。","respondent":"安井子育て支援課長","answer":"６月の大阪の事件以来、非常に増えてきておりまして、児童相談所も同じような状況が続いているということで、職員も一生懸命頑張って対応に努めているというような話がありました。","voiceIndex":107,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問・要望","question":"周りからのそういう相談とともに、もしかして自分がとか、自分がそういう問題を抱えている人たちはどこに助けを求めるんだろうといったときに、電話相談というところに助けを求めるツールとしてそれが機能しているのか。そういう本人からの声というのは、普通、電話というもので届くんでしょうか。","respondent":"安井子育て支援課長","answer":"子育て支援センターでも声かけをして、養育が難しいようなケースについては継続的に見守りをやっていますので、そういった対応を図っているという感じです。","voiceIndex":109,"id":"exchange-046"},{"speaker":"金野委員","kind":"質問","question":"先ほどのご説明の中で、緊急時には１１０番をということで、通報された方が１１０番をしてくださいねという対応になってしまうんでしょうか。通報だけを受けて、どうするのかというふうに答えを返してしまうと、何のためのものなのかというところがあるので、その辺はどうでしょう。","respondent":"安井子育て支援課長","answer":"その際には必ず宿直から私のところに電話が入るということで、後のフォローで情報が確認できるように対応しています。あるいはうちから重ねて警察へお話をするというような形で対応することになっております。","voiceIndex":111,"id":"exchange-047"},{"speaker":"金野委員","kind":"質問・要望","question":"どちらかというと隠してしまうというのが現状かなと私は思うんですけれども、そのときに、周りの人に気づいていただくのに、このしながわ見守りホットラインを開設していますよということを早く周知していただくように、堺議員が質問した内容でもお話しさせていただきましたが、早急に周知をしていただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"私たちは前回も説明を受けましたけれども、見えないのは、どういう流れでどういう処理をするんですかということなんですよ。それで、１１０番なんていうのはすごく緊急度が高いですよね。そういう流れをまとめてもらえないですかね。１枚紙の資料みたいな形で示していただくと、私らもすごくわかりやすいし、説明しやすいし、区の方でもわかりやすいんじゃないかと思うんですがいかがでしょうか。","respondent":"安井子育て支援課長","answer":"どうしてもそこら辺の情報を得られる道をもっとつくらなければいけない。４万件とか、児童虐待についてはこれだけ言われておりますので、そこら辺について一歩踏み出して強化していこうという形で進めているです。","voiceIndex":114,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"ホットラインに行った情報がどういう流れでどういうふうに処理されているんですかというところが見えないので、仕組みがわからないと言っているんですね。「２４時間受けますよ」と。じゃあ、２４時間のみんながいないときにどういう流れで情報が行って、どういうふうに処理できるんですかということを知りたいんですよね。だからそこをはっきり説明してもらえるだけで安心するんじゃないんですか。","respondent":"安井子育て支援課長","answer":"基本的に、先ほど申しましたように、夜中の部分については、単なる情報提供であればそのまま翌朝私どものところへまわってきますので、それで対応していくという形になります。夜中、万が一という場合については、警察の担当に私が言う形になります。","voiceIndex":116,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"ということは、夜間については宿直室の警備員さんのところに入りますよということですよね。そこに入って、その人たちの報告は次の日に受けるものもあるけれども、基本的には、１１０番とかが必要なものについては緊急にやる、それは今までもそうだと思うんです。なので、基本的には次の日に報告を受けるという形になるという理解でいいですか。","respondent":"古川子ども未来事業部長","answer":"今回は、多分補正予算で、総務委員会でやっていると思うんですが、人権啓発課が全体の調整窓口になりながら、虐待にかかわる子育て支援課でありますとか、あるいは高齢福祉課でありますとか、そういった庁内において今まで個別に対処していたものを全体として整理をし。","voiceIndex":118,"id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"前に危機管理対策として、職員の方が夜間の当直みたいなのをやっていましたが、今もいらっしゃるのか。そういう方たちとは全然離れたところで宿直だけが夜間のところを受けようとされているのかということと、あと、今までどういう人が夜間のスタッフになっているんでしょうか。","respondent":"安井子育て支援課長","answer":"それについて電話を受けていただく場合は、「しながわ見守りホットラインです」ということで答えていただくという形になっています。ですから、ほかのいろいろな電話とはちょっと違う扱いをしていただくように対応できているということになります。宿直は総務課で委託しています。","voiceIndex":120,"id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"意見","question":"通報があったけれども入れなかったとか、そういうことがあってはいけないからこういうのをつけられたと思うから、そういう情報をどうきちっと管理して、分析・評価をして対処していく仕組みがちゃんとできていますかということ、答えていただければと思います。","respondent":"安井子育て支援課長","answer":"それについて、住所がどこだということで、例えばマンションのどこだということがわかると、そこで住民基本台帳とかをいろいろ調べさせていただいて、対象を絞って、そこら辺のところをわからない程度にこちらでも調査をかけて、具体的に特定して。","voiceIndex":122,"id":"exchange-053"},{"speaker":"伊藤副委員長","kind":"質問","question":"要はそこが一番根本ですよね。いろいろな話が入ってくるでしょうから、それを全部聞いてから対処していたら大変な話だから、それを冷静に聞き分けた上で、重篤なもの、緊急性の高いものを精選するべきであって、そういう仕組みを、今までのデータがあると聞きましたけれども、逆にこれからいろいろなところから情報が来るわけじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"そうすると、区立幼稚園に行かずに、私立にも行かずに待っているという方が多いということですか。公立がだめなので私立に行っているという方が多いのか。","respondent":"伊崎待機児童対策担当課長","answer":"お待ちいただいている方の数は少ないとは言えない数いますけれども、最終的に４月現在で１名から６名という形になっているんですが、私立幼稚園に行っていらっしゃる方がまれにいらっしゃいますが、多くは公立の第２希望の幼稚園に入られていらっしゃるとか。","voiceIndex":138,"id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":48364,"voices":141}},{"id":"h22-20101026-5","meetingId":"h22-cm10","date":"2010年10月26日","dateIso":"2010-10-26","committee":"総務委員会","time":"午後１時０２分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"意見","question":"個別の中身については別のほうでやっていただいているので。補正予算の性格上、これをどう考えるか。例えば、先ほどのモデル実施の場合は、金が出なくなったら、なくなってしまう。そうなると、今後の、来年度、再来年度の予算編成にある意味では枠をつけることになり得るので、この辺についてはどのように分析され、考えてやっていらっしゃるのかだけ聞かせてください。","respondent":"金子企画財政課長","answer":"高齢者世帯の２４時間対応訪問介護サービスモデル事業ですが、これは国のほうの１０分の１０事業として年度途中に出てまいりまして、実施するわけでありますが、これは今年度のモデル事業という形ですので、区としましてはこのモデル事業に対して今年度やりますけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"その意味で、１０分の１０もらってテスト試行、本当のテスト試行ですから、テストが終わったら一たん終わりと、それで新たな制度としてその同じものが来るかどうかわかりませんけれども、そういうものが考えられていくのだろうと思いますので、それはそういうことだということをしっかりお伝えしておかなければいけないという部分が残るのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"３９ページのここに豊町二丁目の用地取得の規模など、概要だけ教えていただきたい。","respondent":"金子企画財政課長","answer":"豊町二丁目の防災活動広場整備用地の取得ですけれども、これは住所で見ますと豊町二丁目５番１８号で、ちょうど戸越公園の南側のあたりに位置いたします。ですから大井町線の線路のちょっと北側となります。広さは約１３０m2になります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"この第７１号議案全体を通しまして追加で行うものであったり、あとは措置として新たな視点で取り組むものとかが多いと思うんですけれども、それに比べて生活保護など従来のカウントより見込みが伸びたというか、当然その４分の３は国から入ってくるんですけれども、数的にこの概算というか、見積もりより上回ったというような部分というのが、ほかにあるか、ないか。","respondent":"金子企画財政課長","answer":"当初予算で予定していた実績を超えた実績があって、やむを得ず補正を組むというようなお話だと思いますが、今回それに該当するのは児童扶養手当の部分と、それからご指摘の生活保護費の部分です。この２件になります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"防犯カメラは一定の防犯の抑止効果というのとあわせて、その裏腹にプライバシーの問題もあるんですけれども、映像の運用ルールといいますか、そういうのは区としてどういうふうな考え方があるか、ちょっと伺いたいと思います。来年４月は２つできるという発表があったんですけれども、今後の見通し。今年４月は４９４人入れなかったと。どういうふうになったのかということを伺いたいと思います。","respondent":"金子企画財政課長","answer":"ただ、国のほうがどういう年齢設定にしてくるかというのは、やはりそれと整合性をとらなければなりませんので、ある程度はっきりした時点で来年度の基本的な設定のところもまた検討する必要があるかなというふうには聞いてあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"子宮頸がんワクチンのところなんですけれども、国のほうもいろいろ予算化の動きがあるんですけれども、私は国が始めたときに区がどうするかということが、今、区の立場というんですか、考え方というのが問われてくるんじゃないかというふうに思います。そこら辺で何か考え方があったら伺いたいと思いますが、いかがでしょうか。","respondent":"金子企画財政課長","answer":"それから子宮頸がんワクチンの考え方ということですけれども、所管のほうから聞いているのは、先ほど申しましたとおり、中学１年生が基本的な考え方だよというふうに聞いておりまして、費用負担についても現在の形で聞いているところですので。","voiceIndex":14,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"全額助成は承知していないというのではなくて、要するに私は区の考え方がどうなのか、国が始めたら区のほうが引っ込めるというのではなくて、国が始めたら予算がそういう意味では増えるわけですから、全額となるかどうかは別としても、助成制度の拡大というか、充実と、そういう方向で考える必要があるんじゃないかと、そういう質問なので、ちょっとそれについてもう１度考え方を伺いたいと思います。","respondent":"金子企画財政課長","answer":"これは今、国のほうの厚生科学審議会の分科会のほうで定期化の検討も行っているようでありまして、これの中で費用の検討をあわせて行っているかどうかというのは承知していないんですけれども、少なくとも今後、そういうものも含めて国のほうが動いていくわけですから。","voiceIndex":16,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"本来はやはり国のほうに私は戻すべき話じゃないかなと、区でその分どんどん負担していったら、かなりやはり支出負担、財政負担が増えていくと思うんですが、この辺に対して区から国のほうへお願いするというような、そういう各自治体がもちろん関係あると思うんですが、そういうことというのは動きがあるのでしょうか。","respondent":"金子企画財政課長","answer":"生活保護のほうの問題ですけれども、ご指摘のとおり、増えれば増えるほど４分の１負担は各市区町村の負担になっております。そこで全国市長会でも、こういった状況では市区町村の負担増が免れませんので、抜本的な制度改正を国のほうに要望しています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認で、また教えていただきたいんですが、おさらいの意味でまず最初に、当初予算と補正予算とのいわゆる考え方といいますか、大概当初予算が編成されて発表があって、その後第３回定例会、毎定例会ごとに必ずと言っていいほど補正予算が出るということから行くと、その辺の当初予算では組み込めなかった、あるいは想定できなかった事案が発生して。","respondent":"金子企画財政課長","answer":"年度に入りまして、やはりどうしても事情の変化、この中でも実績増になるもの、あるいは事故が起きてそれに対応しなければならないもの等々が出てきてまいります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"これは歳入のところで言っている民生費補助金で安心こども基金交付金として３分の２の補助、それから例えばもう１つは待機児童解消区市町村支援事業補助金というところでは、区内の私立保育園経費として補助基本額が４分の３で１億円ちょっと計上されているのと、それから１０分の１０という補助で１,２５０万円出ているのと、こういうお金はどういうところに手当てされていることになるのですか。","respondent":"金子企画財政課長","answer":"この私立保育園の開設準備経費の補助なんですけれども、かなり複雑になっていまして、ちょっと説明がうまくできるか難しいんですけれども、安心こども基金のほうは上限額が決まっている中で、もともとは国から来たものなんですけれども、東京都のほうで基金を設置していまして。","voiceIndex":22,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから来年１月からでしょう。ですから、今申し上げたように、接種が３回必要となると、３カ月間で３回はできないでしょうね。そういうこともありますので、そんなところも含めて、国の動向を見守りながらということでもありますので、それも含めて区の事業としても積極的にこの件についても取り組んでいただきたいなと、要望も含めまして何点か教えていただきたいと思います。","respondent":"金子企画財政課長","answer":"それから２０歳の女性が１,５００人、合わせて約５,０００人いらっしゃいまして、接種の見込み率が他の任意接種と同程度と想定いたしまして３０％で、１,５００人というふうに想定しています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"所管外で大変申しわけないのですが、ワクチンの接種についてはそういう方向でぜひまた取り組んでいっていただきたいと思うわけですが、１つ、この予防という視点からいきますとワクチンの接種と、それから検診というのが同時に必要なんだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"林委員","kind":"質問・要望","question":"各委員会で、もうされたと思うんですけれども、ちょっと聞かせていただきたいのは、この３３ページの手当の支給というところで、全部支給が延べマイナスの５９２人、これは補正予算なので、予定として何月から来年の３月３１日までという、そういう日にちの問題をまずは聞かせてもらえますか。","respondent":"金子企画財政課長","answer":"児童扶養手当ですけれども、これは支給月が４月、８月、１２月の年間３回になっています。ですので今度の１２月期、これの対応としまして、１２月からの対応としまして、今補正予算をお願いしているところであります。","voiceIndex":27,"id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"そうすると、ちょっと細かい話で申しわけないんだけれども、延べマイナス５９０人というのは、１２月、１月、２月、３月、４カ月分という単純計算をしていいわけですか。それともう１つ、ちょっとここで聞いていいのかどうかわかりませんけれども、父子家庭は品川区にどのくらいのパーセンテージでいらっしゃるのですか。","respondent":"金子企画財政課長","answer":"父子家庭全体、区の父子家庭がどれくらいかというのは、正確には難しいかもしれませんが、これの手当とは別に児童育成手当というのがありますけれども、こちらでは１３８人ほどいますから、こちらはまた所得制限等があるので１００人しか該当しないのですけれども。","voiceIndex":29,"id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"わかりました。それから、これは３９ページの用地の取得で説明いただきました。それで、いわゆる国、都から５,８００万円強で自主財源というか、品川区の財源で３,２６０万円強。もうちょっと逆に言えば、９,１４０万円の土地の価格だから、品川区は買ってもいいよという、そういう話になって取得をして、結果的に補助金が後からついてきた、そういう考えになるわけですか。","respondent":"金子企画財政課長","answer":"委員ご指摘のとおりの流れで判断して、用地取得することになったわけですけれども、都の補助等、国の補助等では３分の１ずつで、残る３分の１も財調のほうで措置されますので、そういう意味では純粋な一般財源の負担はないものですから。","voiceIndex":31,"id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"そうすると、土地を購入する場合に、区としては財産価格審議会、いわゆる区として取得をしていいですよとオーケーが出る価格、全体の価格があって、後から、単純に言うとそれが１億円だとすると、この１億円に対して補助金がどのくらい出るのかという申請という言葉なのか、どういう言葉を使うかわからないけれども、補助金を申請して、３分の１は品川区が持つという。","respondent":"本間副区長","answer":"財産価格審議会の委員長を私は務めておりますので、私からお答えしますけれども、区が不動産を購入する場合、これは第三者で要するに専門家ということで不動産鑑定士３人から構成されております財産価格審議会、こちらに、要するに土地の購入価格の査定をしていただくです。","voiceIndex":33,"id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"そうすると、補助金というのは後から、土地の価格が決まった後に、これは国から幾らくらい出るよ、これは都から幾らくらい出るよという、そういうカウントをして申請をするということになって、あくまでも総額的な問題だけを品川区の財産価格審議会では結論を持つと、そういう考え方でいいのですか。","respondent":"本間副区長","answer":"おっしゃるとおりでございまして、ただし、この防災生活圏のエリア内の土地を購入する場合は、先ほど企画財政課長がお答えしたような、そういう助成制度がありますので、限られたその防災生活圏というエリア内の土地を購入する場合には。","voiceIndex":35,"id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"もう１点、これは前もってお聞きをしておかなければいけないなと思っているのが、繰越金なんですけれども、いわゆる２４億円が当初予算として繰越金という計上をされていて、ここでは４億９,７９７万６,０００円が補正額で上がってきて、純粋に平成２１年度の補正が４億９,７００万円強という計上があって、ここに載ってきたわけですよね。どうでしょう。","respondent":"金子企画財政課長","answer":"その後、これからご審議いただくわけですけれども、決算のほうの段階で、繰越金が２８億円余ございました。そのうちの今回はうちの金額で４億９,７９７万６,０００円を計上するというふうな経過になっております。","voiceIndex":37,"id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"そうすると、４８ページは、これは国保のほうの補正予算ですね。第７２号議案になりますから、後でまたお聞きします。それで補正予算のかかわりが、一般会計では、この補正予算に係る約４億円のお金は補正予算として計上しているというだけの話ですね。一般会計予算では、補正予算として計上されているというだけで、認識を持っていればいいわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"３５ページの子宮頸がんのワクチンで、さっき課長が説明しているときに３回打たないと効き目がないよという、否定を完全にされていたんだけれども、そうすると１回目を受けた人、２回目を受けた人が３回目を受けなかったらむだになってしまうよという、そういう意味に受け取っていいんですか。","respondent":"金子企画財政課長","answer":"私どもが聞いているところによれば、先ほど申しましたとおり、期間はあります。初回から１カ月、初回から６カ月の計３回で、このワクチンとして効果が発揮できるのは、この３回打たなければならないというふうに聞いているところです。","voiceIndex":42,"id":"exchange-020"},{"speaker":"林委員","kind":"意見","question":"そうすると、３回分費用を先に取るということをしなければ、効かないのに１回目でやめてしまうということは、非常にむだが出るということにならないか。ここでやる話なのか、総務委員会で取り上げる議題になるのかどうかわかりませんけれども、３回やらなかったら３回分お金をもらってしまったほうがいいんじゃないのか。効き目がないということならば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-021"},{"speaker":"林委員","kind":"意見","question":"ここでやるとおかしくなるかもわからないんだけれども、後で「知らなかった。そのときに、普通だと１回でオーケーになるようなのが、３回やらないと効き目が出ないですよというのを後で言われて、「最初に聞いておけば、３回ちゃんとやったのに」ということにもならないかなという、これは厚生委員会でやる話になるのかもわからないですが。","respondent":"金子企画財政課長","answer":"その辺のところは所管のほうでも何らかの対応を考えていると思いますけれども、また確認させていただければと思います。","voiceIndex":47,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"賛成ですが、ちょっと１点だけ意見を言いたいんですけれども、先ほど保育園の件は、区のほうでは、保育園はつくらない方向だということなんですけれども、やはりそれは区としてしっかりつくるということがなければ、私立を待っているという方向だけだと、なかなか今の事態を改善できないので、そこの点だけは改めて述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"さっきの続きみたいになるのですが、４８ページ、４９ページの繰越金が、次のページの総務費の一般管理費の電算システム改修費と、これは同額になっているんだけど、偶然なんですか。繰越金をここにそっくり補正予算で総務費の一般管理費に入れるという、偶然なのか、やむを得なくここに同じ額が出たというふうにとればいいのか、それを聞かせてください。","respondent":"金子企画財政課長","answer":"先ほどもちょっと「うち」という言葉を使ったんですけれども、繰越金は実はこれ以上ありますけれども、ただ今回の補正予算として歳出を予定しているのが５,５６０万円ですから、この歳出予定の分だけを今回繰越金として歳入のほうの補正にも計上させていただいたという形です。","voiceIndex":57,"id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"そうすると、へそが曲がって考えると、流用だと。突然必要な額が出てきたので、流用もできる金額がないから繰り越してしまうという仕組みで、繰越金を計上して充てるという、そういうふうにとってしまっていいですか。そんなことをやっていいんですか。もし、そうだとしたら。","respondent":"金子企画財政課長","answer":"今回どうしても年度途中でこういう歳出の必要性が出てきました。それは、その繰越金の相差の中でおさまるものなので、その分今回の歳出に応じた分だけを歳入のほうの繰越金で計上させて、歳入と歳出を同額にしているというふうな形で補正の計上をしているものです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"林委員","kind":"意見","question":"これを流用していく、流用という言葉を使うから、おかしな話になるのかもしれないけれども、どうしてもこの５,５６０万円の改修費をどこかで立てなければならないとすれば、私はこれはおかしいと思う。予算、それから予算から成り立っている施策の実施ということについて、どうしても使いたくなるよね、「流用」という言葉を。","respondent":"日下部企画部長","answer":"これは毎年度の当初予算で、一定の繰越というのを見込めるわけですけれども、ただ、これは今もご説明させていただきましたけれども、これを過大に見込むということになりますと、逆にいろいろ財源的な面で不都合が出てきますので、少し堅めに見込んでおくわけです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"林委員","kind":"質問","question":"年が明けて３月、５月。そこでもう１回繰越金というのを立ててくるわけですか。立ててくると言うか、計上してくるわけですか。だったら、その３月の、５月の時点で、繰越金が計算されてきたのなら、その額を繰越金として入れるべきです。この５,５６０万円を必要になったから、５,５６０万円を繰越にこの中から入れておこう、あとは３月に計上すればいいやという、まさしく私は流用だと思う。","respondent":"日下部企画部長","answer":"もしこれが、プラスアルファが出てこなければ、実は歳出予算の財源というのは出てまいりませんので、今度はまた別の選択を、幾つかの選択がありますが、これを考えるしかないというようなことですので、前年度の決算と当該年度の予算の関係がちょっとわかりづらい面がありますが。","voiceIndex":63,"id":"exchange-027"},{"speaker":"林委員","kind":"質問","question":"この５１ページにある電算システムの改修ということは、この時期にやらなければならない改修なんですか。それとも平成２３年度の予算が立った時点で、あるいは繰越金をこういうふうにここに回すというのなら、なぜ本会計からの繰入金を充て、予算計上して、それを充てていくという、この改修費というのを繰越金でまかなうというのがどうも腑に落ちないんだ。私は流用しているというふうに受けとめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"２つの数字をなぜ持ってくるんだということなんです。繰越金と、この改修費と同じ額を。繰越金が例えば６,５００万円あって、繰越金が６,５００万円計上してあって、ここで５,５００万円なら、それならわかるんだけれども、ぴったり繰越金を流用しているというふうにとるじゃないですか。","respondent":"日下部企画部長","answer":"もう１度ちょっと申し上げますと、国保会計については、さっき企画財政課長もご説明させていただきましたけれども、実は繰越金が国保会計の場合、当初２億円くらいで組んでいたものが、これが大体１０億円を超えるくらい繰越金が出てまいります。最終的な、いわば余剰分です。","voiceIndex":68,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"それとあと、レセプト電算化というのはずっと準備されてきたわけですよね。この時期で何が必要だったのかというのがよくわからないんですけれども、たしかこれは既にもう昨年あたりから始まっていたのではないかと思うんですけれども、これが今やる必要があるというのは何なのかというのをちょっと伺いたいと思います。","respondent":"金子企画財政課長","answer":"全体に大きな流れでシステムを改修していかなければならないので、その仕様についても徐々に明確になってきているところがありますので、今回のところはちょっと部分的な話で申しわけないんですけれども、国保給付の中のキー項目を国のほうで、国保連のほうで変更していると。","voiceIndex":71,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"確認","question":"システムについて、いろいろ徐々に変わってきているみたいなことで、一気にこういう形でやりますということじゃなくて、国のほうからも小出しみたいな、そんな感じでどんどん変更されてきているのか、それはどうなのかなと、そこを確認したいのと、あと失業者のほうなんですけれども、一番聞きたいのは、今まで保険料の減額内容等は、天災とか、そういうところだったと思うんですけれども。","respondent":"原情報システム課長","answer":"１点目のレセプトの関係で情報システム課のほうからお答えします。そもそもこの制度は平成１７年の医療制度改革、その中で現行、今までのレセプトを電子化していこうと、それについては平成２３年度から全部が電子化するようにと、こういうような国の方針がございました。","voiceIndex":73,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問・要望","question":"開業医をやめる理由というのがここに書いてあるんですけれども、やはり導入に見合う収入がないと、そういう答えが非常に多くて、４４％もこの保険医協会の調査でそういう結果もあるので、今一方で保険点数もぐっと少なくなってお医者さんのほうの収入も少なくなっているので、ぜひそういう実態も開業医の先生に一番近いところ、区のところでもやはり調べていただきたいと、これはちょっと要望ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"これは５８ページに書かれているのは補正前の額がゼロなんですね。だから２目保険給付費負担金等償還金というのは予算に載っていない目なのだけれども、それを突然繰越金を計上してこれに充てる、突然降ってわいた目なのですか。当初予算を立てたときには考えつかなかったものが、ここへ来て出てきたという、これはそういうふうな理解を私たちはするものなのですか。","respondent":"金子企画財政課長","answer":"これは右側の説明欄にもありますとおり、精算にかかる返還金で、今回は返還金であります。","voiceIndex":84,"id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"繰越金のほうは、さっきの話でわかりました。この返還金というのは、科目存置でも１,０００円くらいでよく当初予算には入る場合があるんだけれども、ゼロのままというのは品川区の財政担当者としては間違って１,０００円科目存置するのを忘れたというふうに受け取らざるを得ないような感じなんだけれども、そうではなくて、返還金の反対を言うと収入金が生まれる場合もあるわけですか。","respondent":"金子企画財政課長","answer":"今回はあらかじめいただいていたものが、精算した結果、多過ぎたということで返すという形になっていますけれども、さまざま国からの支出金というのはあるんですけれども、こういう毎年度毎年度確定してからいただくというのでは遅過ぎますので。","voiceIndex":86,"id":"exchange-034"},{"speaker":"林委員","kind":"確認","question":"１つだけ確認だけさせてください。このゼロという、科目存置されないまま、この時期に来て補正予算でポンと挙げてくるというのは、法的には認められている作業なんですね。","respondent":"金子企画財政課長","answer":"きちんと、そういう意味では補正予算として計上しておりますので、これは間違ったやり方ではありません。","voiceIndex":88,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"今の時期の国への返還ということですけれども、都への返還というのは時期的にはどんな感じになるのかというのを１つ聞きたいのと、これはもちろんあれですよね。要するに当初の事業費の見積もりで国からもらってきたのが、使わなかったということなんですけれども、そこの主な使わなかった内容というか、きょうはそこら辺のところをちょっと所管のところではないので、もしわかったら伺いたいと思います。","respondent":"金子企画財政課長","answer":"そういうのをかなりさまざまな事業を計算した結果、こういうふうになって、１つの事業ではないものですから、細かいことは大変申しわけありませんが、ご容赦願いたいと思います。","voiceIndex":90,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"基本的には介護給付のほうが減っているので、こういうふうに返還ということになるんだろうと思います。そういう意味では、２３億円を超える金をためているわけですから、私は特別養護老人ホームの増設等、やはりもっとサービスを充実するという方向に頭を切りかえていくということをここで言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-037"}]},{"id":"topic-02","title":"本日は、所管事務調査といたしまして、都区制度のあり方","agenda":"本日は、所管事務調査といたしまして、都区制度のあり方","exchanges":[{"speaker":"土井委員","kind":"質問","question":"それぞれ移管の具体化に向けたさまざまな課題等が今整理されている、されつつあるわけですけれども、と同時に品川区のように先取りして進めるような形の部分というものも各区によって違いがあるけれども何か取り組みをして、都をみんなで包囲網で追い込もうというような発案なり、行動なり、似たようなものはどうなのでしょうか。","respondent":"濱野区長","answer":"先ほど、５３項目についての事前検討をしていこうよというふうにご提案をしたときに、いろいろ議論があったということを申し上げましたけれども、端的に言うと「やってもむだじゃないの」という、そういう趣旨の発言がありました。","voiceIndex":105,"id":"exchange-038"},{"speaker":"林委員","kind":"質問","question":"だから区長会、特別区協議会である程度先を読んで、新しく４年間始まるわけですから、そのときに、スタートダッシュよく、都に働きかけるというか、そういうことも考えなければいけないんじゃないのかなという気がするんですけれども、さっき口走った何人かのわき見をしている区は置いておいて、前を向きそうな区に働きかけるというのはできるものなのですか、無理ですか。","respondent":"濱野区長","answer":"わきを向いているとか、そっぽを向いているということではなくて、これは戦略的なことだと思うんですけれども、先ほど申しました５３項目について事前に検討するということについては慎重な区と、やることはどんどんやっておいたほうがいいのではないかという区と。","voiceIndex":107,"id":"exchange-039"},{"speaker":"林委員","kind":"質問・要望","question":"区と都というのは。最終的に国が乗り出してきて、どうする、こうするという段階に行かなければ、前へ進まないというふうに思いますので、ご苦労は多いと思うのだけれども、意欲の見えないところは意欲をたき出すような、いろいろな作業をしていただきたいというふうに思いますので、お願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-040"},{"speaker":"土井委員","kind":"質問","question":"今の課題の整理を行って、これが後々役に立つというふうに私も思います。課題の整理をというのは、これは区側の立場で、この課題についていろいろ考えたわけですね。それはこれで我々で一生懸命考えてきたんだから、お前のところもこれを出せと、次のスタイルに持っていかなければいけないんだろうと思うんです。そこら辺に対する働きかけと感触みたいなものがあればお伺いしたい。","respondent":"濱野区長","answer":"先ほど一番最初のところの検討委員会のところでご説明申し上げましたけれども、「また、具体化を行うための実務レベルの検討体制を検討する」という文言があります。","voiceIndex":110,"id":"exchange-041"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの、例えば児童相談所の問題ですと、今大きな問題になっているので、やはりより身近なところでやろうというのは、児童相談所の問題でいけば、かなり理解されるというのがあるんだけれども、では５３項目、ほかの問題がバッと、マスコミですとか、世論に訴えるとやったときに、本当に力になるのかなというところは、そこのところは私もよくわからないんですけれども。","respondent":"濱野区長","answer":"一番具体的な課題ということで、１つの象徴として児童相談所の問題がありますけれども、この問題は、長年言われていることですけれども、やはり二元的な対応をやっていますから、どうしても両方で譲りっこしてエラーになってしまうというような。","voiceIndex":112,"id":"exchange-042"},{"speaker":"宮崎委員","kind":"意見","question":"でも、肝心な区域の問題とかとあわせて、じゃあ、この５３項目を一応準備してやっていくんだよということなんだけれども、これが本当にわかりやすい形で住民に訴えられるというか、どういう角度で訴えてくるのかということなんかが、しっかり伝えないと、逆に、やっぱり世論というのはどういうふうにも絡んでいくので、今逆にやはり大阪なんかだとああいう、こちらから見れば逆方向へぐっと行く流れというか。","respondent":"濱野区長","answer":"新聞なんかにも時々載りましたけれども、今の２３区はこんなふうに再編したらどうだろうかと、絵にかきやすい話題ですから、それを持ち出されると、我々としてもちょっと厄介な問題だなというふうには思っていますけれども、それについては。","voiceIndex":114,"id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問","question":"私はちょっとマスコミのという話があったので、気になったんですが、先ほどの林委員のほうからもあったんですけれども、以前は期成同盟をやって、やはり住民を巻き込んで本来のあり方はどうなんだということを、住民の中でも世論をつくってきて、それがこういう形まで来ているわけですから、私は世論をつくっていくという点では、そういうオーソドックスなやり方というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"こういう移管事務に対しては、例えば東京都から区へ移管された場合に、東京都とすれば移管したほうが経費が削減できる、事業が幾つもあって、そうしたほうがいいですよというような、そういうランクづけ、点数づけというのがあるんでしょうか。そうじゃなくて、一応こういうものだったら区でできますよと、区とすれば、その東京都の予算をそのままそっくりもらうという考え方なんでしょうか。","respondent":"濱野区長","answer":"お金の話が絡んできますので、今、お金の話は一応事務配分の議論が終わった後に税財政のことについてはやりましょうという仕切りになっていますので、ちょっと一緒になってしまうと議論を進めていくのが難しいんですけれども、東京都は東京都で、本当はやめたいんだけれども。","voiceIndex":117,"id":"exchange-045"},{"speaker":"須貝委員","kind":"意見","question":"逆に向こうが逼迫して、「これをやっぱり」と言うようなタイミングをねらって、「じゃあ、これを条件に受けますよ」とか、何か必ずパッケージでうまくこちらに引き出せて、最終的にあまり区も、受けるのはいいけれども区の負担が多過ぎたら困るし、逆にマイナスになったら、それはまた困っちゃうことだと思いますので、どうぞ当面の間は慎重に進めていただいたほうがちょっといいような気がしますので。","respondent":"濱野区長","answer":"１回とまったら、もうこの話は１０年、２０年持ち出せない話だと思いますので、やはり向こうがゆっくりだったら、こっちは少しねじを巻くくらいでちょうどいいのではないかなと思いますので、本当はもっともっとどんどん話を進めたいですけれども。","voiceIndex":119,"id":"exchange-046"},{"speaker":"堺委員","kind":"確認","question":"そういう面から見ると、これもさっきおっしゃっていたように、こちら側が、要するに区長会側が緩めちゃうと、もう場合によっては１０年、遅々として進まないんじゃないかという話を区長がされたように、やるときに一気にやっていかないと、途中でもう終わっちゃって、結局意図するところがしり切れトンボで終わってしまうんじゃないかなと、そんなことも今思って、３年半、当初の予定からいくと。","respondent":"濱野区長","answer":"それとやはり私は、個人的な思いになるかもしれませんけれども、このあり方検討というのは高橋前区長がいわゆる主要５課題の整理に当たって、本当に命をかけてやり通した主要５課題の中で。","voiceIndex":121,"id":"exchange-047"}]},{"id":"topic-03","title":"」を聴取いたします。 初めに、(1)の「新地方公会計制度に基づく財務４表","agenda":"」を聴取いたします。 初めに、(1)の「新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"１点だけ。これは総務省の方式でやったと。２３区のほうも基本的にこれと同じ様式でやっているのか。それと、あと２３区の横並びで見られる、そういう資料というのはあるのかないのか、その点だけ教えてください。","respondent":"金子企画財政課長","answer":"全部確認したわけではないんですけれども、２３区のほとんどが、この同じ方式、総務省方式改訂モデル、たしか全部だったような気がするんですけれども、ほぼ全部がこの方式を採用しております。","voiceIndex":132,"id":"exchange-048"}]},{"id":"topic-04","title":"の「品川区配偶者暴力対策基本計画（案）に対するパブリックコメントの実施について」","agenda":"の「品川区配偶者暴力対策基本計画（案）に対するパブリックコメントの実施について」","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"そこのところの対応と言いますか、こちらが「待っているよと」いうふうにしていても、実際上、知人とか、兄弟とか、そういうところには行くんだけれども、やはり実際に開いているこっちのほうに来てもらわないと、なかなか解決できないんじゃないかなと思いますけれども、そこら辺のことをどういうふうにしていくのかなということですけれども。","respondent":"中山人権啓発課長","answer":"こちらはちょっと１７ページのところをご覧いただきたいんですが、「人権に関わる意識調査」のほうの先ほどちょっと割愛させていただいてしまったのですが、もし、ＤＶについての相談を受けたことがある人。","voiceIndex":138,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひそういう啓発をどんどんしていただきたい。何かあればお願いします。","respondent":"中山人権啓発課長","answer":"相談という形で何カ所かでやってはいるんですけれども、今後、配偶者暴力相談支援センターの機能をどう設けていくかという話と、それからＤＶの出前講座みたいなものも考えておりますので、そういった、こちらのほうから地域に出ていったところで。","voiceIndex":140,"id":"exchange-050"}]},{"id":"topic-05","title":"の「平成２２年特別区人事委員会勧告の概要について」","agenda":"の「平成２２年特別区人事委員会勧告の概要について」","exchanges":[{"speaker":"土井委員","kind":"質問","question":"毎度のことなんですけれども、勧告が出ると、それに対して職員組合等々やるんですけれども、そこがどのようになっているか。品川区の場合ですと、職員と言っても若干みんな違うから、違ったグループに属される方もいろいろあるわけで、そこら辺との兼ね合いはどのようになって結論になっているのでしょうか。","respondent":"榎本人事課長","answer":"その交渉が妥結した段階で条例等のところの手続きに入っていくというような形で流れていくものというふうに考えています。","voiceIndex":146,"id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"地域手当というのは、現行１７％から１８％に引上げとなっているところで、その地域手当とは何なのか、その正確な意味を、ちょっとそこのところを教えていただきたいんです。","respondent":"榎本人事課長","answer":"東京都特別区の地域については１８％ということになっておりますので、それに合わせて１８％になるよう順次改正を行ってきて、１８％が特別区の地域の本則という形になっています。","voiceIndex":148,"id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"大都市はいろいろ、物価がちょっと高かったり、そういうことなんだろうと思うんですけれども、それはやはりそういうことで手当が出るのであれば、それに見合ってその同額減らしていくというのが、やはりそうなると今度は手当の意味といいますか、何なんだろうなと思うんですけれども、そこのところはどういうふうな説明になるのでしょうか。","respondent":"榎本人事課長","answer":"もともとが本給に対しての手当という形で大都市調整手当という形で入っておりましたので、その部分の考え方を引き継いでいるというふうに考えております。","voiceIndex":150,"id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"これはここで言ってもしようがないんですけれども、これからのいわゆる労使、こういうのはどういうふうになっていくか、それを見たいと思います。非常に今回も大分大きな減額ということになっていますけれども、私は１つは、先ほど財務諸表のところでもありましたけれども、かなり黒字がガッと出ているという中で、その一方で職員の給料が減っていくと。これは感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-054"},{"speaker":"須貝委員","kind":"質問","question":"我々が得ている情報、新聞報道でも、民間給与というのは、昨年５.５％下がっているというのは新聞でも報道されていますが、それに対して人事院勧告は今回１.５％という話が、今回は品川区のほうは１.６％という形で勧告の概要に沿って動くという話ですが、その約４％の差があるというのは、そういうことに関してそのまま、これは人事院勧告なんだから、それに沿って各自治体は動くのかと思うんですが。","respondent":"榎本人事課長","answer":"特に、同じ国税庁の調査の中でも、従業員が１,０００人以上の規模の男性職員ですと、年間５９２万４,０００円、先ほどの厚生労働省の調査ですと、従業員１,０００人以上になりますと７７６万円という形の数字が出てきますので。","voiceIndex":153,"id":"exchange-055"},{"speaker":"須貝委員","kind":"質問","question":"今、よくわかりましたが、ただ我々区民は、実際給与をもらって日常生活を営んでいるわけですが、その中にはもちろんアルバイト、非常勤の方もいらっしゃると思います。実際、国税庁で実態調査をして民間給与の額が国税庁、国の特に税金を扱っているんですから一番間違いないところで５.５％下がっていると言って、そのはっきり数字を押さえているわけですね。税金という形で給与の実態を押さえている。","respondent":"榎本人事課長","answer":"そういった中での全国の平均値という形になりますので、先ほど私が申し上げた厚生労働省のほうの賃金構造調査は、各都道府県別に出ておりますので、東京都の地域で見るとかなり高くなっている形なので、なかなか全国平均のものをベースに持ってくるか。","voiceIndex":155,"id":"exchange-056"}]},{"id":"topic-06","title":"の「南大井六丁目区営住宅耐震改修その他工事請負契約について」","agenda":"の「南大井六丁目区営住宅耐震改修その他工事請負契約について」","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"この住宅は築何年たっているのかと、あと、外フレームと建物を圧着というのは具体的にどういうふうな方法でつくるんでしょうか。","respondent":"宍戸施設整備課長","answer":"何種類か工法については検討したんですけれども、ちょうど青陵学園でやっているような、ああいった斜め材を外側に足していくというふうな工法も検討したんですけれども、やはり住宅だということで居住性や何かを考慮いたしまして。","voiceIndex":161,"id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"外フレームと建物の接合といいますか、それは具体的にこの場合はどういうふうにしていくか教えてください。","respondent":"宍戸施設整備課長","answer":"アンカー打ちなどをするのに加えまして、鉄筋や何かもぐっと引っ張りながら圧着した状態で、かなりモルタルよりも圧着性のいいコンクリートを流し込むというふうな形で、非常に強いモルタルで圧着させるというふうな工法で密着させるというものです。","voiceIndex":163,"id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"すみません。１点だけ。その１とその２を入札をやって、それでその１でＮＩＰＰＯが落札したので、その２のほうは資格基準で無効というふうにしたんですけれども、たまたまこれは一緒の日だったからそうなのか。例えば、普通で考えれば両方一緒にやりたいというのが出てくると思うんですけれども、この場合、一緒の日だったからだめだったのか、そこら辺の考え方はどうなのでしょうか。","respondent":"阿部経理課長","answer":"今回の工区を２つに分けた理由は、工期の関係です。要するに１月３１日までに完成しなければ、それ以降の管の入れかえ、あるいは道路整備が予定どおり終わらないということで、工区を２つに分けたということです。","voiceIndex":169,"id":"exchange-059"},{"speaker":"林委員","kind":"質問","question":"この電線の地中化に関係してくるんだけれども、ここも電線は全部道路の下に入るわけですよね。今、２カ所、北品川と戸越とをやっているんだけれども、相当ずれが起きているんですよね、工事、特に戸越のほうが１年くらいずれている。ここの工事については、従来商店街であったわけですよね。その商店街の人たちは、街路灯のことだとか、そういうことについての話は上がってきていないのですか。","respondent":"阿部経理課長","answer":"その調整にかなり時間がかかって、当初よりおくれているというふうに聞いておりますけれども、今回のところにつきましては道路を新設するという場所ですので、今おっしゃった２カ所とは大分様子が違うというふうに所管からは聞いております。","voiceIndex":171,"id":"exchange-060"},{"speaker":"林委員","kind":"質問","question":"そうすると、商店街の皆さんの意見も吸い上げておいてあげてほしいなと思いますので、お願いをしておきます。これから始まる工事でしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-061"}]},{"id":"topic-07","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"林委員","kind":"質問","question":"本庁舎の耐震工事を進められているんだけれども、リボンの上、労政棟を出たところの３階に環境情報活動センター、防災センターに今まであったものが１１月１日から移るということだそうで、私たちはまだ初めて知ったような状態ですし、防災センターは耐震工事はやらないことになっているんだけれども、中のレイアウトをここに移していくというのは、我々に教えてくれるということはないんですか。","respondent":"阿部経理課長","answer":"もう１点、なぜかということなんですけれども、実は耐震工事を第三庁舎は終わりましたので、庁舎全体の有効活用、どういうふうにしたら一番使い勝手がいいのかという検討をいたしました。","voiceIndex":182,"id":"exchange-062"},{"speaker":"林委員","kind":"質問","question":"おっしゃることは理解して、そうですかということだけど、年に１遍、しながわ中央公園で環境フェアというか、今は名前が大分変わっているんだけれども、そのときに防災センターの従来の場所にあると、一体化されたイベント開催になるんだけれども、こっちに移してしまうと、環境フェアのときに間にいろいろ入ってしまうという心配があるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":75258,"voices":185}},{"id":"h22-20101027-14","meetingId":"h22-cm10","date":"2010年10月27日","dateIso":"2010-10-27","committee":"行財政改革特別委員会","time":"午前１０時０２分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"杜松小学校ですけれども、プールはどうするのかなというのが１つと、あと、既存校舎を改修して利用するということなんですけれども、耐震改修は既にされていたかどうかの確認と、また、築年が、増築はあったという説明がありましたけれども、昭和３４年と、わりと古いんですけれども、これを改修して活用していくということなんですが。","respondent":"久保田行財政改革担当課長","answer":"１点目、プールについてですけれども、まだ跡地活用の改修の設計等については、今後の協議の中で詳細に詰めていく予定ですので、ちょっとプールの位置づけについてはどうなるかというところは、現時点ではまだ確定はしていないです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"プールの件は、いろいろな地域要望がこれから出てくると思いますので、ぜひそちらも耳を傾けていただいた上で要望を取り入れる方向で検討していただきたいと思います。それは、荏原第四中学校と杜松小学校のほうをそれぞれお願いします。","respondent":"久保田行財政改革担当課長","answer":"検討の経緯ですけれども、こちらにつきましては７月の本委員会でもご説明させていただいたと思いますが、私ども、庁内に区有施設跡地活用検討委員会を立ち上げまして、そちらの中で全庁的に調査いたしまして、この杜松小学校・荏原第四中学校の活用について調査いたしました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"杜松小学校の検討経緯ですけれども、庁内の検討委員会はいつ立ち上がって、だれが入っているのか、あと、地元の要望との関係なんですけれども、地元の方々から「どうなるんだろう」という質問をいただいていたという話がありましたけれども、例えば「こういうところにしてほしい」とかという、何かそういう、今まで地域の人たちの要望を聞くような、そういう検討の機会はなかったのか。","respondent":"久保田行財政改革担当課長","answer":"その後、いろいろと青稜高校でも老朽の改築計画等を進めてこられたのだと考えていますが、そうした中で、やはり改めて本年、平成２２年９月に、青稜高校から協力してもらいたいと改めて要請をいただきまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、検討の俎上に上がっているものは、何か具体的にどういうものがあるのかお伺いしたいのが１点と、あと、やはり日常的に仕事をする中でいろいろ要望などは伺っているんですということですと、ちょっとやっぱり跡地活用、これはあくまで案ですから、検討するに当たってやっぱり不十分ではないかと思いますので、正式にといいますか。","respondent":"久保田行財政改革担当課長","answer":"検討委員会についてお答えいたします。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の活用案に関しては、昨年も行財政改革特別委員会で委員会としての意見を出して、高齢者施設等ということも入っておりますので、方向性としてはもちろん賛成なんですけれども、今回、特別養護老人ホームが小規模特別養護老人ホームになった、小規模多機能との組み合わせになった、具体的には案ですけれども、こういう案が出てきたわけですが、特別養護老人ホームが小規模になったその経緯というんですか。","respondent":"久保田行財政改革担当課長","answer":"その一方で、杜松小学校周辺はやはり密集市街地ということもありますので、そういったところの観点からも一定のそうした広場的な機能を持った場所も必要だろうという中で、既存の校舎を活用しながら特別養護老人ホームを整備ということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"井上委員","kind":"確認","question":"この大体のところの概要というものが、今、初めてお伺いした形になるかと思うんですけれども、住民への周知というところでパブリックコメントを行うことも考えているということだったので、どういうスケジュールで今後これが確定というところまで行くのか、ちょっとその辺の先を見通したスケジュールをまず確認させてください。","respondent":"久保田行財政改革担当課長","answer":"そうしたものを踏まえまして、できますれば今年度中に利用計画案の方向性なりを決定していきたいと考えておりまして、利用計画案の方向性がある程度まとまった段階で、できれば今年度中にパブリックコメントをかけて。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"提案","question":"もうそこはひっくり返らないよということなのか、意見聴取といっても、こういう案になったときに、大きく反対であるとか、もうちょっと違うというような具体的な提案があった場合には、それもありなのかという、その辺は、区としてはどうお考えでしょうか。","respondent":"久保田行財政改革担当課長","answer":"永久的なものではございませんので、１年６月という短期間の一時的な貸し付けでありますので、その後の活用ということであればいろいろとご意見等も聞きながら、また区も主体的にいろいろと活用計画について検討していきたいと考えていますが、区としては。","voiceIndex":17,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ただ何か変だなと思うよりも、こういうふうな形でこの貸し付けの費用を区民の財産として当然の対価をいただきますというようなことをぜひ区民にも説明してほしいし、我々もそのことをもってこういう計画に賛同していきたいと思いますので、もしきょう出なければ次回でも結構ですので、そんなに便宜を図っているものではないよという資料を、ぜひわかりたいと思いますので。","respondent":"久保田行財政改革担当課長","answer":"青稜高校に関してですけれども、しながわ中央公園の利用について、簡単に概要についてご説明いたします。","voiceIndex":19,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"減額のところで、２倍で学校施設で使っていることはわかっているんですけれども、そうではなくて減額のところとか、そこのところはそういう資料としてちゃんとしっかり見たいと言ったときには、情報公開ではなくて生涯学習課になるんでしょうか、そういったところでちゃんと示していただけるものなんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"今、資料提供ということでございましたけれども、行財政改革特別委員会で資料要求ということで取りまとめをされるのであれば、私どももそれには協力はしていきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"ぜひそういうデータがあって区民の方へも説明ができるし、おかしいと言われて、ただ、大丈夫です、とは言えないので、ぜひ委員会としてそういった資料要求をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"その辺を、荏原第四中学校を使うかどうかは別問題としても、学校跡地などの検討をしていたわけですから、その当時の状況をちょっと聞かせていただきたいです。もう一つは、先ほどの説明の中で青稜高校に関する校舎の部分はわかったんですけれども、グラウンドですとかそういうところはどうなっていくのか、その辺もお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"その後、今年の９月になりまして、さらに具体的に青稜高校から荏原第四中学校の跡等を使えないかということで改めて協力の要請がございましたので、具体的な検討を進めているというところで、方向性としてはそういった形でお貸ししていきたいと考えて取りまとめたところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"その中の具体的な問題として、荏原第四中学校があったり、杜松小学校があったりするわけです。ですから、そういう話が実際にあって、その具体的な中身ではなかったとはいっても、そういう話は区にあったわけですから、そうした材料は常に議会の中に示していくべき中身ではないかと思うんですけれども、その辺の検討は実際に区の中であったのかどうか、その辺をちょっともう少しお聞きしたいんです。","respondent":"日下部企画部長","answer":"この一貫校をどうするかというような、そういう一つの検討が進んでいるときに、跡地の問題をどうするこうするということになりますと、これは地元の地域の皆さん方の一つの受けとめ方といいますか、感情の問題も考えますと。","voiceIndex":27,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つひとつのそうした、かなり具体的ではないとはいえ区に対して要望が青稜高校からあったわけですから、そこはしっかりと私は報告をしていく部分ではないのかと思います。やっぱり昨年度の行財政改革特別委員会の中で実際に委員が議論しているわけですから、そうしたものについては、しっかりとした報告をすべき中身だろうと思います。","respondent":"日下部企画部長","answer":"提言についての審議ですが、もちろん私どもとしましては、議会から出されたそういう意見とかご提言を踏まえまして、今回もそれを一つの大きな課題としまして、この間、検討を積み重ねてきた、そういうものです。","voiceIndex":29,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"だから、そこはちょっと今の部長がおっしゃった部分は違うのではないかと思います。最後になりますけれども、いずれにしても前年度の行財政改革特別委員会の中で出されていた、やっぱり今本当に必要になっている、こういう高齢者施設を建設していく、増設していく、こういう流れをしっかりつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"ただ、１点、今、青稜高校とかいろいろな話があるんだけれども、青稜高校のところとしながわ中央公園は、もう一番最初にできたときからいろいろな話が議会の中でもあって、きちんとその辺の整理をしてきたという経緯があるので、その辺を見てからやっていかないと、また同じような質問が何回も出てきてしまうと思うので、そのあたりは理事者のほうもしっかりそういう話。","respondent":"日下部企画部長","answer":"確かに施設を計画するときに、やはり非常に私どももいろいろ悩むんですけれども、実際、建物をつくればそれでいいかというと、そうではありませんで。","voiceIndex":32,"id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"原小学校跡のときは、高齢者施設と保育園というか、そういう子どもの施設、両方が一体となった運営をしなければいけないということで、そういうことでお声をかけてつくっていかれたと思うんです。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-016"},{"speaker":"金野委員","kind":"確認","question":"確認を２点ほどします。その一方で、学校の避難所としての機能はどうなのかという心配の声がある。それが１点。それから、この地域利用の方の案ですけれども、介護予防拠点ということで案が示されているんですけれども、こちらもいわゆる介護予防拠点ということですから、ある一定の広さをもっていろいろな活用の仕方をというところだと思うんですけれども、その確認とともに、プールのある位置ですね。","respondent":"久保田行財政改革担当課長","answer":"今後の活用等につきましては、やはり詳細な設計の中で高齢福祉の事業部とも検討していきたいと考えているところです。","voiceIndex":35,"id":"exchange-017"},{"speaker":"金野委員","kind":"質問・要望","question":"介護予防拠点としての活用の仕方も、体育館を存分に今までと同じような形で使っていけるようにということですが、できるだけ、今もおっしゃってくださいましたけれども、当然、地域の方のご利用の利便性というか、ご希望をかなえる形でしてくださるとは思うんですけれども、介護予防拠点はたくさんあるんですけれども、その介護予防拠点が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと１つだけ聞くのを忘れたんですけれども、先ほど荏原第四中学校の貸し出しの賃料は決まっていないという話がありました。この間のＴＯＣのときの話も、近くの不動産屋に聞いてみたいな話があったような気がするので、財産としての価値を決めるために幾らで貸し出すということは、当然、何かの基準があるのだと思うんですけれども、それと財産価格審議会ですか、あの辺との関連を教えていただけますか。","respondent":"市岡総務部長","answer":"区の公有財産の活用についての、売却ですとか、あるいは購入ですとか、そういう所有権の移転を伴うものと、それから貸し付け等の活用と、これは２つルールがありまして、売却や購入の場合については「財産価格審議会」というところで。","voiceIndex":38,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"その庁内の「公有財産管理運用委員会」ですか、ここは先ほどの話と同じで、部長や課長のところでつくり上げている委員会ということなんですか。","respondent":"市岡総務部長","answer":"これは、ご案内かと思うんですが、「公有財産管理規則」という区の規則がございまして、これに基づいて、私が委員長なんですけれども、必要な部課長で構成する委員会です。","voiceIndex":40,"id":"exchange-020"}]},{"id":"topic-02","title":"旧第一日野小学校跡地の活用","agenda":"旧第一日野小学校跡地の活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"貸付期間ですけれども、２年間ですけれども、逆にこれが、この経済状況もありますので、建て替えが具体化できずにまた延びるというか、２年間以上になってしまうことがあるのかお伺いします。鑑定士の方はどういう考えでこの金額を算出したのかをお伺いします。どういう、例えば７８台だったら１台分に月額３万円で掛ける７８台みたいな、そういう何か考え方があると思うんですが、そこら辺もお伺いします。","respondent":"久保田行財政改革担当課長、市岡総務部長","answer":"貸付期間の２年間ですけれども、この暫定活用としまして、この暫定活用中の期間の契約上は２年間ということで契約を結んだですが、再三申し上げていますように、ＴＯＣといたしましては。これは、駐車場の車１台ずつの貸付料を足し上げていって賃料を出すというふうな、そういう性格のものではありませんし、それから、不動産鑑定士というのは、これはもうご案内のとおりですけれども、国家資格として公のものです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった場合、計画のパブリックコメントというか、区が今回この暫定貸し付けを経て本格貸し付けでＴＯＣに貸し付けるという計画そのものは、やはり区民の財産の活用は大変重要な課題ですので、当然、区民の皆さんにまずしっかり意見を聞く必要があると思うので、パブリックコメントにかけるべきだと思うんですけれども、こういう場合、パブリックコメントにかけないのかなというのが１点と、あと。","respondent":"久保田行財政改革担当課長","answer":"今年の夏に行いました、地元の町会から周辺住民へ説明してくれという要請を受けまして説明をしに私どもが行ったんですけれども、その際にも地元の方から。","voiceIndex":49,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"これは一時的ではないですよね、あまりにも。その間に毎年、今年の４月でも４９４人も保育園に入れなかったという状況も年々ある中で、ちょっとそれは区民の合意なしにそれを進めるのは、やっぱり非常に問題があると思いますので、パブリックコメントにこれは最低限やっぱりかけるべきだと私は思いますけれども、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"地元への説明ですけれども、私どもとしましては４月と８月に地元の大崎第一地区の町会長会議で説明を行ってまいりました。","voiceIndex":51,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと１点尋ねたいのが、私もちょっと現地で調査なども、アンケート調査ですけれども、改めて、やっぱり「公園がない」という声が強く、それはそうなんですよ、そう思っていたんですけれども、改めてすごく切望されているなと実感もいたしましたし、あと、特別養護老人ホームでも結構切実な声が届きました。そう思わないですか、それだけお伺いします。","respondent":"久保田行財政改革担当課長","answer":"公園等が少ないというところもありますけれども、なかなか地域的にも非常に公園等をつくるのには難しいところではありますけれども、そうした中で、やはり私どもとしましては必要なところには必要な公園等も整備していきたいと考えておりますが。","voiceIndex":53,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"この今日の審議の部分については、８月の委員会でいろいろ審議して、それで、今日の部分は、前回その他で金額の面が出たということで報告が入ったと私は思っておりました。ですから、再度またもとに戻った審議がされたことがちょっとどうかなというのが、言うのは別に構わないですけれども、あまりその点に触れていくのがちょっと気になったんですけれども。そこら辺を教えてください。","respondent":"市岡総務部長","answer":"この鑑定評価については、当然、長期の貸し付けとこういう短期暫定貸し付けでは、鑑定条件が違いますので、それらを含めて、あるいは初期投資の舗装費用ですとか、フェンスですとか、これは借り主側が負担するというようなことも含めて鑑定条件の中に織り込んで鑑定を依頼し。","voiceIndex":55,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。そうすると、今回は短期の一時利用という形になりますけれども、今後、先ほど来１０年間という期間が出たときには、再度鑑定をして、同じように公有財産管理運用委員会の中で検討していくということでよろしいのでしょうか。","respondent":"市岡総務部長","answer":"そのとおりです。本格貸し付けになる場合には、これは鑑定条件が違いますので、これは改めて鑑定もし、決定もしていくということになります。","voiceIndex":57,"id":"exchange-026"},{"speaker":"渡部委員","kind":"確認","question":"お金のところで聞きたいことがあります。経営します。時間幾らという形になるとした場合、この月額といいますと、１０９万円。利用者が多くて１０９万円を超えた場合、要するにＴＯＣに入る駐車場利用料が多くなった場合は、これは公有地において商売をやっていることにはならないのか、大丈夫なんですか。ＴＯＣが公有地で利益を出してしまって大丈夫なものなのかどうかだけ１つ確認したかったんです。","respondent":"市岡総務部長","answer":"区有財産、公有財産の貸し付けには、当然、区の財産活用という面もありますので、それを織り込んで地方自治法上も適正な条件で貸し出すわけですけれども、もともとこの土地の貸し付けというのは、不動産鑑定上も一種の収益還元法で鑑定をしておりまして。","voiceIndex":59,"id":"exchange-027"},{"speaker":"渡部委員","kind":"質問","question":"それであればわかりました。それで、何もこの詳しい話がわからない人からしてみると、区が駐車場をやっているのかなとか、いろいろな話も出てくるのかなというところがあった中で、確かに家賃よりも高い収益をＴＯＣが出した場合、例えばですけれども、公園とかですと駐車場は区の土地ですから、委託して委託料を払ってたしか駐車料金は区に入るような仕組みですよね。","respondent":"市岡総務部長","answer":"そのためにも適正な価格で貸出しをするということを私どもとしてはきちんと担保するような手続を行っている、こういうことです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"井上委員","kind":"確認","question":"確認で、先ほどの幼稚園の活用みたいなところでは、同じような思いを私も思っていたのですが、できない理由としては、文部科学省から解体せよということで利用したくてもできないんですよということでよろしいのかということと、あと、移転だからということでしょうか。","respondent":"久保田行財政改革担当課長","answer":"活用につきましても、文部科学省の理由でできない、したくてもできないのではないかということでございましたけれども、やはり私どもとしましては、それに加えまして短期的ということで期間的に短いというところもありますので。","voiceIndex":63,"id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"本委員会の調査事項が公有地活用に関するということですので、区内に、ちょっと一般質問でも再質問でしたか、させていただいたんですけれども、どういう公有地があるのか、国有地や都有地ですね、そういうのがやはり区内のどこにあるのか、どういうものがあるのか、どういう面積なのか、幾つあるのかをぜひ委員会としても明らかにして、そして、つかんでいるならご報告していただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"保育所や介護施設などを地方公共団体の事業者が施設整備を行う場合に未利用の国有地の定期借地権を利用した貸し付けなど、そういう方針を打ち出しているので、ぜひ資料要求ということでいいんですけれども、区内にどういう公有地、国有地、都有地があるのか、ぜひ委員会としても明らかにしていただきたいので、次回以降でも構わないのですが、資料を要求したいと思います。","respondent":"堺委員長","answer":"その件については、また正副で検討します。ほかになければ、その他を終了いたします。以上で、本日の予定はすべて終了いたしました。","voiceIndex":71,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30232,"voices":72}},{"id":"h22-20101028-15","meetingId":"h22-cm10","date":"2010年10月28日","dateIso":"2010-10-28","committee":"環境対策特別委員会","time":"午前１０時０３分～午前１１時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"水辺とみどりの整備に関することとして、みどりの現状と施策","agenda":"水辺とみどりの整備に関することとして、みどりの現状と施策","exchanges":[{"speaker":"川西委員","kind":"質問","question":"全部できるかどうかわかりませんけれども、とりあえず二、三点。ちょっと聞き漏らしたかもしれないので伺います。月というものが、何月なのか。それから平成６年にみどりの条例というので動きまして、それ以前にできた建物の、いわゆるみどり率、何というんですか、建築に対する指導というのはそのままになってしまっている。公園、区立の。すみません、それだけとりあえず。","respondent":"藤田水とみどりの課長","answer":"調査を行った月ですが、６月に航空写真を撮影しています。それをもとに分析をしたものです。それから低木、高木の区分がわかるかということですが、草と木の区別はついているんですけれども、低木、高木の区分はちょっとできてはおりません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問・要望","question":"ちょっと意地悪な質問になっちゃいますけれども、大径木の現状という、今説明を受けました。６,９４１本確認されて、平成１４年との比較で１,４４０本増えたと。ですよね。急に大径木が１,４４０本増えるわけないんですから。そうしてみると、この調査そのものが本当に信頼性に足るのかなという話になってしまいますので、その辺改めて説明をしていただきたい。","respondent":"藤田水とみどりの課長","answer":"ということで、あくまでもそのときの本数がこういう本数であったということのご報告だけしかできないということで、私ども考えてあります。","voiceIndex":11,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"そんなに難しいことじゃないんですけれども、これ品川区の緑被地分布図、一番後ろにありますが、単純なことで水面と運河の違い、これは運河は水面になっていませんよね、これで見ると。それは何でなんですかという、それだけのことなんです。","respondent":"藤田水とみどりの課長","answer":"こちらの緑被地のほうは、先ほど申した緑被率を出すためのもとになっているものです。品川区の行政区域の２,２７２という数値では、運河等は含んでいないです。そこの中に入ってくる率としてカウントするときには、やはりどうしてもこういう色の塗り方になってしまいます。","voiceIndex":14,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"それはわかるんですけれども、川、多分これ目黒川ですよね。目黒川の水面があって、なぜそれに接続するような部分がないのかなと。単純に同じ水面だったらつながっているわけじゃないですか。それをなぜか、国なり東京都の基準があってこうされているんですかということの質問です。","respondent":"藤田水とみどりの課長","answer":"行政区域の面積を出す場合に、川はその面積の中に含まれるんですね。２,２７２と一般的に言っている数値の中にはもともと川は含んでいます。ただし運河は含んでいないということで、こういう記載になってあります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとの関係というのはどういう位置づけになっているのか伺いたいと思います。今度行動計画が出たわけですけれども、このままでこのみどりの基準といいますか、規制といいますか、これでよいと思っているのか、さらにみどりを増やすための基準だったり、規制というのか、枠を決めるというか、そういうのを考えているのか、そこを伺いたいと思います。川の上は植物ないですからね。","respondent":"藤田水とみどりの課長","answer":"これにつきましても、緑化推進計画のほうができてから、もう既に１４年ほどたってありますので、新たな行動計画というものはつくる必要があるのではないかということで、実施計画の中でもそういった計画をつくり、新たな枠組みを。","voiceIndex":20,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"この環境の行動計画ができて、いわゆる緑化指導、このままでいいのかという問いに対して新たな枠組み、あとみどりの枠の再編というお話ありましたけれども、それがどういう方向を考えていらっしゃるのか、考えを伺いたいと思うんですね。それまでの緊迫感を持った具体的な行動とかスピード感が必要だと思っているんですけれども、この辺どうお考えなのか伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"みどりのこれからの施策で、もっと増やしていくという考え方なのかどうなのかということですが、みどりの基本構想、この中で４分の１緑化をやっていきたいということで、その当時の緑化の考え方は現在のみどり率と同じような考え方であったということで。","voiceIndex":22,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"でもこれじゃ足りないという今議論になっている、足りないというか、みどりを増やさなきゃいけないという議論に進んでいるわけですから、今のこれでよしとしたら、あの行動計画は一体何なのと、こうなりますので、やっぱりさらなる区みずからも、民間さんも、住民に対しても、いろいろな基準を設けていくことが大事だと思うんですけれども、そこは行動計画の関係で今のままでよいというのは。","respondent":"岩田都市環境事業部長、藤田水とみどりの課長","answer":"ただ、過去品川区は緑被率でずっと区民には説明してきていますので、今は並行して、両方で区民の方に明らかにしていると、こういうことです。それからもう一つは、現在緑確保の総合的な方針ということで、つくるみどり、これは確実につくれてきている、しかしながら、これ多摩のほうが中心ですが、失われていくみどりも結構あるということで。","voiceIndex":24,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２削減の問題、確かに一番の問題は化石燃料を使って、地球の、何というんですか、循環システムの循環を壊してＣＯ２が増えていった、こういう問題があると思うんですね。品川で置きかえるといわゆる業務部門、オフィスビルの増加に伴うＣＯ２が直接的には多いと。そういう意味で、やっぱり具体的にみどりをどう増やしていくかという、その具体策が課長さんの答弁からも私は見えてきませんでした。","respondent":"藤田水とみどりの課長","answer":"これからはもう少し有効な土地といいますか、植栽場所を活用していかなければいけないということで、施設を新たに建てるようなときには緑化指導の中もありますとおり、屋上等の緑化についても行ってきたところですけれども、それに加えまして、当面建て替え予定がない、で。","voiceIndex":27,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"これ品川では１件もなかったんですけれども、何といったらいいんですか、ＣＯ２とかそういうことを考え始めると、低木１本置いたって何の効果もないかもしれないんですけれども、景観という意味ではそれがつながっていくことにとても意味があると思うんですね。だからそういった視点でもみどりを増やすという考え方があっていいのではないかと思うんですが、いかがでしょうか。この３点お願いします。","respondent":"藤田水とみどりの課長","answer":"一方では人に危害を加えるような害虫がいる場合については駆除もしなければいけないということで、方向性としては両方をうまく両立していくしかないのかなということで考えてありますが、これについては今生物多様性の委員のお話ありましたとおり。","voiceIndex":30,"id":"exchange-009"},{"speaker":"阿部委員","kind":"意見","question":"生物多様性のほうなんですけれども、やはり、先ほど課長から実態調査という言葉もありましたが、すべてで虫ばかりのところというわけには、確かに品川の場合いかないとは思うんですけれども、どういうところでそういったものを確保していくのかということは、ぜひある程度計画的に進めていかれるべきであろうなと考えています。この点についてはご答弁お願いいたします。","respondent":"岩田都市環境事業部長","answer":"ただ、道路法とか、いろいろ難しい法律の規定がありますので、そういう中でどういうにぎわいを醸し出す道具として、あるいはイタリアのローマのように、街路樹なんか全然なくても何か花だけが至るところにぶら下がっているとか、いろいろこれからは考えて。","voiceIndex":32,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"民間よりも規制というんでしょうかね、そういう目標を高く掲げているということなんですけれども、ただそのみどりの現状と施策についてを見てみると、公共施設が平成６年から２１年で、ヘクタールで１６５.１から１８５.９ということで、確かに力を入れている割には少ないという、ただ単純に数字を見るとそう見えるんですけれども、やはり民間が倍ぐらいに増えているという中で、民間の開発。","respondent":"藤田水とみどりの課長","answer":"緑被地の面積が１７２haです。で、比率のほうが１２.３％ということになってあります。ということで、公共施設のほうが緑被は既に進んでおりますので、その中でこれ以上の伸びがなかなか難しいというのが実態だです。","voiceIndex":35,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうところも区が積極的になんらかの形でアクションとってできるものなのかどうかということがちょっと気になります。民間も、当然どこまでやっていただけるかという、そういう先ほどもなかなか厳しいところもあればちゃんとできているところもあるという中で、公共のほうはどのようなストレスというんでしょうか、交渉の仕方ですとか、影響はどうなっているか、ちょっと教えていただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"これは区の施設だけでなくて、都の施設であったとしてもそういうような形になりますので、その中で私どもとしては適切に指導をしていきたいということで考えてあります。","voiceIndex":37,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"すみません。ちょっと聞き方悪かったんですけれども、新しいところはそういう形でやられるというのはあれなんですが、もう既に建物が建ってしまっているところの、例えば屋上ですとか、壁面ですとか、そういうのが多分出てくると思うんですね。そういうところに対してのアクションについて、すみません、そちらのほうを教えてください。","respondent":"藤田水とみどりの課長","answer":"ただ、その他の東京都ですとか、そういったところの中ではそれぞれの考え方もありますので、可能な場所が私どもが見て見つかればお願いをしていきたいと考えていますが、実際にはそれぞれの施設でご検討いただいているというのが実際です。","voiceIndex":39,"id":"exchange-013"},{"speaker":"川西委員","kind":"質問・要望","question":"ほかになければ１つ。いいですか。３８ページです。新しく大崎地区なんかはちょっと増えているほうに入るわけですが、新しく開発建築されたものの、数字が乗っかっているのか、今の質問にあったように、既存の建物の中で努力されているところがあるのか、ちょっとわかれば教えていただきたいと思います。ですから、そういうのをもっと促進するためには載せていただければいいかなと。これは蛇足です。","respondent":"藤田水とみどりの課長","answer":"保存樹の関係ですが、平成２１年度で考えますと、新たに指定をしたのが１２本あるんですが、その際に解除があったものが３件あります。ページ数がないんですが、後ろから４枚目のところにありますので、よろしくお願いします。","voiceIndex":42,"id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"これもう一つありましたね。新設の計画建物の中で荏原は増えたのか。それから既存の建物の中、民間ですよ、これ。民間の中で増えているのか。壁面緑化の現況ということで、やはり棒グラフか数字かわかりませんが、荏原地区、大崎地区の質問の中だと思うんですが、これは開発に、例えば大崎の明電舎の。ああいう開発行為の中で増えた壁面なのか、既存の建物なのか。","respondent":"藤田水とみどりの課長","answer":"正確な数はちょっと出ておりませんが、基本的に、やはり壁面緑化にしても、屋上緑化にしても、かなり建物に負荷をかけるものですので、小規模にプランターをちょっと置いて緑化する、そういうのも今は１m2からカウントできますので拾えてしまうんですが。","voiceIndex":45,"id":"exchange-015"},{"speaker":"川西委員","kind":"質問","question":"わかりました。壁面というのは比較的面積の少ないところでもできるんじゃないかというふうに印象を持っているんですけれども、こういう指導を丁寧にされる窓口というのはきちっとしているのかどうかというのをついでに伺っておきます。それから、せんだって品川寺のほう、イチョウなんですけれども、行きましてね。あそこのイチョウで行ったんじゃないんです。わかりました。これは質問ではありません。","respondent":"藤田水とみどりの課長","answer":"壁面等については、壁面もいろいろなタイプがあるんですが、そんなに負荷をかけないでできます。そういうお話があったときには、私どものみどりの係のほうでいろいろ支援をしながら、ご相談に応じながら対応しています。","voiceIndex":47,"id":"exchange-016"},{"speaker":"山元委員","kind":"質問","question":"１個だけすみません。この地区別の屋上の緑地で八潮地区がゼロということで、古い建物だということなんですが、これから八潮も一貫校の屋上とか、これからも屋上緑地というんですかね、何か予定しているというか、そういうのはありますか。","respondent":"藤田水とみどりの課長","answer":"ただ、既存の施設をそのままお使いになるというケースでは、私どものほうにそういった届け出があるわけではございませんので、それぞれの施設の中で施設を使う人たちのご要望があれば、その施設の中で工夫をして屋上の緑化をすることもあるかとは思います。","voiceIndex":50,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"ということは、緑被率とかみどり率には入ってこないという理解でよろしいですか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"壁面緑化は、実は飛行機からカメラで写真を撮るので壁が数値にあらわれてこないんですね。なので、緑被率、みどり率については、その壁面緑化の部分についてはカウントの中に入ってこなくなってしまいます。熱だけ考えればもっと安くできる。遮熱のペンキを屋上に塗ってしまえば、反射させてしまえばそっちのほうがいちばん手っ取り早いんですね。だからなかなか、義務づけないとなかなかやっていただけないというのが実態です。","voiceIndex":55,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"グラウンドはあのままで、全面は無理かもしれませんけれども、一部でももうちょっと工夫できないのかとかという工夫は、みどりの基本構想の４分の１構想から見れば、民間さんが今どんどん増えている、でも、公共の部分はもう目いっぱいというご答弁は、ちょっと私は、だれがおっしゃったかも覚えていないですけれども、いわゆるこの特別委員会の話の中で。","respondent":"藤田水とみどりの課長","answer":"委員ご提案のいろいろな、さっきのものもありますし、私どももみどりを増やしていきたいということで考えてあります。学校等についても可能な場所については植栽をしていきたいということで考えております。４分の１の緑化に向けてこれからも進めていきたいと考えています。","voiceIndex":58,"id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"もう１個だけすみません。緑被率とみどり率の議論がありました。これは要するにその目的とかが違うんですよね。何か言葉だけが飛び交ってしまって、そもそも言葉の使い方というか、目的が多分違うと思うんですが、そこを最後に一言だけ整理整頓していただけますか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"水辺についても同じように、水辺があると当然みどりがある、そばにあるところが非常に多いですので、そういった水辺の部分を活用することで安らぎとか、潤いだとか、そういったことを感じるような策につながるということで。ただ、混乱しますので、常にみどり率と緑被率というのは並列で調査をして、きちっと公にしていくということは今後してまいります。","voiceIndex":60,"id":"exchange-020"},{"speaker":"西本副委員長","kind":"意見","question":"１つだけ。","respondent":"藤田水とみどりの課長","answer":"そういった面では、屋上の菜園、これについても屋上緑化の１つの考え方であるということで考えておりまして、１年間通じてずっと野菜を植え続けていただければ、私ども、先ほど屋上緑化の助成の件数も挙げておりますけれども。","voiceIndex":64,"id":"exchange-021"},{"speaker":"西本副委員長","kind":"質問・要望","question":"どうしても菜園というところで楽しみもあってということで、維持管理は当然大切だということになると思うんですが、公共施設の中ではやっぱり取り組みやすいのは学校施設かなと思っていて、幾つかもう始まっているところもありますので、ここは教育委員会が担当になっていると思うんですけれども、その部署と、それからほかの公共施設の担当のところと。","respondent":"藤田水とみどりの課長","answer":"そういった中では何が問題なのか、どうすれば続けていけるのか、その辺については教育委員会のほうともお話をしたりしながら進めているところです。","voiceIndex":66,"id":"exchange-022"}]},{"id":"topic-02","title":"を行います。 環境情報活動センターの移転","agenda":"を行います。 環境情報活動センターの移転","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"ちょっとすみません。つまらないというか、ＥＣＯだよりのところで「星稜中学校」の「セイ」の字が違っているよ。これやっぱり配布することになるので、もう出しちゃっているんですか、これ。","respondent":"工藤環境課長","answer":"申しわけございません。こちらのほうの地図、「星稜中学」の「星」という字が、本来だと「青」という部分です。こちらのほうはホームページの中で訂正します。申しわけございません。","voiceIndex":73,"id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"すみません。この環境情報活動センターの移転ということですけれども、もともとは今ある場所にあって、こっちに行くわけですけれども、だから、こっちにあったのが向こうに行って戻ってくるわけではないわけですよね。だからこっちに行った理由というか、利点というか、ねらいといいますか、何かそういうお考えがあるのかなと。どういうお考えなのかご説明いただけますか。","respondent":"工藤環境課長、岩田都市環境事業部長","answer":"移転に関しましては庁舎内全体のレイアウトを管轄します経理課からお話がありました。理由といたしましては、やはり庁舎全体の有効活用という考え方から、今回決まったものです。ただ、３階部分は一時展示物を一遍片づけて、そのときにここの活動センターをとりあえず入れたんですけれども、やはり区役所としては入ってすぐのところですから、もう少し前のようにでかい空間を回復して。","voiceIndex":76,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28858,"voices":83}},{"id":"h22-20101029-4","meetingId":"h22-c-settlement","date":"2010年10月29日","dateIso":"2010-10-29","committee":"決算特別委員会","time":"午前１０時０２分～午後５時５３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"金野副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁も含めて１０分といたします。経過時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"以上で決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"歳入、１１款分担金及び負担金、８１ページに民生費負担金、保育園保育料云々書いてあります。これが１点目です。１点目の保育園の待機児童対策についてですけれども、私たち品川自民党の議員団としても、待機児童対策への喫緊な取り組みを要望しているところですけれども、ここ数年の入園希望者の数と待機児童数の推移について、また保育園の受け入れ拡大数についてお教えいただきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"ここ数年の保育園の定員の推移と待機児童者の推移についてご説明いたします。","voiceIndex":13,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"それぞれ、今の待機児童数を伺ったんですけれども、つい先日まで激しかった区長選があったものですから、そのときには、５００人も入れないんだよという声が私の耳にも届いておりました。今お話を伺いますと、平成２２年、待機児童数６６人という話を伺いました。この数字の差異は何なんでしょうか。ちょっと詳しくお教えいただきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、この方たちの中には、既に保育園に入っていらっしゃって、転園を希望している方、あるいは区の外、区外からのお申し込みの方などもすべて含まれておりますので、品川区といたしましては、６６人が待機児という認識をしております。","voiceIndex":17,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"待機の方が６６人いたということなんですけれども、この方たちがどうしても入れなかったということなんですけれども、この方たちは１年間子どもたちを抱えて、仕事を休んで待っているという状況だったのでしょうか。その辺、待機された人たちの、どういう状況に置かれているのかということをお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"そのほか、認可外保育所に預けている方、自営でお子さんを見ながらお仕事をされている方などもいらっしゃいますが、皆さん、適切な保育を受けていると認識をしております。","voiceIndex":19,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。たくさんの方が申し込みをして、その当時は入れなかったけれども、現在は入れている。当然のことながら、保育に欠ける状態の方たちから優先順位があるわけですから、当然６６人残されたという、最初に残った方というのは、ひとり親家庭とか、そんなことはなくて、私は、３時間、４時間働きたいんだ、子どもを預ければという方たちかなと思っているんですね。","respondent":"伊崎待機児童対策担当課長","answer":"認可外保育所につきましては、区内に１９園あります。利用状況ですけれども、１４０人ぐらいの方がご利用なさっていらっしゃいます。","voiceIndex":21,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"措置というんじゃなくて、入園というんでしょうかね。これから、認証保育所がただネックとなっているのが、お金が若干高いのかなという気がいたしますけれども、これについての運営助成とか、あるいは入園助成というものについて、若干上がったという話は聞いているんですけれども、今後品川区としてどのようなお考えを持っているかについてお伺いしたいと思います。","respondent":"吉岡保育課長","answer":"そういう中で、先ほどお話もございましたように、駅から近いですとか、わりと夜遅くまでやっているとか、そういう利便性もありますので、一定、認証保育所のご利用についても。","voiceIndex":23,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"申し込みの、今年度が１,７７１という数字を伺いましたけれども、これは当初の見込みどおりの、当然のことながら、シミュレーションの中で今年はこれぐらい申し込みがあるかなという中からは、どうもオーバーしたんだというような声も聞くんですね。これもやっぱりキャパシティ、ある程度もう限界に来ているのかなという気がするんですけれども、来年度の見込みについてお教えいただきたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"それに対しまして、区といたしましては、これまでのさまざまな保育施策で対応していくと同時に、認可保育園の開園の助成を、今度補正予算でお願いしていますが、さまざまな施策で対応していくと考えております。","voiceIndex":25,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。時間がなくなりましたので、あと２点あるんですけれども、補助１６３号線のほうは土木費のほうに回したいと思います。３番目の質問で通告しました債権の管理ということについて。区の収入未済額の近年の傾向、この表を見ましても、大変大きな額なんですけれども、どのような傾向、増加しているのか、減少しているのか、その辺をお聞きしたいと思います。","respondent":"福田会計管理者","answer":"ただ、区民税のような大きなものは別といたしまして申しますと、平成２１年度と平成１７年度を比べてみますと、８,６５０万円、率ですと２０.３％の増であります。これは１つの傾向として毎年少しずつ増えてきた、こういうことが言えようかと思います。","voiceIndex":27,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"増えております、まあ、数字的にお答えいただきましたけれども、このようなさまざまな債権ですね。収入未済額。未済額の中には、住宅関係なんかですと、その締めの月にどうしても入らなくて、二、三日遅れて入れましたと。この辺の方策についてお伺いしたいと思います。","respondent":"福田会計管理者","answer":"今までの検討を踏まえまして、じゃあ、どういう仕組みが望ましいのか。これをこれからいろいろ調査をしたり、あるいは内部で検討を進めたりしながら考えていきたいと考えております。","voiceIndex":29,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、今後何らかの仕組みづくりを行っていく、方向性でもいいんですけれども、という方向でやっていくということでよろしいんでしょうか。もう一度お聞きいたします。","respondent":"福田会計管理者","answer":"今申しましたように、債権の区分をきちんとする。実はこれは大変難しいことなんですけれども、きちんとするということと、それから、円滑な事務処理ができるようにすること。最終的な目的は、委員、ご指摘にありましたように、未収金の増というものをどうやって食いとめていくか。","voiceIndex":31,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"順番どおりやらせていただきますが、最初に住基カードの発行ですけれども、こちらによりますと、平成２１年度は４,１１９件の発行ということでありました。そして、今年度から即日発行するように対策を施しながら、また１,０００円から５００円に値下げをしておりますけれども、ここまでの期間で何らかの傾向の変化が見られるのかどうか、お伺いいたします。","respondent":"梶戸籍住民課長","answer":"こちら、今年の７月から即日交付、あと、ならびに発行手数料１,０００円から５００円ということでございまして、昨年と比べまして、７月、８月、９月の３カ月だけで見てまいりますと、昨年の３カ月間と比べますと、２７％ぐらい増えているというような状況になってあります。","voiceIndex":34,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"平成２０年度が特殊事情があって、少しずつ増えているということで、これはまたうれしい状況でありますけれども、増え方としては、全体的な区民数からいいますと、かなりまだまだ低いのかなという気がしてなりません。その中で、利便性を上げる取り組みというものがどうしても増やすためには必要かと思います。今後何らかの手だてを打とうとしているのか、お伺いします。","respondent":"原情報システム課長","answer":"そういった動きを十分区としても反映しつつ、今後の課題としてとらえて検討しています。再来年度、外国人の住民基本台帳、こういったところへの組み入れも検討されておりますので、そういう状況を判断しながら今後に生かしていきたいと考えているところです。","voiceIndex":36,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"この社会保障カードとか、一時期報道されて、４種類でしたかね、それを一緒にするとかいうような話もありましたけれども、今どうも論議がとまっているようでありまして、なかなか進まない１つの大きな要因になっているかと思います。工数もかかってしまいますので。ほかに踏切の安全対策で補助金の対象となるような事業があれば教えてください。","respondent":"藤橋都市整備下水道課長","answer":"カラー化につきましては、平成２２年度、本年度に東急池上線と東急大井町線の合わせて４カ所でカラー化を予定しておりまして、それについては、国庫補助ではなく、対象ではありませんので、一般財源という形で考えてあります。","voiceIndex":38,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"ものによっては、同じ安全対策でも、規模、また国庫補助の対象にならないものもあるということで認識をさせていただきました。実は、旗の台の東口の踏切、あそこをよく通るんですけれども、特に朝の時間帯は、車は本来は進入できないんですけれども、どうも通る車も多いようで、ここで人と自転車との錯綜というんでしょうか、非常に激しいかなという気がします。","respondent":"松代都市計画課長","answer":"これまで区のほうでは踏切の安全対策、いろいろとやってまいりました。かなり進んでおりまして、今、委員からもお話がありましたように、拡幅できるところ、またカラー化するところ、順次やっております。","voiceIndex":40,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"踏切事故は車と車の衝突とかと比べまして格段に被害が大きくなりますので、事故が起こらないうちに検討のほうはぜひとも進めていただければと思います。これは要望です。３点目ですが、学校情報通信技術環境整備事業費、非常に長いんですけれども、これは学校ＩＣＴ化の補助金だと思いますけれども、こちらのほうの用途、歳入に対します用途についてお伺いします。","respondent":"和氣学務課長","answer":"委員お尋ねの学校情報通信技術環境整備事業費、非常に長い名前ですが、これの使途ですけれども、品川区といたしましては、これを使いまして、地デジ対応の液晶４６インチのテレビを小学校に１台が１０校、小学校２台が２８校、各中学校には１台を配置し。","voiceIndex":42,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"ちょっとすみません。前回、これも過去に質問させていただきましたけれども、デジタルテレビとかブルーレイのレコーダーですけれども、どのような活用のされ方をしているのか、実例等がありましたら教えてください。","respondent":"和氣学務課長","answer":"これにつきましては、例えば理科の番組とかを録画いたしまして、基本的にリアルタイムであまり見ることはないので、録画をいたしまして、例えば地理に関する映像であるとか、生物に関する映像であるとか、そういうものを録画いたしまして、録画したものを使って。","voiceIndex":44,"id":"exchange-016"},{"speaker":"浅野委員","kind":"提案","question":"私もさきに質問の中で、サイエンスチャンネルで無料で提供している「ザ・メイキング」、このような番組を、無料なので、ぜひとも皆さんにお見せする機会を設けてはどうか。この時間帯は授業というわけにいかないので、例えば休み時間とか、短いのもありますので、子どもが理科離れ、科学離れしている中では、１つの大きな方策ではないかなと提案しています。","respondent":"冠木指導課長","answer":"今委員お話しのように、理科につきましては、非常に可視化が難しい。","voiceIndex":46,"id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"事項別、３０ページにあります区民税のところに関連をしてお聞かせ願いたいと思います。前年比で、区民税のところは０.２％増、７,０００万円ほどの増ということなんですけれども、今年の９月に国税庁のほうが平成２１年度の民間会社の平均給与を発表しているんですけれども、前年比で５.５％の減、金額にすると２３万７,０００円も減少したと報じています。","respondent":"武内税務課長","answer":"平成２１年度の区税の決算ということになりますと、ご案内のとおり、区税は、昨年徴収した分がこの１０月に決算という形になるんですけれども、実際的には平成２０年の１月から平成２０年の１２月の間に収入があった部分の課税をしているということですので、その辺。","voiceIndex":49,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと要因のところがなかったんですけれども、人口、この間、品川区の人口が、給与所得者が増えたとかいうような話がいろいろありましたけれども、どういう所得階層になってきているのかというところも教えていただきたいです。それから、平成２１年度の相談件数、減免者何件ぐらいになるのか、この辺もお聞かせ願いたいと思います。","respondent":"武内税務課長","answer":"ということで、それぞれ納税義務者数が増えているということですので、それなりの所得も、住民税のほうの個人住民税のほうについては増えるということですけれども、その中で、先ほど説明したとおり、分離所得の方については。","voiceIndex":51,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"減免者が何件ぐらいになるのかというのもお聞きしたので、お聞かせを願いたいと思います。それから、徴収猶予、その後に支払いが可能になる方、こういう方の件数についてもお聞かせを願えますか。","respondent":"武内税務課長","answer":"減免の平成２１年度の件数ですけれども、４６件です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"本来の数字がよくわからないのであれなんですけれども、徴収猶予の方の半分ぐらいが後に分割で納入できるという意味なんですか。その辺の件数というのは、平成２１年度ですから、ある程度数字として持っておられるかと思うので、その辺、数字としてお聞かせを願えますか。","respondent":"武内税務課長","answer":"徴収猶予は、具体的には、１,８００人ぐらいの方、徴収猶予という手続を年度で行うんですけれども、その半数ぐらいの方については、分納開始だとかという形で、手続で、全額ではないんですけれども、月々幾らとかという形で払っていただいています。","voiceIndex":55,"id":"exchange-021"},{"speaker":"菊地委員","kind":"確認","question":"最初のところで、相談が８,０００件、８,０００名という話でしたよね。徴収猶予になった方が、今の話だと１,８００、減免が４６件になる。ということは、４件に１件ぐらいの割合、２５％ぐらいの方しか、猶予になったり、あるいは減免になっていないという状況なんですか。ちょっと確認させてください。","respondent":"武内税務課長","answer":"そういう部分、将来的に見ても、３カ月猶予してみて、どう見てもなかなかこれは厳しいでしょうという形になりますと、執行停止という、そういう手続に入ります。その方が、平成２１年度では、６,１４２人の方を手続を行っているです。","voiceIndex":57,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"８,０００で、執行停止が６,１４２名。この６,１４２人の方のうちでいえば、実際に平成２１年度じゃなくて、平成２０年度の相談件数や何かもきっと入っているのかなと思うんですけれども、こういう状況というのは、区民の暮らしを見る上で、課長のところでも一定程度、今の暮らしがどうなっているかというのが見えるんだと思うんですけれども、その辺での分析というのはそもそもやらないわけですか。","respondent":"武内税務課長","answer":"もちろんそういう相談がありますと、どういう相談の傾向があるかというのは、職員間の中で、私も含めて、傾向的な話し合いをしてもちろんやっております。","voiceIndex":59,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"これだけの皆さんが執行停止ということではないですか、そもそも減免の制度を使いたいということで相談に伺う状況にあるんだと思いますね。本当に生きた税金の使い方をどういうふうにしていくのかというところも、税務課にとっても非常に中心課題になるんだと思うんですけれども、改めてその辺もお聞かせ願いたいと思います。","respondent":"武内税務課長","answer":"もちろん区政執行に当たりましては、区税収入というのは、３０％という割合を含めていますので、その辺の現状については、認識しながら、区政の声として広めていくということは大切だと認識しております。","voiceIndex":61,"id":"exchange-024"},{"speaker":"稲川委員","kind":"質問","question":"よろしくお願いします。密集市街地整備促進事業ほか４事業という補助金があるんですが、その辺についてお伺いいたします。返済をしたときに、基本的に一番古いのからどんどん返済をしていくような感覚はあるんですけれども、どういう形の返済になっているかということを教えてください。","respondent":"武内税務課長","answer":"ちなみに、平成１５年度以降は、１,６０３件、これは納期別の期数ということで理解していただきたいと思うんですけれども、１,６０３件ありまして、平成２０年度分については、３万８,３１８件というものです。","voiceIndex":64,"id":"exchange-025"},{"speaker":"稲川委員","kind":"質問","question":"平成の初期からずっとたまっているという話なんですけれども、この中には、滞納すると、多分利子とか利息というか、１７.４％ですか、そういうのというのはついてこの額になっているのか。これは元金というか、元本というか、そういうことでよろしいんですか。","respondent":"武内税務課長","answer":"こちらに出ている滞納金額については、延滞金を除いた金額で、本税という部分です。","voiceIndex":66,"id":"exchange-026"},{"speaker":"稲川委員","kind":"意見","question":"最近のやつはまだあれなんですけれども、結構前の本税の滞納に関して、結構昔からあるとおっしゃっていましたけれども、それはどういう形で今後徴収をしていくのか。１０年もたってしまうと、なかなか徴収の意欲もなくなってくるんじゃないかなと思うんですけれども、その辺今後どうやって徴収していくか、お願いします。","respondent":"武内税務課長","answer":"そうしますと、やっぱり財産がありますので、それはそのまま停止だとか、不納欠損に落とすということではなく、将来的に財産分与等が行われたときに、幾らかでも徴収するという、そういう姿勢で、そういう古いものが残っているということですので、それは状況を見きわめながら。","voiceIndex":68,"id":"exchange-027"},{"speaker":"稲川委員","kind":"質問・要望","question":"次に８９ページの外国人登録、手数料ということなんですが、外国人登録全般についてお伺いしますが、以前にも質問させていただきまして、平成２４年ですか、外国人登録ですか、法律が変わるんですが、法律が変わったことによって、じき来ると思うんですが、何がどう変わるのか、システムも変わるのかどうか、お願いします。","respondent":"梶戸籍住民課長","answer":"ただいまの外国人登録制度の改正につきましてのご質問です。全般の内容といたしましては、こちらの法律、ご案内のとおり、平成２１年、昨年の７月１５日に公布されたものですけれども、そちらによりまして、公布の日から３年以内に施行されるものです。","voiceIndex":70,"id":"exchange-028"},{"speaker":"稲川委員","kind":"質問","question":"ということは、今後外国人登録証明手数料的なものは、これにかかわる事務費というのは、歳入歳出に関しても、この件に関してはなくなってくるということでよろしいんですかね。それがいわば住民基本台帳のほうに今度は移行してくるという考え方でよろしいですか。","respondent":"梶戸籍住民課長","answer":"ただし、この新たな在留管理制度ですけれども、特別永住者の方につきましては、相変わらず市区町村のほうで受託事務になりますので、そういった在留カードという形ではなくて、特別永住者の証明書という形になってまいります。","voiceIndex":72,"id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"結構混乱するんじゃないかななんて僕も思うので、しっかりとこの事業は行っていっていただきたいと思います。９０ページの開発行為手数料に関してです。これは１５０件と書いてあるんですけれども、実際開発行為というのはどういう行為なのか、教えてください。","respondent":"山崎マスタープラン担当課長","answer":"区画の変更とは、道路等の新設、廃止等により、一団の土地利用形態を変更することを申します。それから、形質の変更ですが、土地を、切土、盛土等々申し上げますが、１メートルを超える造成行為、こういったものを指します。","voiceIndex":74,"id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"じゃあ、最後に１件だけ。この１５０件の中で、１つの土地を分筆して分譲にするような開発行為というのは何件あるかだけ教えてください。","respondent":"山崎マスタープラン担当課長","answer":"開発行為の手数料に該当したものは５件ございまして、そのうち、委員おっしゃられたものに該当するのは２件です。","voiceIndex":76,"id":"exchange-031"},{"speaker":"渡部委員","kind":"確認","question":"歳入全般の中のことで、特に先ほどほかの委員からもありました債権の管理に当たるのでしょうか、不納欠損額と収入済額の関係について伺っていきたいと思います。１回何かアクションが起これば、その時効は延びる。今回決算書ですとか、決算審査意見書、監査委員のほうから出ている意見書の１６ページを例にとってお話を伺っていこうかなと考えています。時効の部分等もいろいろあわせて伺いたいのが１件。","respondent":"福田会計管理者","answer":"大きく分けて２つのご質問にお答えさせていただきたいと思います。使用料における公債権と私債権の区別ですけれども、これは名称が使用料と呼んでおりますから公債権あるいは私債権という区別ではございません。","voiceIndex":79,"id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"もう１点、事例を示して、同じことなのかと思うんですが、お伺いしたい。当然平成２１年度においても、収入未済額が出ております。やはり平成２１年度から、会計処理上、これは受けたサービスに対する対価ですから、当然区民の方にもお支払いいただかなければならない。毎年出ていたものがゼロになっているということ自身、何かの制度変更でもあったのかなと思ったんですが、その辺はいかがでしょうか。","respondent":"吉岡保育課長","answer":"それで、年度を越した６月に早速、平成２１年の分でやるべきであった分について不納欠損処理を実際のところはもう既にしております。金額は１２８万円余ですので、大体金額的にも例年の額と同じぐらいの不納欠損が発生をしていたというのが実態上の状況です。","voiceIndex":81,"id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"それで、いわゆる監査委員から出た意見書のほうで、１６ページです。例えば平成２０年度の収入未済額があって、平成２１年度の収入未済額があります。減っています。収入未済が減っているということは、この決算書の間１年間で、繰り越しされていた方、収入未済であった方が、区のアクションによってお支払い、要するに支払い行動があったから、今年収入未済が減っているということでよろしいんでしょうか。","respondent":"柏原住宅担当課長","answer":"今のご質問です。収入未済が減っているということで、主に多いのが、特に年度を繰り越して過年度分になってしまったという方が多いんですが、その方に対して、区のほうでも積極的にアクションを起こしたところ、お支払いいただいた結果です。","voiceIndex":83,"id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろ伺ってまいりました。ありがとうございました。やはり債権に関しての取り扱いというものは非常に大変だと思いますし、さまざまな制約がかかってくるケースもあると思います。なおかつ当然ですけれども、不納欠損をなるべくできない、しないでいけるような方向に、いろいろこれからさまざまな変更等が必要かもしれませんが、区もしっかりと努めていっていただきたいと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"山内委員","kind":"質問・要望","question":"１つ確認をさせていただきたいんですけれども、９９ページに高齢者のさまざまな対策に対する補助金が記載されておりますけれども、基本的には品川区、要介護者の約６割以上の方が在宅で支援をしていただきたいというようなアンケートの回答が出ていると思うんですけれども、いわゆる在宅の介護といったものを１つの基準として、そこからさらに、例えば在宅で介護ができない。","respondent":"冨岡高齢者福祉課長","answer":"あわせて今は、地域密着型のさまざまな事業所ができておりますので、認知症のグループホームであるとか、小規模多機能と、そういうものも建設しながら、できるだけ地域でお住まいをいただくということを目指したいと考えているところです。","voiceIndex":87,"id":"exchange-036"},{"speaker":"山内委員","kind":"質問・要望","question":"施設の重要性といったものもあるかと思いますので、そのあたりはいろいろと区民の方々の意見もしっかりとお聞きをしていただいて、整備をしていただきたいなという思いがいたします。この助成金なんですが、ちょっと確認をさせていただきたいんですが、私、第１回定例会でシルバー人材センターの今後の行く末について質問をさせていただきました。質問させていただいたのが２月ですよね。","respondent":"福島ものづくり・経営支援課長","answer":"区といたしましても、大体年間１２億円、人数でいいますと２,４７０人余りの高齢者の方が働いている大切な就労機会ですので、区としましても、今後支援を進めていきたいと思っているものです。","voiceIndex":89,"id":"exchange-037"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。そうしますと、先ほど申し上げた成果報告書に載っているシルバー人材センターの助成費の２,４９９万円というのは、どのような形で品川区のほうでお使いをされているのかといったことと、今年度の平成２２年度の予算書を見ましても、やはり同じ金額なんですけれども、この金額といったものはずっとフラットでいくものなのか、そのあたりも教えていただきたいなと思うんですが。","respondent":"福島ものづくり・経営支援課長","answer":"どのように決まっているかといいますと、先ほど言いましたように、都の要綱によりまして金額が決まりますので、都の要綱は改正がありますと金額が変わるというもので、ずっとフラットというものではございません。","voiceIndex":91,"id":"exchange-038"},{"speaker":"山内委員","kind":"確認","question":"その辺の内容なんですけれども、例えば仮に会員になられる方が、これからも多分右肩上がりで増えていくだろうといったことを言われておりますし、そういう考えをされていると思うんですけれども、そうなりますと、平成２１年度の決算と平成２２年度の予算というのは同じ額ですが、これは人数、会員数に対しまして、金額的にも上昇していくといったことでよろしいのか。その辺を確認させてください。","respondent":"福島ものづくり・経営支援課長","answer":"今回品川区の場合は、本部につきましてはＡランクになっています。支部につきましてはＢランクになっているというものです。このランクが上がるほど、人数が増えますと、確かに金額は増えるかと思ってあります。","voiceIndex":93,"id":"exchange-039"},{"speaker":"山内委員","kind":"質問・要望","question":"再度、そのランクというのは、人数のことなんでしょうか。ランクといってもいろんなランクがあると思うんですけれども、ランクの内容というのはどういうものか。今ランクということをおっしゃられたので、その辺について確認をさせていただきたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"ランクは、人数もそうなんですけれども、それ以外にもさまざまな規定がございまして、使うことができる内容ですとか、例えば人件費は幾らまで使えるとか、そういう細かい内容の要綱に基づきまして支給されているものです。","voiceIndex":95,"id":"exchange-040"},{"speaker":"山内委員","kind":"質問・要望","question":"載せることには私は問題ないと思うんですが、ただここは、品川区の施設といった何か記載を載せるべきじゃないかなというような思いがしたんですけれども、そこら辺が載ってないといったときに、その辺の民間との公平性というか、そういうものを、これからいろいろそういった形で民間にいろいろ貸し出しをするような区有施設もあるかと思うんですけれども、そういったときには。","respondent":"堀越文化スポーツ振興課長、金子企画財政課長","answer":"今ホームページ等のお話をいただきましたけれども、そういった誤解を与えるような何かがもしあれば、確認させていただいて、必要に応じて申し入れ等をするような、そういう形で対応していきたいと考えております。使用料全体についてのご質問がありましたので、私のほうからお答えします。使用料は、使用した際の受益者、受益されていますので、適切な負担をしていただくというのが基本的な考えです。","voiceIndex":97,"id":"exchange-041"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党の山元です。そこでご質問なんですけれども、利用されている方々は、単発といいますか、急に使いたいとか、また、毎月利用される方もおられるかと思うんですけれども、利用率というんでしょうか、利用率と、また、特に毎月使っていらっしゃる方々がいらっしゃると思うんですが、この方たちは全体の何％ぐらいを占めているのか、その辺を教えていただきたいと思います。","respondent":"中山地域活動課長","answer":"継続的利用の方の割合というご質問ですが、そういう形での統計はとっておりませんので、幾つか施設ごとにそういう登録をしている団体の数というものはそれぞれで把握しておるわけですけれども、一度ご利用いただいたら、その後は、１回登録をして。","voiceIndex":102,"id":"exchange-042"},{"speaker":"山元委員","kind":"質問・要望","question":"区民の方からも苦情が来ているかどうか。来ているのではないかと思うんですが、実際利用したいときに、申しわけないんですが、毎月のように利用されている、俗に常連と言うんですかね、そういう方たちとかち合ってしまうことが起きて、使いたいときに使えない、一番近い集会所なのにという思いがあるわけですが、それに対して解決方法といいますか、何かお考えをなさっていれば、教えていただきたいんですが。","respondent":"中山地域活動課長","answer":"今おそらくご質問のほうは、そういうことよりは、非常に人気のある時間帯、例えば土曜日等の日中であるとか、平日夜間の利用率高いところについては、結局倍率が高くなって、何回か申し込んでもとれなかったということがあろうかもしれませんけれども。","voiceIndex":104,"id":"exchange-043"},{"speaker":"山元委員","kind":"質問・要望","question":"１６カ所の集会所の中に平塚橋会館があります。例えばこの葬儀のことでちょっと使いたいななんて思うときに、日曜日がお休みというのはどうなのかなと思っているんですが、その辺も教えていただければと思いますが、いかがでしょうか。","respondent":"中山地域活動課長","answer":"それで、日曜日の利用等、休館の扱いというのは、いろいろこれ、経過の中で地域のお声を聞きながら設定した経過がありますけれども、もしそういう潜在的なお声があるということであれば、またこれは、会館のありよう、運営の体制の確保も含めて、そういうお声があれば。","voiceIndex":106,"id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"そうしましたら、そのときには、ご相談に乗っていただけるということでよろしいでしょうか。","respondent":"中山地域活動課長","answer":"今申し上げたのは、個別の休館日の利用のご相談ということではなく、例えばそのようなお声が、今もございました、少し冷静に分析させていただいて、必要性があれば、要はこれはきちんと周知をして、利用の時間、曜日等の設定のことですので、そういう中で。","voiceIndex":108,"id":"exchange-045"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思います。次に、８８ページの温水プールのことでお伺いをさせていただきたいと思います。各地域で温水プールを待ち望んでいる方がたくさん、特にご高齢の方がおいででございました。","respondent":"堀越文化スポーツ振興課長","answer":"学校の温水プールの開放経費としては９,１００万円という形で、昨年度の実績が、歳出ですと、決算ベースで６,６００万円ですので、八潮学園の温水プールが平成２１年度からオープンしておりますので、歳出としては増えているという状況にあります。","voiceIndex":110,"id":"exchange-046"},{"speaker":"山元委員","kind":"質問・要望","question":"温度を決定するというんですかね、それはどなたが何度の設定をするとかとお決めになるのか、その辺を教えていただきたいんですけれども。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどの歳入と歳出の差ですが、失礼いたしました。５,１００万円の歳出に対して４,３００万円です。こちら、学校の利用等が増えておりますので、一般開放の有料分が昨年度から比べて若干減ったと。","voiceIndex":112,"id":"exchange-047"},{"speaker":"山元委員","kind":"質問","question":"もう一方、プールから一時上がって、また着替えたりする更衣室があるんですけれども、そちらの温度というのも決まっているのでしょうか。実は、やはりちょっと寒いとか、いろいろ苦情があったりもしたものですから、この辺の温度も決まっていますか。","respondent":"堀越文化スポーツ振興課長","answer":"特に温度が何度という形はしておりませんけれども、寒いですとか、そのようなお声も聞いておりますので、そのときは、例えば風を防ぐカーテンですとか、そういったものを設置したりですとか、そのような形で、それぞれ要望に応じて工夫を図って。","voiceIndex":116,"id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"もう１点お聞きしたいんですが、プールに、係の方と言っていいんでしょうか、どなたかがついていらっしゃるかと思いますが、ＡＥＤでしょうか、特に心臓で倒れちゃったり、いろいろとあると思うんですが、そういう方たちというのはＡＥＤの操作といいますか、そういうことができる方がその場にいらっしゃるのかどうか教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"例えば泳力もそうですけれども、救命救急の講習も一定の講習を受けた者を配置を義務づけておりますので、そういったプールの監視業務の中で、もし何かあった場合には対応するという形になります。","voiceIndex":118,"id":"exchange-049"},{"speaker":"藤原委員","kind":"質問","question":"歳入全般でお伺いしたいんですけれども、ページでいうと７７ページの特別区税、８０ページの財調、１０５ページの繰入金、あと、１０４ページの有価証券等売払収入なんですが、まず１０４ページの有価証券についてお伺いしますが、内容はわかっております。で、このことによって、区民に得といいますか、これをやったことによって、一般の区民には何のメリットがあったのか、教えてください。","respondent":"榎本人事課長、金子企画財政課長","answer":"区民にとってのメリットということですけれども、区がそのまま持ち続けていた場合については、会員制宿泊施設が裁判所の再生手続に入った関係で、不納欠損が出てしまうということで、それを回避するということで。経常収支比率を中心にしたお尋ねですけれども、冒頭ご説明申し上げましたとおり、品川区でも経常収支比率は３.４％ほど数字が落ちております。","voiceIndex":121,"id":"exchange-050"},{"speaker":"藤原委員","kind":"確認","question":"それを確認。ですから、大きな形で、企画財政という課なんですから、大きな目で品川区をどういういいまちにしていくか、来ていただける自治体にしていくかというのを全庁的にある意味見ていくべきだと思うんですが、その辺はいかがでしょうか。それと、区債と基金についてお伺いしたいんですが、たしか２年ほど起債していなかったですよね。","respondent":"榎本人事課長、金子企画財政課長","answer":"時代が変わりまして、互助会のほうもそれなりにいろんな福利厚生、職員のためのことができるという形になりましたので、その部分で有価証券を手に入れることで、保養所機能はそのまま互助会のほうが使えるということで。３点ほどご質問いただきました。一番最初、ちょっと難しい質問かと思いますが、私ども、平成２１年度から新しい長期基本計画をスタートさせております。","voiceIndex":124,"id":"exchange-051"},{"speaker":"石田委員","kind":"質問","question":"よろしくお願いします。私のほうからは成果報告書の都委託金、１０３ページの教育費委託金のスポーツ教育推進校委託金と英語教育調査研究事業委託金についてお伺いします。初めにスポーツ教育推進校委託金と英語教育調査研究事業委託金、この内容について、この２点お伺いをします。","respondent":"冠木指導課長","answer":"それからもう一つ、英語の調査研究につきましては、これは文部科学省の指定事業でございまして、平成２１年度に小中学校を連携した英語教育、新しい学習指導要領に向けて、国のほうが調査を始めたというようなところで、品川区の小山台小学校、後地小学校。","voiceIndex":128,"id":"exchange-052"},{"speaker":"石田委員","kind":"質問","question":"もう少し詳しく、スポーツ教育推進校が３校ということですが、予算として１４０万円弱なんですが、実際どのようなものにこの予算が使われているのか、お聞かせください。調査研究と書かれて、調査研究というのも、主にどういった事業があるのか、その内容をもうちょっと詳しく教えてください。","respondent":"冠木指導課長","answer":"スポーツ教育推進校の３校の使い道ですけれども、今体力の低下というようなところで、これは日本全国、あるいは東京都においてもいろいろと話題になっているところでございまして、品川区においても、全体的に体力については、一定程度の維持はしているものの。","voiceIndex":130,"id":"exchange-053"},{"speaker":"石田委員","kind":"質問・要望","question":"それは要望で終わりますが、それで、スポーツ教育の中で、持久力、筋力を伸ばしていくためにさまざまな機材を買われているということなんですが、これをどのように実際、授業内で使われているのか、それとも別な時間帯で使われているのか、その辺、ほかの学校との違いを教えていただければと思います。スポーツの件で、スポーツの教育推進校の件をお答えください。","respondent":"冠木指導課長","answer":"子どもたちの体力の向上という意味合いにおきましては、授業ももちろんですが、家庭生活、そして学校生活、両面にわたってそういった意識で取り組んでいくということが大事なのかなと思ってあります。","voiceIndex":132,"id":"exchange-054"},{"speaker":"石田委員","kind":"意見","question":"スポーツ、主に小学校なのかなと僕もちょっと思ったんですが、中学校では、品川区では大崎中学校が全国的にバレーボールも頑張っていますし、そういった意味では、ぜひともスポーツを通じて子どもたちの健全な育成に臨んでいただければと思います。英語教育、しっかりと取り組むように、僕たちもまた提言等もしますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"辞退者などを引いた数字だったんでしょうか、先ほどの質疑で４８７人という数字でしたけれども、一方で、区が発表する４月１日現在の待機児は６６人ということなんですけれども、この関係がわからないので、教えてください。つまり、保育園に入れずに仕事をあきらめて申し込まなかった人や、申し込んだとしても認証に入った人や転園希望の方は除いていることでよろしいんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"待機児童として国の基準に基づき算出した方の人数は６６名です。この６６名という数字は、先ほども申し上げましたが、認証保育所に在園している方や認可保育園に在園をしていて、転園を希望している方、あと、区外からお申し込みをしていらっしゃる方などの数字は除いてあります。","voiceIndex":136,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"４月１日現在の待機児はなぜか６６人と、国に基づいてということでしたが、これは一たん改めて申し込みをされた方でないとこの６６人にならないと思うんですね。申し込まない人の中には、４月入園でかなわずに、仕事をあきらめて申し込まなかった方もたくさんいらっしゃると思うんですけれども、そこはどうなんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"この６６人は、国から出されています待機児童の報告の基準に基づいて算定をしております。その算定におきましては、４月１日現在で保育園を希望しているということがありますので、４月１日におきまして保育園の入園を希望している方という形でお出ししています。","voiceIndex":138,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"つまり４月１日で、不承諾通知を受けた方には改めて新年度には申し込みの必要がありますよというご案内が入っているわけですよ。ですから、改めてその通知を見て申し込みをされた方ということでよろしいんですよね、今の答弁は。","respondent":"伊崎待機児童対策担当課長","answer":"不承諾通知をお出しする中に、引き続き保育園を希望される方は４月１日から申し込みをしてくださいというご案内が入っております。これに基づきまして、ご申請を出されない方というのは、４月１日以降のご入園を希望されないという判断をいたしております。","voiceIndex":140,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、来年がどうなるかと、とても多くの方が心配しているわけですけれども、今年１０月時点での申し込み人数、現在何人になっているのか、昨年の同じ時点での申し込み人数を伺います。あわせて、先ほど来年さらに申込者が増える可能性もあるとの認識も示されましたけれども、一体品川区としてはどうやってこの事態を解決するつもりなのか、お聞かせ願いたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"来年に向けての待機児童対策ですが、これまでのように、既存施設の利用も含めて認証保育所の開設、短時間就労保育室の開設、あと、計画的な認可保育園の開設支援、あるいは幼保一体施設の計画的な整備等含めまして、これまでと同様に取り組んでまいる所存でおります。","voiceIndex":142,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、１つマンションができると、相当子育て世代が来ますので、そういう政策をするのであれば、最低限計画的な認可保育園増設ということが必要だと思います。区商連との委託契約の内容についてお伺いしますが、委託契約期間とあと委託料は１食につき幾らなのかということと、今年わかれば、今年も含めていただきたいんですが、ここ３年ぐらいの配食実績数を教えてください。","respondent":"秋山協働・国際担当課長","answer":"区商連のほうに委託する際には、高齢者の方への食事ということも一つありますので、その内容について、講習会などを行い、その質について確保するように区商連のほうには伝えておりますし、また、アンケート等をとっておりますので、そのアンケートの結果については、随時。","voiceIndex":144,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"委託の件ですけれども、総額５３０万円ということですが、１食につき幾らという契約ではないのか、それとも、委託契約期間というのがあるのか、そこら辺をお伺いします。","respondent":"秋山協働・国際担当課長","answer":"失礼いたしました。答弁漏れです。１食当たりの単価は、区商連に対して９００円です。契約期間は１年、４月から３月３１日までということになっております。","voiceIndex":146,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"しっかりと区が委託をしているわけですから、受け手にとってしっかりとした質のサービスが以前に比べても変わらないような、引き続き得られるような措置が絶対必要だと思うんですが、何点か声を伺うのが、以前は中学校給食だったので、温かいものを持ってきて、ポットか何かを持ってきて、訪問したお宅の食器に移しかえて、お出しして、いただいてもらうという、そういうシステムだったんですね。","respondent":"秋山協働・国際担当課長","answer":"配食につきましては、日々必要なものですので、配食を継続的に続けていくということで、地域の商店とそれから地域の商店の活性化も含めて効果があるということで進めているところです。","voiceIndex":148,"id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"メニューというのは、高齢者向けのものという答弁しかなかったので、どういったものを注文するのかわからない面があるんですが、ぜひそういった観点から、横の連携もとりながら、高齢者のサービス受け手の方にとってよりよいサービスになるよう努力をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-063"},{"speaker":"武内委員","kind":"質問・要望","question":"私は９７ページの水道管直結化事業負担金、それから１０９ページの水族館運営費収入の２点でお伺いしたいと思います。","respondent":"田村庶務課長","answer":"実績としますと、まず平成１９年度、大井第一小学校から開始しまして、平成２０年度、浅間台小学校、三木小学校、宮前小学校ということで、それと、今回平成２１年度につきましては、城南小学校、城南第二小学校、芳水小学校と鮫浜小学校ということで、当初予定した２校以外に。","voiceIndex":152,"id":"exchange-064"},{"speaker":"武内委員","kind":"質問・要望","question":"私どもの三上委員が平成２０年の予算特別委員会のほうでこの件で質問させていただいて、早急に拡大をというような要望もさせていただいたんですが、これまでいろいろ委員会等の質疑ですと、東京都のほうでは、平成２３年度以降、来年度以降は動向がちょっと定かじゃないというような、そういう答弁もあったような気がしたんですけれども、今後の状況、来年度についても実施できるのかどうかということと。","respondent":"田村庶務課長","answer":"当初モデル事業だったんですが、今の段階では、平成２２年度から中学校も実施して、あわせてこの事業そのものを平成２８年度まで延長して普及を図る。そのような動きを聞いているところです。","voiceIndex":154,"id":"exchange-065"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。そうすると、来年度からつかないのかなと心配していたんですけれども、今のお話だと平成２８年度まで延長されるということなので、品川区としても、その間に可能な学校についてはすべてやっていくということでよろしいんでしょうか。一応答弁いただきたいと思います。","respondent":"田村庶務課長","answer":"もう既に１０校近くやっていまして、学校の構造上可能な学校は具体的にさらに推進していきたいと考えております。","voiceIndex":156,"id":"exchange-066"},{"speaker":"武内委員","kind":"質問","question":"ぜひよろしくお願いいたします。それから、次の質問で、水族館の運営費収入についてお伺いしたいと思います。こちらも、当初予算は１億３,５６５万４,０００円ですか、で、決算のほうでは８,５００万円余りということで、大幅に見込みに比べて減ということになっておりますが、この主な要因について教えてください。","respondent":"藤田水とみどりの課長","answer":"水族館運営費の歳入の部分ですが、予算時点では入館者の予測を６１万人ほどということで当初考え、計上しておりましたが、決算の段階では５３万９,０００人ということで、入館者が減ってしまったということが主な原因です。","voiceIndex":158,"id":"exchange-067"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、平成２２年度の今年度の予算のほうでは、そうしたことも踏まえて、今回の決算額と同じような額に予算自体を抑えてはありますけれども、そうした中で、この間の予算委員会の中で、ほかの委員からの質問の中で、今後の水族館の運営のあり方等も含めて、おそらくこの中には集客をどうしていくかということもあると思うんですが、あり方検討委員会で検討していると。","respondent":"藤田水とみどりの課長","answer":"その中では、当初私どもの水族館、３０万人ぐらいの入館者であろうというような予測もありましたので、そういった３０万人という数値も含めて、どうあるべきか、検討を進めたいと考えています。","voiceIndex":160,"id":"exchange-068"},{"speaker":"武内委員","kind":"質問","question":"今お話あって、そこからどうとるかというのはこちらの判断なんですが、今若干弱気の感じかなと受けとめたんですけどね。その辺はどうなんでしょうか。その辺も含めて教えてください。","respondent":"藤田水とみどりの課長","answer":"１つは、現実をしっかり受けとめなければいけないということで考えております。私どもも、水族館、大変多くの方にまだまだ来ていただいている施設ですので、そういった面では、これからも水族館とどう進めるか、これは一生懸命考えていきたいと思ってあります。","voiceIndex":162,"id":"exchange-069"},{"speaker":"武内委員","kind":"提案","question":"わかりました。私たちもできる限り知恵を絞って、アドバイス、ご提案させていただければしっかりさせていただきたいと思いますので、また歳出のほうでだれかやるかもしれないんですけれども、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-070"},{"speaker":"伊藤委員","kind":"質問","question":"言っている意味わかりますよね。だから、そういう外部委託をした数字の中に占める人件費相当分というものを実は正確にカウントしていかないと、単純に品川区の職員数が減ったからといって、それが評価に結びつくと考えにくいということを指摘させていただいて、当時の企画財政課長から検討するという話をいただいていたんですが、その後はどうなったんでしょうか、お答えいただければと考えています。","respondent":"日下部企画部長","answer":"ですから、これは改めてということで申し上げますが、この辺をどういう形でお示しできるかということについては、例えばひとつ参考的な資料として検討するとか、そういうことも含めまして、改めて少し詰めさせていただきたいと思います。","voiceIndex":166,"id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問","question":"もう話の趣旨は伝わっていると思いますよね。確かに今の法規上、いろんな仕組みがあるでしょうから、それはクリアしていただいて、だけれども、これは行政が品川区議会に対してどういう敬意を払うかですね。先ほどほかの委員もありましたけれども、例えば軽自動車税とか、それから自動車重量税、利子割交付金、配当割交付金、株式等譲渡所得割交付金ですか、軒並みマイナスになっています。お願いいたします。","respondent":"金子企画財政課長","answer":"一方で、当然のことながらでありますが、歳出も十全たる、何といいますか、漫然に取り組むのではなく、今年度実施しましたように、事務事業評価、これを厳しく重ねて。","voiceIndex":168,"id":"exchange-072"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、もし一括交付金化になって、財調がなくなって、税収が下がってきたら、本当に厳しいことになってくると予想されるわけでありますから、この一括交付金の今の現状といいましょうか、おそらく行政のいろんな話が出ているでしょうから、今の現状と、それから、これは当然区長会としても、また全国、国に向けていろんなことを発信をしてもらいたいと考えていますから。","respondent":"濱野区長","answer":"そういう意味でいいますと、さまざまな面で地方財政へのしわ寄せということについては、さまざまな面で対応を考えていかないといけないんだろうと考えています。","voiceIndex":170,"id":"exchange-073"},{"speaker":"伊藤委員","kind":"質問","question":"やっぱりきちんと現実を見て、対処していくべきだと考えていますので、指摘をぜひ改めてお願いしておきます。例えばアメリカでは、全米でやっていたものが、実際２年後には１つの州しかなくなったということもあります。これからやる事業にこんなこと言って申しわけないんですけれども、でも、こういうことも勉強してわかってまいりましたので、質問させていただいて、ご答弁いただければありがたいです。","respondent":"吉田品川区保健所保健予防課長","answer":"子宮頸がんワクチンについてのお問い合わせです。１０月に入りまして、厚生科学審議会の予防接種分科会というところが答申を出しまして、一応子宮頸がんについては効果がかなり期待できるということで、品川区としても導入を決めていくです。","voiceIndex":172,"id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問・要望","question":"正確に言うと款が違うのであまり細かくは突っ込みませんけれども、事業の点検、私たちもぜひやるように要望しました。ですから、お願いしたいことは、そういう一つ一つのさまざまな事情に対応して、事業もある意味見直しすることも必要だし、またさらに進めていくことが必要だと考えていますから、そういう観点で対処していっていただきますようにお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。歳入全般についてお尋ねをしたいと思います。それから、たばこ税も減ったりということで、自主財源、特に特別区税の増収について、繰り返しになりますが、お考えを伺いたいということと、その際、税外負担の適正化という観点で、以前検討されたということもお聞きしておりますが、それも今後の検討の１つになっていくのでしょうかということをお尋ねします。よろしくお願いします。","respondent":"武内税務課長、金子企画財政課長","answer":"もちろんたばこ税につきましては、今回このように大幅な減になっているわけですけれども、国の政策というか、区民の考え方で、禁煙志向といいますか、そういう状況の中で、たばこの売り上げ本数が下がっていくという。使用料、手数料、あるいは財産収入等々ありますけれども、私どもとしては、そういう意味で、自主財源の比率を高めるというのは、基本的な方向として持っておりますが、なかなか法制度の枠の中、あるいは都区制度の枠の中で。","voiceIndex":176,"id":"exchange-076"},{"speaker":"高橋委員","kind":"質問・要望","question":"今年度は事務事業評価を行われたとお話がありましたが、その際の視点、そしてかつて事務事業評価を行われたと伺っていますが、その際に、例えばなくすというふうな評価を、Ａ、Ｂ、Ｃ、ＤのＤとかになったものが、その後本当に、その次年度に廃止になったのか。あるいは、廃止しなければいけないというふうに判定、評価が出たらば、そのときの視点は何だったのかということをお尋ねしたいんですが。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度に行います前に、平成１３年度から１７年度にかけまして５年間事務事業評価をやってまいりました。その中で、ちょっと今手元に数がないのであれですけれども、幾つかの事業については廃止という結論を出させていただきました。","voiceIndex":179,"id":"exchange-077"},{"speaker":"高橋委員","kind":"質問・要望","question":"とすると、平成２２年度に事務事業評価をされていますので、平成２３年度予算に反映させていくということで理解しているのですが、よろしいでしょうか。そのよい例が今回の杜松小学校の跡の特養ホームの建設。このような点で、長期基本計画と柔軟な施策というところでは、どのようにお考えかということ。具体的にどのような形でというふうなところで、お願いします。","respondent":"久保田行財政改革担当課長","answer":"次の段階といたしましては、区民の方や、外部の方の学識の方のご意見も取り入れていく仕組みというものも考えなければならないということで、平成２２年度の事務事業評価とあわせまして、そういった仕組みについても現在検討しています。","voiceIndex":181,"id":"exchange-078"},{"speaker":"井上委員","kind":"確認","question":"区の受託事業などもここで行われているんですけれども、ここの負担金や使用料などは歳入のどこかにあるのかどうかということをまず確認させてください。","respondent":"間部高齢者いきがい課長","answer":"いきいきラボ関ヶ原の運営についてお答えいたします。こちらにおけます収入につきましては、区歳入に上がるものはございません。","voiceIndex":184,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"東大井の児童センターの関ヶ原分室を区が２５２万円をかけて２０００年に開設したところというふうに認識をしているんですけれども、この中で、この施設がシルバーセンターと入り口が別ですけれども、外部からは一体的に見られているというような状況かと思います。現状で区はその問題意識を持っておられるのかどうか伺います。","respondent":"間部高齢者いきがい課長","answer":"そういった意味では、制度とか趣旨が異なるということで、１階と２階に分けてありますけれども、我々といたしましては、それぞれがそれぞれの機能を果たしているものと認識しています。","voiceIndex":186,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"ちょっと質問がわかりにくかったかと思います。特にこのところでは、パソコン教室とか独自の登録をした方たちにおいての趣味の活動とか、健康体操なども費用が発生する中でされているということを品川区の中のいろいろな市民団体、活動団体から照らすと、公平性という観点で、ちょっと区への依存度が高いのではないかと思いますが、そのところは改善が必要なのではないかと思いますけれども、見解を伺います。","respondent":"間部高齢者いきがい課長","answer":"依存度の件ですけれども、私どもとしては、団塊世代の新たな社会団体としての位置づけをした団体だと認識しておりますので、当面ある一定の年限については支援を強めるということで、今この間３年ほど支援をしてきたわけですけれども、今後につきましては。","voiceIndex":188,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"団塊の世代の方々というのはまだまだ労働意欲がたくましい方たちですので、とりあえずシルバー人材センターに登録しましょうということよりも、自分たちの経験を生かした起業支援なんかができるということがもっとあれば、元気な品川のまちづくりに貢献できると思っているんですけれども、その辺をシニアネットと協議をして、もうちょっと広い活用の仕方もあるかなと思うんですが、いかがでしょうか。","respondent":"間部高齢者いきがい課長","answer":"ただ、あそこの見晴らし通りにつきましては、なかなか喫茶店がないとか、いろんなお話も伺っていますので、その点も踏まえて、地域の方にも認識をしていただけるような努力をしてまいりたいと考えています。","voiceIndex":190,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"せっかくいい施設があるわけですから、ぜひ活用していただきたいと思います。もう一つ、社会参加促進事業の中で、シニアネット活動支援というところと別に、予算のほうで次世代活躍システムに関する支援事業というところで、４００万円がコンサルタントに委託されているんですが、この事業の目的と決算額を教えてください。","respondent":"間部高齢者いきがい課長","answer":"平成２１年度の決算額については、２９９万５,４８２円となってございまして、成果品といたしましては、高齢者いきがい課および出先施設でお配りしておりますいきいきガイドや高齢者クラブのＰＲ用のチラシ等についても成果物として納品をされているものです。","voiceIndex":192,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"今、社会参加のいきいきガイドなどをコンサルタントがつくるということだったんですけれども、ヤングシニアと言われる方たちというのは十分に自立した方たちだと思いますので、行政が税金を使う範囲として本当にここまで手厚くすることがその方たちに対してどうなのかと思いますので、来年に向けて公平にここのところは判断をしていただきたいなということで、これは要望でぜひお願いしたいと思います。","respondent":"金子企画財政課長","answer":"緊急雇用創出のお尋ねです。委員、今ご指摘のとおり、全体では、平成２１年度、１５事業に充当してこれを実施しております。","voiceIndex":194,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"あるいは、モデル事業への取り組みで、そのことでもし次に本格事業ということでできるんじゃないかということもありますし、他の自治体ではそういったことに使われているということもありまして、ただ、時限的なそういうことの放置自転車対策とか、そういったところじゃない、もう少しアイデアと知恵を絞れることがあるのではないかと思いまして、これからもこういった事業があった場合に。","respondent":"金子企画財政課長","answer":"全体としても枠がありますので、その中で私どもとしてできる限り先に向けて効果が得られるようなところに活用してまいりたいという考え方で今後も行きたいと考えています。","voiceIndex":196,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひほかの自治体のことも調査をしていただいて、広く取り入れていただきたいなということで要望します。次は、総務手数料の情報公開手数料ですけれども、情報公開手数料を有料にしている理由を改めてお伺いしたいと思います。","respondent":"中川原広報広聴課長","answer":"品川区では地方自治法の第２２７条に規定する特定のもののためにする事務というのに情報公開事務が当たると解釈しまして、そのためには相当の労力を要しますので、そういった根拠で負担を求める観点から手数料をいただいているものです。","voiceIndex":198,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"区政に関心を持って開示請求をするような自立した市民の登場というのは、むしろ行政は歓迎すべきではないかと思うんですけれども、ちなみに、２３区中有料のところが何区あるのか、お知らせください。それから、平成２１年度、６６６件の請求のうち、区外の事業者や個人の方たちの割合はどのぐらいを占めているのでしょうか。","respondent":"中川原広報広聴課長","answer":"前回お尋ねのときは３区とお答えしましたが、有料とする区は２区増えました。２３区の中でです。区外と区内の比ですけれども、平成２１年度の実績では、件数では区内の個人・団体対区外の個人・団体は、２割弱対８割強となっております。区内が２割弱で区外が８割強です。","voiceIndex":200,"id":"exchange-087"},{"speaker":"井上委員","kind":"意見","question":"今の３区というのは、いつの時点の調査なのか。今、全国オンブズマンの連絡協議会で調査をした資料を見ると、中央区と品川区だけなんですが、データがどちらなのかなと思いますが、３区に増えたとおっしゃったんですが。","respondent":"中川原広報広聴課長","answer":"３区が５区に増えたと申し上げました。５区というのは、直近の、この決算特別委員会のために担当に調べてもらったところです。","voiceIndex":202,"id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"知りたい資料がちゃんとすぐに出て、そこで協働を図っていくということがこれからは求められるし、区長がこれから進めようとしている区民との協働というところでは、第一に区政を関心を持つことと思いますけれども、その辺の認識が区はどういうふうに感じていらっしゃるのでしょうか。","respondent":"中川原広報広聴課長","answer":"それで、手数料３００円というのは、品川区の手数料条例に基づいた適正な価格ということで、低所得の方には免除の制度もありますので、先ほどの自治体経営という点からも適正な手数料をいただくということで、品川区は運営しているものです。","voiceIndex":204,"id":"exchange-089"},{"speaker":"阿部委員","kind":"質問","question":"私からは７７ページの特別区民税について、それから、６３ページの人件費、それから８８ページの住民基本台帳カード、とりあえずここまでお伺いしたいと思います。それから、人件費なんですけれども、ずっと人件費減り続けておりまして、どの程度を適正と見ているのかという区の大きなお考えを伺いたいと思います。何かお考えがあれば教えてください。","respondent":"武内税務課長、金子企画財政課長、梶戸籍住民課長","answer":"先ほどお話ししたとおり、平成２０年の際の収入ということになりますので、その当時、９月に景気の悪化ということが大きく出たんですけれども。そういう意味で、人件費そのものが２.４％、繰り返しになりますけれども、上がっていないというところでは。私のほうは、住基カードの不正取得に関連したご質問についてお答えします。","voiceIndex":207,"id":"exchange-090"},{"speaker":"阿部委員","kind":"質問","question":"住基カードのほうは、大変ご丁寧なご説明いただきまして、そこまでやっていれば、まずは自治体としては安心なレベルかなと思います。それから、特別区民税のほうなんですけれども、分析と言いましたのは、品川区がこれまでとってきた政策との絡みで、こうした政策が奏効してこういう結果であったというようなことが伺えればなと思いましたので、その視点からもしお答えいただければ、ご答弁お願いします。","respondent":"武内税務課長、榎本人事課長","answer":"これは、その間の人口増という部分も非常に大きい中で、品川区民の増もあわせて、それなりの景気の状況に応じて給与所得者も増というところで、そういう政策もある中で、区民税が平成２１年度分については。その関係で、全体としては４４人増えておりますけれども、平均の賃金が下がっているというか、初任給が低い部分の職員数が多いということで、平均年齢が下がって、１人当たりの給与月額としては下がっているというものです。","voiceIndex":211,"id":"exchange-091"},{"speaker":"阿部委員","kind":"質問","question":"私は品川区はそう理解していると受けとめました。若いうちから現場を直接持って、直接知っているということが、職員の方の、あるいはひいては品川区の政策力の維持向上につながると思っておりまして、そういった意味でも、職員としてある程度のボリュームをキープすることはとても大切なことだと思っているんですが、その辺のお考えはいかがでしょうか、教えてください。","respondent":"濱野区長、榎本人事課長","answer":"これは必ずしもマーケティングリサーチのような、そういう緻密な調査によって裏打ちされたものではありませんけれども、首長としてはそういう感想を持っているところであります。そういった意味で、特に今現在は３０代後半がちょっと谷になっているという、区全体でいくと３０代後半が谷になっている部分がありますので、それを経験者採用で補っているという部分と、あとは。","voiceIndex":214,"id":"exchange-092"},{"speaker":"阿部委員","kind":"質問・要望","question":"それぞれの自治体ともみずからの強みを知って、どのように資源を配分することによって、自分たちの持っている力を最大限に生かせるかというのは、意識的に持っていくことが将来にわたって税収を確保する方法の大きな１つだと思いますので、ぜひそこは丁寧に自覚的にできるだけの資料もそろえていただきたいし、それにあわせた政策を打っていただきたいと思います。","respondent":"榎本人事課長","answer":"例えば２０代から５０代まで考えれば、大体４分の１ぐらいずつが目安かなというところなので、なるべくそれに近づけるような形で人員構成をつくっていきたいという考えです。","voiceIndex":217,"id":"exchange-093"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうから２点お伺いいたします。１点目は８７ページ、自転車駐車場使用料について、２点目は１０９ページ、放置自転車等保管料に関連いたしまして、放置自転車対策についてお伺いいたします。相談がありまして、区のほうに聞いたら、あいていると言った。この連携がとれていないということで済まされる問題かどうか。この辺、そういう情報を聞いていらっしゃったら、聞かせていただきたいと思います。","respondent":"藤木交通安全担当課長","answer":"実態としまして、五反田の定期利用は利用率といたしまして７割から８割程度ということで、現場のほうでどのような言動があったかというのは、ちょっと詳細には把握しておりませんけれども、事実としては駐輪場はあいていた。そのような状況です。","voiceIndex":220,"id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"いっぱいになった時点で、もっと申し込みが多かったら、その先に天現寺通りのほうに行きますと、駐車場もありますよね。パーキングメーター。この辺までも活用できるような、そして、放置自転車をやっぱりなくしていくような、こういう努力をしていただきたいと思いますが、その辺についてはどのようにお考えでしょうか。","respondent":"藤木交通安全担当課長","answer":"２点目の五反田駅周辺の駐輪場ですけれども、現在のところ、私ども、五反田駅、定期利用は若干あきがあるんですけれども、当日利用のほうが非常に利用率が高いということを承知しておりまして、近辺のどこか道路空間などを利用できないかですとか。","voiceIndex":222,"id":"exchange-095"},{"speaker":"山路委員","kind":"質問・要望","question":"続きまして、放置自転車対策についてですが、大井町駅東口を出まして、浅間台商店会とすずらん通りを結ぶ富士ガーデン横の道路、きれいに区のほうで整備を、あそこは私道の道路とお伺いしておりましたが、車いすの方、あるいは常時通行する方、あるいはレストラン、飲み屋も多いですので、千鳥足で歩く方たち、こういう方たち、非常に喜ばれていることをこの場をおかりいたしましてご報告をします。","respondent":"藤木交通安全担当課長","answer":"当日利用のほうですけれども、こちらは時間帯によってはやはり満杯になるような時間帯がございまして、その場合は、駐輪場の管理員のほうで、駐輪場のあいているスペースをご案内したりするなどして、利用に見えた方にはそのような対応をしています。","voiceIndex":224,"id":"exchange-096"},{"speaker":"山路委員","kind":"質問","question":"奥のほうに行きますと定期、手前のほうが一時利用で、あいているところもかなりありますので、その辺を徹底して、富士ガーデン横に自転車をとめさせないように、通行人の人を優先に、景観にも注意する、この辺を取り締まってと言うとちょっと違うかわかりませんけれども、整備をさらにお願いしたいと思いますが、今後どのように考えていらっしゃるか、お伺いします。","respondent":"藤木交通安全担当課長","answer":"大変失礼いたしました。あの周辺は、近辺、あの駐輪場の周辺も放置禁止区域のほうに拡大いたしまして、指導ならびに撤去などをこの夏ぐらいから進めている地域ですので、委員おっしゃったとおり、通行しやすい道路になるようにこれからも進めてまいりたいと考えております。","voiceIndex":226,"id":"exchange-097"},{"speaker":"山路委員","kind":"質問・要望","question":"ごそっと撤去するのは簡単ですけれども、そうじゃなく、せっかく駐輪場がありますので、駐輪場に駐輪できるように促していただきたいということですね。この辺をさらによろしくお願いいたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-098"},{"speaker":"原委員","kind":"質問","question":"私用のほうの電話ですね。午前中からいろいろお話を伺っていて、会計管理者のほうからは、いろんなところで減、減、減と来ておりまして、また、企画財政課長のほうからは、おおむね良好だよと、意外と漠然と良、良という感じなものですから、私はどういうふうにして聞いていっていいのかなという気がします。その次、区民住宅等の費用については、５日目、土木のところでお聞きしたいと思います。","respondent":"金子企画財政課長、中川原広報広聴課長、太田品川区清掃事務所長、三宅都市開発課長、冨岡高齢者福祉課長","answer":"これが４,６００万円ほどありまして、かなりのウエートを占めているという内容です。広告料の伸びについては私のほうからご説明いたします。広告料につきましては２つ原因がありまして、まず品川ガイドを全戸配布した。それが平成２１年度、年内ずっと維持をされたということによる減です。このところの電気料の額は下がっておりまして、そういったものが大きく作用しているのかなと考えているところです。私のほうからは都市基盤整備費収入についてご説明いたします。","voiceIndex":231,"id":"exchange-099"},{"speaker":"原委員","kind":"確認","question":"それからあと、ほかのところは大体そうですかという、想定していたとおりのご答弁をいただいたのでいいんですけれども、昨年から都市基盤整備費収入、これは１００倍ですよね。ただ、今日、雑入の入りで聞かせていただいておりますので、この１６億円、答弁漏れがありましたが、これが区にとって大きいのか、小さいのかと、そのご返事がなかったので、まずそれと後見制度のことの確認、２点お願いします。","respondent":"冨岡高齢者福祉課長、金子企画財政課長","answer":"今後につきましては、全体の件数が増えていくということでありますが、利用される方がどういう資力であるのかということによりますけれども、件数は増え、場合によっては。ただ、諸収入の中にある都市基盤整備費収入として扱っているわけでありますけれども、これは予算書、決算書の組み立ての中で寄附金のところにこういったものが入っておりますと。","voiceIndex":238,"id":"exchange-100"},{"speaker":"原委員","kind":"質問","question":"確かに諸収入が約６０億、そのうち雑というのが２９億ですか、半分、５０％だからバランスがとれているということで。当然民間じゃなくて区ですから、福祉政策とか、いろんなほかの面で大きいマイナス覚悟でいろいろなことをやられていっていると。１００％に近いぐらいの。ですから、ここでお願いをしたいのは、例えば入りのここのところで１６億というのはある程度すごい数字かなと思います。","respondent":"金子企画財政課長","answer":"そういう意味では、さまざま、ほかの寄附もありますけれども、こういったものについても、努力していただけるように努めていきたいと考えています。","voiceIndex":243,"id":"exchange-101"},{"speaker":"宮崎委員","kind":"質問","question":"私は成果報告書８０ページの財政調整交付金に関連して、再開発の補助金について伺いたいと思います。先日の本会議で防災まちづくり事業部長は、大崎駅西口南地区再開発への補助金の増額を答弁いたしました。この補助金の増額についてどういう経過で、いつ方針化したのか、まず伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"一定の手続を踏まえて、適正な判断の中で再査定を行ったと。その結果として、一部補助金を変更して、対応してきたというところがあります。","voiceIndex":246,"id":"exchange-102"},{"speaker":"宮崎委員","kind":"質問","question":"今の答弁でわからないんですけれども、１つ伺いたいのは、この前の質問では、北品川五丁目第１地区と西口南地区、質問したんですけれども、ほかにも補助金増額の見直しをするところがあるのかというのが１つと、あともう一つ、再開発の補助金については、国と東京都の補助金、そして財政調整の対応補正などが財源なんですけれども、こうした財源の確保の見通しがどういうふうになっているのか。","respondent":"三宅都市開発課長、金子企画財政課長","answer":"国の補助金ですけれども、今見通しを報告しまして、確保されるように調整しております。なお、都からは補助金はもらっておりません。再開発に関する財調についてのお尋ねですけれども、これは翌年度になります。翌年度以降４カ年で計算されて、対応補正と言うんですけれども、計算されて、財調のほうによってくるというふうな形でいただいております。","voiceIndex":248,"id":"exchange-103"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど北品川五丁目第１地区と南地区以外にもそういうことをやっているのがあるのかどうなのか聞きたいということと、補助金増額しますという答弁だったんですよね。これは特定財源だから、福祉だとか、いろんなところに回せないよと言っていますけれども、逆に、財調の経常経費、こっちのほうから回したりする、そういうやりくりをするのかどうなのか、聞きたいと思います。","respondent":"金子企画財政課長、片田防災まちづくり事業部長","answer":"財調のほうのお尋ねですので、私のほうからご答弁申し上げます。先ほど申しましたとおり、翌年度から４カ年、その前提となるのが都市計画交付金なんですけれども、そういう形で４カ年で入ってまいります。それとあとほかに、補助金を変更したような経過があるのかというようなお話ございましたけれども、現時点で事業として動いてきて、今後進めるというものは、先ほど申し上げたように、２件の事業ですけれども。","voiceIndex":251,"id":"exchange-104"},{"speaker":"宮崎委員","kind":"確認","question":"そうすると、終わったやつは見直しだけ、終わったのはそうだと思うんですけれども、じゃあ、これから始まるところ、今、事業、工事中だとか、そういうところは、見直しをやるということでいいんでしょうか。補償金等の修正をしたと述べていますけれども、その概要を、工事費、あと規定建物調査、補償費、概要、おおよそ、前後でどういうふうになったのか、伺いたいと思います。","respondent":"三宅都市開発課長","answer":"大崎駅西口南地区ですけれども、工事費につきましては、内容を仕様などを見直しまして、約５％低減しております。建物の補償費の関係ですけれども、例えば工作物、建物の中にある工作物など、詳細に調査をして、精査した結果、増額が出てきておると。","voiceIndex":254,"id":"exchange-105"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところがポイントだと思うんですけれども、そこのところはどうなのかということを１つ聞きたいのと、あと、やっぱり全体として事業費を下げて、コストを削減しているということなんですけれども、何で補助金が増えるのかというのは、やっぱり疑問のところですよね、南地区のところは。その見直しを踏まえて、そこに何か判断が入っているのかどうなのか、ここのところはどうなんでしょうか。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"１点目の補償費ですけれども、こちらは従前は建物の中の機械、例えば工場などの機械の補償費までは、計上漏れといいますか、建物の中まで精査できていなかった。ちょっと数字的に精査しますと、大崎駅西口南地区につきましては、総事業費が２７０億円という話をさせていただきました。その中で、補助が当初は２７億円ということで、今回精査した中で３５億円と。","voiceIndex":258,"id":"exchange-106"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、今までがどうだったのかということがありますよね。そういう仕組みになっておりますけれども、区のほうは、じゃあ、３分の２まで全部行くぞという考えがあるのか、ないのかということと、あとは、そこの政策的な判断、今回は機械まで、今までやっていなかった機械のところまで算定したと言っていますけれども、そこの気持ちのところ、考えのところを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"これまで機械などの調査をどのようにやっていたかですが、設計なども徐々に詳細なものにしてきました。建物の調査も主に外観から調査をしていたです。それがだんだん……。","voiceIndex":261,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"一般会計ももちろんありますし、それから、国民健康保険の事業の中でも、４番と６番でしょうか、それから、保険料というところでも、不納になったもの、不納と判断されたものというのが非常に多いなと感じるわけですが、これらに対する区の対応、それから傾向的にどういう傾向になっているのか、そして、それからなぜこのような状況になっていて。","respondent":"武内税務課長","answer":"現年課税分の即時消滅という意味合いですけれども、これにつきましては、今平成２２年度で課税されている方の分が、例えば本人がお亡くなりになって、全然財産もない。家族もだれもいない。そんなような場合については、執行停止と同時に、不納欠損という落とす部分です。","voiceIndex":264,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"意味はわかりました。そこの中で、現状、そういうところで不納になったというのはわかりますけれども、それに対して、この傾向はどういう傾向にあるのか。それに対する区の対応をどうされるのかということを、それと担当違うと思いますけれども、国民健康保険についても、その辺についてお聞きしたいと思います。両方お聞きしたいと思います。","respondent":"武内税務課長","answer":"それで、もちろんこれを不納欠損に落とすということは、税収の減につながりますので、極力、生活が苦しくて払えないという相談がある場合については、徴収するという前提の中で、財産調査等をしっかりして、その後、明らかに財産がないと確認しましたら。","voiceIndex":267,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません。わかりました。それとプラス、財調の話も、先ほども質問あったと思うんですけれども、財調の動きもあると思うんですね。これもどういうふうに見ていくのか。これから品川区も事業の内容を考えていろいろやっていきましょうよというところの中においては、非常にやりにくい状況になっているのではないかなと思いますが、その点に関しての今後の考え方をお聞きしたいと思います。","respondent":"金子企画財政課長","answer":"ただ、これについては、私ども注視しているんですけれども、なかなか絵姿が見えてこないという状況がありますので、これを注視しながら、対応が遅れることのないようにしていきたいと考えております。","voiceIndex":270,"id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"これからの動きが非常に大切になってくると思います。国も、一括交付金の話も出ていますけれども、どういう形で削減というのをひっくるめてやっていくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":272,"id":"exchange-111"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから成果報告書の８７ページの区民住宅使用料に関連してお伺いをします。決算書の４３ページですが、ここに区民住宅使用料について、収入未済額が３,６７６万６,５９３円、このように計上されておりますけれども、現況についてまず冒頭お伺いをさせていただきたいと思います。","respondent":"柏原住宅担当課長","answer":"ただ、残りの２,５００万円ほどなんですけれども、こちらのほうがどうしても前の年からたまっているものとかございまして、こちらのほうがどうしても滞納ということで、収納がなかなか難しいと。","voiceIndex":274,"id":"exchange-112"},{"speaker":"堺委員","kind":"質問","question":"私、今年の予算特別委員会の総括質問の中で、区民住宅のあき家対策といいましょうか、傾斜家賃制度の抜本的な改善、これが必要なのではないかというようなことも含めまして、例えば借上型住宅についても、管理戸数２９８戸のうち、あきが５１戸、建設型についても７５８戸の管理戸数のうち、２５戸、合わせて区民住宅については管理戸数が１,０５６戸のうち、あき家が７６戸あるということで。","respondent":"柏原住宅担当課長","answer":"ですので、こちらのほう、定期使用許可の部分について条例改正が必要でございましたので、提案をさせていただいたです。その他、入居の基準については、変更を行わない。現在オーナーへの借上料、こちらのほうも変更は行わないです。簡単ではありますが、概要はこういった形です。","voiceIndex":276,"id":"exchange-113"},{"speaker":"堺委員","kind":"確認","question":"今回はあき家の２棟について、そういうふうに手を打つということから改正条例案を提出されたという趣旨のご答弁かと思いますが、そこで確認をしておきたいんですが、この２棟について、新たに３月１日から入居される方については、それが適用されるわけですが、今現在入居されている方についても、おそらく新しい条件が適用されるんだろうと思いますが、その辺、確認をしておきたい。","respondent":"柏原住宅担当課長","answer":"２点のご質問です。現在の入居者の方です。新しく入ってこられる方が低い家賃ということですので、バランス等も考えまして、現在お住まいの方につきましても、同様の家賃ということでやらせていただく予定です。それから、入居率の低いところへの対策です。","voiceIndex":278,"id":"exchange-114"},{"speaker":"堺委員","kind":"質問・要望","question":"入居率が５０％切ればという前提つきで検討してくださるようなことをおっしゃっておりましたが、予算特別委員会のときにも申し上げました建設型、これについても区のほうでは対応していただきたいと申し上げました。入居率３６.８％ということで、１２戸あいたままと。したがって、建設型のこの件については、今後どういうふうにしていくつもりなのか、その辺のところをお考えをお示しいただければと。","respondent":"柏原住宅担当課長","answer":"建設型区民住宅につきましては、直接この制度を移行できるかどうかというところもありますので、その辺も検討しながら、できるかどうかということも含めまして、建設型については今後検討していきたいということで考えております。","voiceIndex":280,"id":"exchange-115"},{"speaker":"堺委員","kind":"質問","question":"もう一つ区役所のすぐ近所に新しく平成１５年２月に開設されましたファミーユ下神明という区民住宅がありますね。ですから、同じ至近距離の中で、入居する希望者は、同じ家賃を払うならば、ファミーユ下神明のほうが全然いいと。だから、どうしても棄権しちゃう。この辺がどうも関係していて、なかなか区が独自に手を施策として打てないのかなという気もするんです。その辺との絡みの考えはいかがでしょうか。","respondent":"柏原住宅担当課長","answer":"もらえない状態という形になっておりますので、こういったところも含めて、ファミーユ西品川については家賃の問題であるとかいうのは検討していきたいと考えています。","voiceIndex":282,"id":"exchange-116"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今、ファミーユ西品川について家賃補助が切れたというご答弁だったんですよね。ということは、もう国の縛りがないから、強いて言えば区独自に打とうと思えば手は打てると理解をしていいのでしょうか。","respondent":"柏原住宅担当課長","answer":"こういった関係がありますので、例えば違う用途にするということになりますと、用途廃止であるとか、いろいろな手続が出てまいりまして、それがいいのかどうかというところもありますので、そういったところも含めてトータルで検討していくです。","voiceIndex":284,"id":"exchange-117"},{"speaker":"堺委員","kind":"質問・要望","question":"用途変更すれば、それは確かにそういういろんな絡みはあるかもしれませんが、このファミーユ西品川はあくまで区民住宅ですから、用途変更はあり得ない。したがって、今回借上型住宅について手が打たれたように、建設型についても早急に手を打っていただきたいと思いますが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"今担当課長がご答弁申し上げましたように、特に建設型については、建設時に国の補助金、建設費用の補助金をいただいております。その対応がありますので、若干難しいところがありますけれども、今、借上型も含めて、引き続きそれは検討してまいりたいと考えています。","voiceIndex":286,"id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"私は７６ページ、款別決算表全般、あと歳入全般についてお聞きします。そうすると、これ、何かあったときに、使いたいときには、縛りがあって、国債というのは期限があると思うんですが、これは使えないようになっちゃうんですか。それとも、当面もう使わないよと、運用だけで、地球環境基金もそうですが、３０億円入っていますが、とりあえず載っけたんだよということなのでしょうか。","respondent":"金子企画財政課長、福田会計管理者","answer":"例えば今回の学校についてもそうですけれども、９０％は起債を起こせまして、その部分については、財調で措置されるということがルール化されておりますので、そういう意味では、一般財源を振り向ける額が非常に少なくて済みますので。これがつまり私ども会計管理室が日々の出納に使っているお金です。国債を購入いたしますと、途中で手放さない限りは、これは当然現金化されませんので、使うことができません。","voiceIndex":289,"id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"理由はよくわかりますが、ただ、ちょっと見ると、今財政当局と企画ときちんと打ち合わせしながらという話ですが、地球環境基金なんかは、３０億円のうち２９億円ですか、これが国債に回っているとなると、ほとんどそこでとまっちゃうのかなという感覚を覚えたもので、一応お聞きいたしました。これは翌年度はおよそどのぐらいの金額ベースで減るのでしょうか。わかる範囲で教えていただければありがたいです。","respondent":"金子企画財政課長","answer":"３点お尋ねいただきましたけれども、委員のお尋ねと話の立て方が違うかもしれません。私ども、まず全体の予算の総額というのは、歳入で見ますけれども、やはり全体の予算の総額も見ながらも、必要な事業についてはきちっと実施していくという形で予算を組み立ててまいります。","voiceIndex":292,"id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"福祉に当たっても、高齢者を守らなきゃいけない。区も見守り事業を一生懸命やっているというのはわかるんですが、逆に、こういうところ困っているんじゃないか、こういうところ大変じゃないかというのがありましたら、私は積極的に予算化してもいいんじゃないかと思うんですが、そういうところの配慮、対応というのはちゃんとなっているのでしょうか。","respondent":"日下部企画部長","answer":"例えば経済対策、これは平成２０年１月から補正予算を組みまして、これは切れ目なく今日まで緊急対策として進めておりますし、高齢者の福祉につきましても、これも３つの緊急課題ということで、しっかりと着実に基盤の整備、これも含めて進めているです。","voiceIndex":294,"id":"exchange-121"},{"speaker":"大沢委員","kind":"質問","question":"８３ページ、使用料及び手数料、そして８５ページ、しながわ中央公園、それと９１ページ、感染症ということ、３点お伺いをします。しっかりとしたここについてのご答弁を伺いたいと思うんですけれども、使用料及び手数料、区の歳入に占める重要性、そして今後の見込みについてお伺いをしたいと思いますので、よろしくお願いします。","respondent":"金子企画財政課長","answer":"そういう意味では、今後若干増えてまいりますが、現在の経済情勢の中で、使用料、手数料の価格が適切かどうかというのは、節目節目できちっと検討していく必要があると考えています。","voiceIndex":297,"id":"exchange-122"},{"speaker":"大沢委員","kind":"質問","question":"先ほど別のところで、区長、クリティカルマーケティングというようなお話をいただきましたけれども、マーケティングについて、使用料、手数料、区民の皆さんにより使い勝手がよく、使う気持ちを惹起してもらうような施設であり続けるべきだと思いますけれども、そこらのマーケティングの手法について、行政側では、顧客満足度という点から、どのようにそれについてお考えになりますでしょうか。","respondent":"金子企画財政課長","answer":"それは単に使用料の価格だけではなくて、さまざまなサービスの部分についても生かしていけるような形で考えていくというのが基本的な姿勢です。","voiceIndex":299,"id":"exchange-123"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは終わります。次、しながわ中央公園、８５ページについてお伺いさせていただきたいと思いますが、先ほど課長の答弁の中で、中央公園の前の学校施設があります。その中で、使用のことで、学校の前の施設を挙げて、民間及び学校法人への貸し付けを具体例を挙げて伺いましたけれども、今の現在の区内及び区外の民間への貸し付け状況、中央公園、どのようになっているのか、お尋ねしたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"一般のしながわ中央公園の多目的広場のご利用という観点でお答えをします。区内に所在する学校であれば、学校としてのご利用、どの学校も幅広くご利用いただいているところです。私立の学校もありますし、それから区立の学校。","voiceIndex":301,"id":"exchange-124"},{"speaker":"大沢委員","kind":"質問","question":"この質問につきましては、先ほど山内委員の流れの中で、私、最後にお尋ねさせていただきましたけれども、いずれにいたしましても、貸している品川区、そして利用されているほう、双方利するよう、それでまた公平になるような形。一般質問でもお話をさせていただきまして、組織変更がありました。それを踏まえまして、本来、行政につかさどる保健師の業務についてお尋ねをしたいと思います。","respondent":"吉田品川区保健所保健予防課長","answer":"精神の患者を、例えば通報があった場合に駆けつけて、実際に対応する。あるいは今回起こった新型インフルエンザのように、感染症が発生した場合に、患者のもとに駆けつけて対応する。そういったきめ細かい対応。","voiceIndex":303,"id":"exchange-125"},{"speaker":"大沢委員","kind":"質問","question":"期せずして、まさに、繰り返しになります、タイミングがあまりにもよすぎるというぐらいに、連携体制がとれて、非常に功を奏したと私は思いますが、しかしながら、ここで１つお伺いをしたいんですけれども、組織変更がされました。この４名の体制についてのお考え、去年の総括を含めながら、保健師４名に対する、専ら感染症という業務を行うに当たっての４名についてのお考えをお聞かせ願いたいと思います。","respondent":"吉田品川区保健所保健予防課長","answer":"ただ、新型インフルエンザのように大規模な感染症、あるいは災害に近いような状況になりますと、やはり保健予防課だけでは不足する部分がありますので、３センター協力の上、保健所一体、あるいは全庁的に対応する必要があるですので、通常業務。","voiceIndex":305,"id":"exchange-126"},{"speaker":"大沢委員","kind":"意見","question":"保健予防課の保健師の通常業務においては感染症が専らそれを主とするわけであって、ほかの母子指導とか、成人の予防指導、その他の健康に関する相談事象については、本庁の保健予防課の保健師は、重きを置いた場合には、そちらのほうが従になって、主は感染症ということになるということでよろしいんですね。","respondent":"吉田品川区保健所保健予防課長","answer":"保健予防課の所管している業務といたしましては、重点的にやっているのは感染症ならびに予防接種ですので、母子保健については、ご案内等は保健師のほうでいたしますが、主には該当地区の保健センターにおつなぎしているといった状況です。","voiceIndex":307,"id":"exchange-127"},{"speaker":"大沢委員","kind":"意見","question":"保健予防課の保健師においては、各保健センター、保健所に対しての司令塔の役割ということであって、実際母子相談、ほかの相談に関しては、相談業務は、そちらのほうにお願いをしてやっていただいている、こういうことでいいんですね。","respondent":"吉田品川区保健所保健予防課長","answer":"ご指摘のとおりでございまして、感染症ならびに予防接種業務については、私どものところでメインにやっておるところですけれども、母子保健業務、あるいは精神の実際の個人的な対応といった内容になりますと、各地区の保健センターに依頼をお願いしているといったところです。","voiceIndex":309,"id":"exchange-128"},{"speaker":"大沢委員","kind":"質問","question":"ですから、ぜひともそこのところを検討方をもう１回、１年たちましたけれども、これから１年たったときの検証、また検証作業をしなければいけなくなると思いますので、私は、これから、先ほどお話をしたように、多耐性菌、いろいろなもの、医学の専門家ではないですけれども、さまざま調べた中で、おそらく４人体制では足りなくなるのではないかという危惧を持っております。よろしくどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-129"},{"speaker":"土井委員","kind":"質問","question":"一番最後から行きます。住民基本台帳カードですが、何のためにやっているんですか。どうしてたくさんつくらなきゃいけないのでしょう。政府がやれと言うからだけじゃないでしょう。そこら辺をこれからどう考えるか。だから、そこら辺をどう考えてやっていくのかということも含めて、なぜやるの、どうしていっぱいやらなきゃいけないのというところと、今現在の到達点を聞かせてください。","respondent":"梶戸籍住民課長","answer":"我々のほうの、こちらの品川区民の方、先ほども件数お話しいたしましたけれども、３５万区民の方たちの大体４％強が今持っていらっしゃるような状態になってあります。","voiceIndex":313,"id":"exchange-130"},{"speaker":"土井委員","kind":"意見","question":"いや、違うんですよ。当時の政府の皆さんはね。だから、それがどう変わってきた。気持ちの悪い話ばかりが出てきて、進まないということにもなるので、その辺をどう考えるかということなんですよ。そうしないと、いろんな発想がどうも皆さんあるようなんだけれども、それを言い出していいものやら、悪いものやら、わかってないというのが今現状なので、その辺をちょっと聞かせてください。","respondent":"宮地地域振興事業部長","answer":"いろいろな状況を判断しながら、せっかくつくったものですし、お金をかけずに有効に使える手段を検討していくということは自治体の役割でもあろうかと考えております。そのような中で、有効活用を図っていきたいと考えております。","voiceIndex":315,"id":"exchange-131"},{"speaker":"土井委員","kind":"質問","question":"ぜひその意味では、区市町村でもやっていますから、いろいろやっていますから、皆さんは、ちゃんとそれを乗り越えたわけでしょうから、きっと。この件はこれで終わります。それよりも本当はもっと高いのが本来やってもらうべきものでしたよということに仮になったとすれば、それはどうなんだろう、隠れ不納欠損なのかな、そういうような形ですよね。たがら、その辺も含めて、どうお考えか、お聞かせください。","respondent":"吉岡保育課長、金子企画財政課長","answer":"そういう中で、区としてどのような保育料のご負担を願うのが一番ふさわしいあり方なのかということについては、委員ご指摘のとおり、常に考えていかなければならないし、また考えていきたいと思っているところです。関連な答弁になるかと思いますけれども、私どもでは、今現在、保育園に限らず、さまざまな施設のハード、それからソフトの運営費についてコスト表示をしようということで今検討している最中でありますので、そういう意味では。","voiceIndex":317,"id":"exchange-132"},{"speaker":"土井委員","kind":"質問","question":"要するに、そういうものを知りながら、どうしていくのか。そのために私たちの政策選択はこれですというスタイルでいかないと、皆さん、なかなかわかっていただけないと思うものですから、申し上げているので、よろしくお願いしたいと思います。減っているんだけど、それは大もとの調整３税の上がりが減ったということですよね。ですから、これは区で何とかしようにもなかなか難しい中身のことが多過ぎますね。","respondent":"金子企画財政課長","answer":"今お話にありましたとおり、全体としての中の５５％の配分であるとか、こういった問題については、特段ありませんけれども、ただ、ここのところ、特別交付金ですね。","voiceIndex":320,"id":"exchange-133"},{"speaker":"土井委員","kind":"質問","question":"来年度、それ以降の見通しについてはいかがでしょうか。","respondent":"濱野区長","answer":"配分率を変える云々の話、大きな話になれば、それは当然今やっているあり方検討会の一定の結論を見て、その上で財源配分をどうするかという再配分の話として、結果として配分率の見直しということが行われるだろうと考えています。","voiceIndex":322,"id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問","question":"乳幼児の保育とか教育、今まで保育園とか幼稚園とか、パターンがシンプルであったんですが、ここのところ、幼保一体施設とか、認定こども園とか、形態が変わってきていますけれども、品川区が幼保一体施設と認定こども園、始めた理由を改めて伺うのと、どのような役割を現在果たしているのかの２点と、あともう１点、幼保一体施設には、今、年齢区分型と幼保連携並列型と２つに区分をされているので。","respondent":"吉岡保育課長","answer":"その理由は、一番大きくは、今年度４月の待機児をいかに解消するかという中で、幼保一体施設においても、保育園部分の受け入れの人数をなるべく増やしたいという中で、並列型の開設をしたものですけれども、当然幼保一体施設という。","voiceIndex":325,"id":"exchange-135"},{"speaker":"飯沼委員","kind":"質問","question":"教育の質の向上という面では、ばらばらよりも一体のほうがより重要ととらえているのかという面では、既存の保育園への拡大とか、私立の幼稚園とか保育園の組み合わせとかが新たに考えがあるのか、その辺の方向性を教えてください。","respondent":"吉岡保育課長","answer":"あと、既存の園をさらに拡大する予定はあるかというお話ですけれども、幼保一体施設につきましては、従来計画的に設置をしてきているところですけれども、来年度、６月には、今品川学園を建設しております校地の隣地におきまして。","voiceIndex":327,"id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つには、幼保一体の中身が今発展をしているというような報告があったんですけれども、教育の要素がすごく強まっていくというところにおいては、保育園と幼稚園の違いをどう認識されているのかなというところが１つ疑問なので、お尋ねをしたいと思いますけれども、子どもの側から幼保一体施設を検証されている部分があるのかどうか。私はぜひしていただきたいなと思っています。","respondent":"吉岡保育課長","answer":"それからあと、長時間保育はやはり保育園というお話もございましたけれども、基本的にはもともとの成り立ちが、保育園については、就労等によって保育に欠ける状態のお子さんを保育するということになってありますので。","voiceIndex":329,"id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問","question":"みんながそうだねと言えるような検証がちゃんとされているかどうかというところをお伺いしたので、もう１回そこと、あと、今幼稚園と保育園がいろいろ幼保一体化の流れがある中で、全国の中では、幼稚園や保育園自体がもっと十分な議論をして進めてほしいという意見が大変多い。十分議論をして進めてほしいという現場からの声がたくさん上がっているんです。この辺の見解をお聞かせください。","respondent":"吉岡保育課長","answer":"あと、こども園についてですけれども、こちらは、まだ法律的な整備もされてございませんで、聞くところによれば、来年度の通常国会に法案が上程されて、平成２５年度の実施を目指すという政府の方針については聞いてありますけれども、今のところまだ詳細についても。","voiceIndex":331,"id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問","question":"私としては、今法案が急速に進められようとしているので、決まってからでは遅いので、今日質問させていただいたんですけれども、ポイントは、品川の今の水準をよくしていってほしい。水準が下がるような状況だったら、断固反対、拒否をしてほしいなと思うので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":333,"id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"７７ページの不納欠損、滞納の関係と、あと全般に何点かお伺いいたします。先ほど事務事業評価のお話が出ておりましたので、今回の決算特別委員会への資料提供は間に合わなかったのかということを１つ確認をしておきたいのと、来年以降は、決算に合わせて間に合わせるスケジュールで事務事業評価を行っていくのか。これを１つ確認をさせてください。","respondent":"久保田行財政改革担当課長、金子企画財政課長、福田会計管理者","answer":"平成２２年度、今行っております事務事業評価につきましては、平成２３年度予算編成のほうに反映させるということで。基準財政需要額なんですけれども、これは都区協議の中で、全体のパイといいますか、普通交付金の全体額というのがどうしてもマイナスになりましたので。各特別会計におきましても、例えば国民健康保険事業特別会計でありますと、これは１７７ページになりますけれども、上のほうにありますが、収入未済額。","voiceIndex":335,"id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、それまで５年間やっていた毎年の事務事業評価、たしか決算特別委員会に間に合っていなかったですかね。すみません。滞納額のほうです。大ざっぱに私、立て分けしちゃいましたけれども、こういう中でどういうふうに、ある意味ではお金がかかる部分ありますので、優先順位をつけて回収というものに当たる、そういうお考えがあるのかどうかというのをひとつ確認をさせてください。","respondent":"武内税務課長、福田会計管理者","answer":"それでないからというんじゃなくて、さらに引き続き時期を見て催告書をお送りする、あるいは電話催告をする、あるいは訪問をする、あるいは何ら連絡がない方については、財産調査をする等、実施しまして。例えばシステム改修をやる。このようなことはやはり現実的には避けるべきだろう。せっかく債権を回収しても、それ以上の歳出が出ますので、そのような状況は私どもは想定するべきではないと考えています。","voiceIndex":339,"id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっと具体的になりますが、例えば区役所のほうから区民のほうへ、いろいろなパターンがありますけれども、税金、お金をお支払いする。これは、各部署、区役所でどこかでまとまっているものなのでしょうか。件数とか、金額とか、それを確認させていただきたいのと、そのときに、区民に対してどのような対応をされているのかというのを確認させてください。","respondent":"福田会計管理者","answer":"それらを区役所の中でどのように統一しているのかですが、債権にはいろいろな種類がございまして、その性格によって、例えば督促通知をどう出すかとか、それぞれ異なりますので、これらを現在統一したところになっているということはございませんし。","voiceIndex":342,"id":"exchange-142"},{"speaker":"若林委員","kind":"意見","question":"そのときに、払い過ぎましたので、お返しくださいといったときに、どういう対応をされているか。","respondent":"福田会計管理者","answer":"たくさんあるわけではございませんけれども、あるとすれば、これは一般的な債権の回収ですので、まずは納入の通知というのを送付をする。そうしまして、それで期限までにお支払いがない場合については督促通知を送付する。この辺で大体回収はできていると考えております。","voiceIndex":344,"id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう対応をぜひお願いしたい。これから、品川区は小さな区役所で大きなサービスという言葉の中に、もしかしたらそういうことがなおざりになっていくのであれば、さっきの人件費の議論もありましたけれども、そういう人件費の使い方であれば、私はそれは違うと思うし、そういう意味での区役所を目指していただきたいと思うのですが、何かご答弁がありましたらお願いいたします。","respondent":"古川子ども未来事業部長","answer":"今１つの事例として、児童扶養手当のお話がございました。内容については、私、詳細存じ上げておりませんけれども、今の委員のお話につきましては、窓口対応、あるいは実務の中で十分に今後生かしていきたい、このように考えております。","voiceIndex":346,"id":"exchange-144"},{"speaker":"渡辺委員","kind":"質問・要望","question":"あるいは、団体というくくりで、その辺の割合が把握されていたら、推計でも構わないんですが、教えていただきたいのと、それとあと、リピーター率というんですか、繰り返し利用されている方、これは明確な率でなくても、把握されている場合、あるいはそういうふうな話を聞いているでもいいと思います。行きたいというのは、やはり最高の評価であると思いますので、まずこの２点から伺います。","respondent":"阿部経理課長、中山地域活動課長","answer":"移転の話はどうなっていますかという話は絶えずお聞きをしておりますけれども、今の時点で移転するということは明確に出されておりませんので、凍結というのが正しいのかどうかわかりませんけれども、変更。感覚的なもので恐縮ですけれども、半分ぐらいはそのような利用かなと考えています。","voiceIndex":349,"id":"exchange-145"},{"speaker":"渡辺委員","kind":"質問","question":"最初の東京法務局の出張所なんですが、年に２回という接点、大事な接点だと思う中で、どうですかというよりは、やはりこちらの思いは変わらぬ、地域ともども強く注視しているということは、ニュアンスの問題になるかもしれませんが、伝えられたほうがいいのではないかと思っています。常に課題はあるかと思いますが、そういった経費の考え方含めて、これから中長期的な取り組みや考え方を伺いたいと思います。","respondent":"中山地域活動課長、阿部経理課長","answer":"片や、維持管理の経費、これも経年の中でだんだん大きくなるという傾向がありますので、これはまたどういう補修が中長期的に必要なのか、この辺も冷静、客観的に分析しながら、場合によっては。当然のことながら、移転反対という立場は変わってございませんので、東京法務局との話し合いの中ではそういう立場で臨んでいきたいと考えています。","voiceIndex":352,"id":"exchange-146"},{"speaker":"渡辺委員","kind":"質問","question":"特別区税のところで、このページでいうと、区民税、軽自動車税等ありますが、運用というか、納付について伺いたいと思います。納付の割合、方法の割合を伺いたいのと、手数料、経費のところですね。利用者側が手数料負担というのはあまりないかとは思うんですが、区の中で、区とのやりとりの中で、銀行なのか、あるいはコンビニで違いがあるのかどうか、その辺を伺えたらと思います。","respondent":"武内税務課長、秋山協働・国際担当課長","answer":"平成１７年から軽自動車税、また平成１８年から普通徴収についても、コンビニで収納を開始しているんですけれども、その件数につきましては、銀行、郵便局、区の窓口は３７.３％です。件数でいきますと、コンビニが４８.６％です。個人と企業の割合ですけれども、平成２１年度は、今おっしゃったとおり、個人が３３件、それから団体が３件だったと思いますけれども、この割合ですけれども、今年に入りまして、平成２２年度ですけれども、個人が７名、企業が。","voiceIndex":355,"id":"exchange-147"},{"speaker":"渡辺委員","kind":"質問","question":"区税の納付の方法のところは、私も初めて聞いて、この数字のとらえ方は、それぞれのとらえ方があると思います。地域振興の寄附金のところでは、これも寄附の性格上、受け身にならざるを得ないのか、それとも、定額給付金のときのように、強い働きかけというか、営業的要素、それとか、区民活動支援の目的もあるので、ここは強く行けるのかどうかを伺いたいと思います。","respondent":"武内税務課長、秋山協働・国際担当課長","answer":"すみません。先ほどの答弁で、郵便局につきましては、２円ではなくて、今、資料がなくて、後ほどまた回答します。地域振興基金ですけれども、協働の１つの形、いろんな協働があるとは思いますけれども、協働の１つの形として手を出す、知恵を出す、その１つとしてお金を出すというような形を考えてありますので、私どもとしましても。","voiceIndex":358,"id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":119080,"voices":361}},{"id":"h22-20101101-4","meetingId":"h22-c-settlement","date":"2010年11月1日","dateIso":"2010-11-01","committee":"決算特別委員会","time":"午前１０時０２分～午後５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０２分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","agenda":"○午前１０時０２分開会 ただいまより、決算特別委員会を開きます。 それでは、平成２１年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"初めて決算特別委員会で質問します。改めまして、沢田洋和です、よろしくお願いいたします。私は、１１９ページの文化スポーツ振興費の中の区民スポーツ大会、そして関連して、東品川公園弓道場について、お伺いしたいと考えています。区民スポーツ大会の現状について、お伺いいたします。これらの参加団体は、どのような基準で決められているのか。","respondent":"堀越文化スポーツ振興課長","answer":"ご紹介がありましたように、平成２１年度は１万５,２７０名に参加をいただいております。区と品川区スポーツ協会と共催をして実施しておりまして、競技につきましては、スポーツ協会と各競技連盟との間で調整をしながら行っているという形になってあります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"そういった中で、今、お話がありましたとおり、区内の各種スポーツ施設が足りないというお話を、よくお伺いするわけですけれども、それにつきましては、土地がないというお話をよくお伺いします。確かに特別養護老人ホーム等の優先順位はあると思いますけれども、そういった部分で、土地があればつくられるのか、お伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"実際に、抽選の申込み件数が、全体で３割から４割減という形の実績も出ておりますので、こういう形で、ハードだけではなくて、いろいろな工夫を図って、振興の場として環境整備を図っていきたいと考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"それに伴いまして、東品川公園内にある弓道場についてお伺いしたいと思っているんです。近い将来、建て替えとか、改修の予定はあるのかどうかを、お伺いさせていただきたいと思います。他区では、総合体育館内に設置したり、武道館だったり、特に弓道は弓道場がないとできませんので、新たな新設の予定とかあるのか、どうかお伺いさせていただければと思います。","respondent":"齋藤道路公園課長","answer":"ただ、弓道場は、利用者の数がそれほど多くないのと、偏っているということもございまして、ああいう施設の維持管理、修繕の立場で言うと、お金がかかってしまうものについては、どのようなあり方が正しいのかというのは、これからちょっと検討してみたいと思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"中学校では、武道が正課、必修科目となる中で、弓道もその枠の中に入っているわけですので、特色ある学校づくりという視点からも、区立中学校で弓道を選択科目に入れるという見込みとか、見通しとか、そういった可能性はあるのかどうかも、お伺いさせていただきたいと思います。","respondent":"冠木指導課長","answer":"基本的には、柔道、そして中には剣道、それから相撲というようなところが中心になってくるということは、現状の施設上、そういったところはありますけれども、弓道についてもいろいろと調査をしてまいりたいと思ってあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"今のところ、地域ワイマックスのサービス提供のめどが立っていないと思いますけれども、現状について、お伺いします。３点目に、防災地図情報システムの改修ですけれども、これにつきましては、街頭消火器の場所を表示をするもので、点検とかで簡単にといいましょうか、迷わずできるようにするものと聞いておりますけれども、ほかに表示できるような物はあるのか、どうか、ということについてお伺いします。","respondent":"原情報システム課長、久保田行財政改革担当課長、中山防災課長","answer":"どういったものを想定したかですけれども、基本的には、大きくは地震、それから昨年度、危機管理室、あるいは保健所が中心になっていろいろございました。南東京ケーブルテレビに限らず、全国的な地域ワイマックスの現状ということでは。ただし、このシステムには、例えば備蓄倉庫がどこにあるとかということは、後で情報を追加することができますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"情報システム運営費のほうですけれども、地震等の災害時の対応ということで、お伺いしました。経費の削減につながりますので、よろしくお願いいたします。地震ハザードマップ、浸水ハザードマップ、それぞれの実績図、想定図とか、地域危険度マップなども盛り込んだ総合的なマップにしたいということでありますので、これは区民の安全のため、ぜひとも検討を進めていっていただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、１１５ページの広報紙発行経費、１１６ページ、区民相談経費、１２８ページの選挙公報、３点でお伺いします。相談業務のことなんですけれども、全般的にお伺いしたいんです。プライバシー保護の観点と、それから落ち着いて話せる、ゆったりとできる環境づくりが大事であると思うので、この点をお伺いします。この点、どう受けとめて、改善を考えていらっしゃるのか、お聞かせください。","respondent":"中川原広報広聴課長、早津選挙管理委員会事務局長","answer":"ただし、これを３９回続けるのは非常に困難であると。それにつきましては、まだまだ体制とか、費用とか、いろいろ検討しなければ、すぐにはできないという結果が出たわけです。それにしても、期日前投票は告示日の翌日から行われますので、自宅に到達しない場合であっても、印刷自体は月曜日の夕方ぐらいには何とか入るようにしてありますので、期日前投票の会場であります地域センター。","voiceIndex":19,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に新聞の折り込みでは、もう今の状況では限界にきているという確認はできるのでしょうか。それから、区民の皆さんに大事な行政を漏れなく伝えていくという姿勢で、ぜひ１００％を目指していくという姿勢がおありなのか、どうか、ちょっとそこをお伺いします。それから、インターネットなどで公表するといった方法はどうなんでしょうか、よろしくお願いします。","respondent":"中川原広報広聴課長、早津選挙管理委員会事務局長","answer":"相談業務の環境の確保につきましては、区民相談室はもとより、それぞれの職場で、お客様の声をしっかり受けとめるということで、今後も検討を考えていくように、庁舎管理と所管とも相談していきたいと考えています。ホームページについては、公職選挙法との関係がひょっとしてあるかもしれないので、ちょっと検討をさせていただきたいと思います。","voiceIndex":22,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"広報しながわなんですけれども、せめて月１回からスタートするとか、全戸配布プラスアルファで１００％を目指すという方向は、いかがでしょうか。","respondent":"中川原広報広聴課長","answer":"いろいろ経過的な作戦は立てたいと思いますが、３９回のうち、月のうち１回というのは、記事の関係でまた非常に微妙な問題がいろいろ出ます。ということですので、これにつきましては、いろいろご意見をいただきながら、さらに検討を進めていきたいと考えております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"私のほうからは、成果報告書の１１２ページ、情報システム業務継続計画検討経費について、それから、１１７ページ、区施設劣化調査および中長期改修計画策定について、それから、同じページの大崎第二地域センター跡地等活用検討経費について、それから１２５ページ、中学校消火ポンプ配備について、そして１２６ページ、防災活動拠点管理運営費について、時間があれば、１２７ページの選挙啓発費についても。","respondent":"原情報システム課長、宍戸施設整備課長、久保田行財政改革担当課長、佐藤防災安全担当課長、中山防災課長","answer":"サーバールームが区の中にもありますけれども、そういった中も、地震対策ということで、地震が来たときに。総合実施計画との関係ですが、こうした計画的修繕を行うということを計画的にやっていこうということで、年間、１施設から３施設の大規模改修。私からは、跡地活用検討経費について、お答えいたします。今後の配備につきましては、平成２０年度から平成２２年度まで、１２校の中学校に配備しておりますが、平成２３年度以降については、残りの中学校。","voiceIndex":28,"id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"区施設劣化調査ですが、防災も含めて、区の施設が最終的にすべて避難所になれば一番すばらしいのかなと、そういった中で、改善等もしっかりと行っていただくということで、ぜひとも進めていただきたい。その点を１点だけお聞かせください。ちょっとそこを教えていただきたいと思います。もう１点、災害時要援護者の方たちは、避難所はどのように設定されているのか、そこをちょっと教えてください。","respondent":"久保田行財政改革担当課長、佐藤防災安全担当課長、中山防災課長","answer":"これを踏まえまして、平成２２年度現在、私どものほうでは、区有施設の有効活用プランの策定というものを進めておりまして、ハード面に加えまして。必要であれば、防災課でも対応できるようにしております。ポンプの点検等については、業者に委託して行っております。避難所の新たな指定につきましては、町会、自治会と十分に話し合いながら、合意の上で進めてまいりたいと思います。","voiceIndex":34,"id":"exchange-011"},{"speaker":"石田委員","kind":"提案","question":"ぜひ、安心安全なまちづくりに、これからも一層取り組んでいただければと思います。ちょっと選挙啓発で１点だけ。これはお願いというか、掲示板がありますよね。人数が少ないのに、１番、２番が上にあって、張るときも非常に張りづらいですし、見る人も、上を見なければいけないので、優しい視点で、そういったこともできないのかと思います。これは提案とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"１１９ページ、文化スポーツ振興費の中で、今年、行われました芸術祭の件と伺っていきたいと思います。どのような方がやったのか、わかれば教えていただきたいと思います。実際、区から管理組合等に、最終的にお願いに行くことになるのかと思うんですが、拒否された件はあったのでしょうか、なかったのでしょうか、お願いします。ちょっと質問が多岐にわたりましたけれども、お願いいたします。","respondent":"中山地域活動課長","answer":"お断りがあったかということですけれども、管理人がいれば、何らかの形で協力はしていただいているんですが、問題は、管理人もいなく、町会でも難しい場合、これは先ほど申し上げた登録調査員、もくしは場合によっては、区の職員が直接やっております。","voiceIndex":40,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"インターネットの１２％弱に関しては、それはやって正解なのかなと思いました。５年後に大きい調査があるわけですから、問答集ではないですけれども、こういう場合はこのような対応でというような形のものを、ぜひこしらえていただいて、お示しできれば、また次にやっていただく方がやりやすいのかなと思って、それは要望します。どのぐらいの方がお越しになったか、わかれば教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"芸術祭という初めての取り組みで、周知ですとか、課題があると、我々も認識しておりますので、さらに周知を図って、定着を図っていくように頑張っていきたいと考えているところです。","voiceIndex":44,"id":"exchange-014"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は、１１６ページの総務管理費の中の広報広聴費のサービス向上運動全般について、お伺いをさせていただきたいと思います。それから、その下になるんですけれども、しながわ百景の普及というのがあるんですが、予算だと６５万円余のところが、１８万９,０００円となって、かなり執行されてないのかなというような感じがしておりますので、その点についても、説明をお願いいたします。","respondent":"中川原広報広聴課長","answer":"サービス向上運動という名称なんですが、これは、このとき、新しく長期基本計画ができましたので、今まで、イメージアップ運動と呼んで取り組んできたものを、今後、新しい長期基本計画の中で続けるかどうかという検討期間でございましたので。","voiceIndex":48,"id":"exchange-015"},{"speaker":"井桁委員","kind":"質問・要望","question":"しながわ百景なんですけれども、表示板の維持管理費と、お伺いをしたんですが、ちょっと調べさせていただいたら、現在なくなっているものもあるんですが、維持管理費というのは、これだけかかるのが妥当かどうかというのは、ちょっと考えなければいけないところだとは思うんですが、百景について、認知度というのでしょうか、わかっていらっしゃる方はわかっているんですが、新しく来た方であったりとか。","respondent":"中川原広報広聴課長","answer":"サイン計画ですが、これも、平成６年につくりましたサイン計画が、時代が変わりまして、バリアフリーとか、観光とか、景観の視点も盛り込まないと、なかなか内容が時代に合わなくなってまいりました。","voiceIndex":50,"id":"exchange-016"},{"speaker":"井桁委員","kind":"質問・要望","question":"この百景をさらに熟成をさせて拡大をしていくというようなことも、今後、ぜひ考えていっていただきたいと、これは要望です。その基準も、いろいろな方の意見を聞いてやっていっていただきたいと考えています。最後に、もう一度戻ってしまうのですが、百景についても、再度ですけれども、必ず観光に生かしていける素材だと思いますので、その点もよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、地域活動費の中の、１１９ページ、近隣セキュリティシステムの運営経費について、ご質問させていただきたいと思います。子どもが危険を感じた場合に、まもるっちの警報ピンを引っ張って、ブザーが鳴って、センターシステムのほうに緊急通報が送信されるということですけれども、平成１７年から今まで、ブザーが鳴った事件というか、そういうことが起きたか、その件数を教えていただきたい。","respondent":"矢部生活安全担当課長","answer":"まもるっちの発報事案です。運用開始から、約４万５,０００件の誤報ということで、平成２１年度末ですけれども、緊急通報につきましては６９件となっております。いずれの緊急通報にしましても、児童がけがをしたというような大きなものはございません。","voiceIndex":54,"id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"実は、この予算書の中には、協力者、ボランティア経費というのが３６９万６,０００円計上されているんですが、今回、決算書には、この項目が載っておりません。これはひとつ、どういうことなのかということ。実は私も協力者の一人として、何回か協力者通信というものですか、送られてきた記憶があります。今後、協力者としてどのようにしていくのか、教えていただきたいと思います。","respondent":"矢部生活安全担当課長","answer":"ただ、１万３,０００人の方を全部集めるというのは、一遍にはちょっと無理ですので、それぞれ職域、もしくは学校等、ジャンルごとに分けまして、協力者の研修会を実施して、今の現状、それから協力者にお願いすることなどを説明していきたいと考えています。","voiceIndex":56,"id":"exchange-019"},{"speaker":"山元委員","kind":"質問","question":"前回の予算書には、協力者のボランティア経費ということで３６０万円強計上されているんですが、今回の決算書にはその項目が載っていなかったので、それはどういうことなのかということで質問させていただきました。","respondent":"金子企画財政課長","answer":"それにつきましては、平成２２年度の決算のほうでは、きちんと分類して表示していきたいと考えております。","voiceIndex":58,"id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"次に、まもるっちのことで、ちょっと質問します。５月１０日付の委員会報告で、何か不都合があったということでお聞きいたしました。実際にどのようなことが起きたのか、また、不都合が起きた件数というのですか、発生した件数を教えていただきたいのと同時に、交換する際の経費、また、賠償はどのようになっているのかも教えていただきたいと思います。","respondent":"矢部生活安全担当課長","answer":"件数につきましては、充電のもちが悪い、充電ができないというのが約１,４００件、それからぴっぴっという発報音が鳴るというのが、やはり同じく１,４００件ぐらいということで、合計２,８００件ぐらいの件数となっております。","voiceIndex":60,"id":"exchange-021"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、不具合のものと、一時、新しいものと交換をするということなるかと思うんですけれども、不具合が起きたら取りかえますということでありますが、従来ずっと使っているものに対して、これからも、もしかしたらまたこういうことが起きる可能性はあるかもしれませんが、改善の余地といいますか、このまま使っていて大丈夫なのかというか、その辺はいかがなんでしょうか。","respondent":"矢部生活安全担当課長","answer":"ただ、２Ｇのときから、当然、部品の故障とか、通常の故障はありましたので、これは大体年間１,０００件ぐらいですので、今、１月から８月までで、５００件ぐらいの通常の故障はどうしても起きますので、これについては、やはり交換ということで対応していきたいと思います。","voiceIndex":62,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"ちょっと視点が変わってしまうのですが、まもるっちですが、ＧＰＳ機能によって、発信地点が特定されるわけですけれども、それで子どもがどこにいるかわかるということなんですが、これを、高齢者の見守り機能として、ちょっとこれは違うかもしれないのですが、何か活用することはできないものでしょうか。","respondent":"矢部生活安全担当課長","answer":"高齢者の見守りというお話ですけれども、今のところ、あくまでもＧＰＳというか、まもるっちセンターで受けているオペレーターたち、児童の安全を見守るということでやって…。","voiceIndex":64,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"職員住宅について、お伺いします。それから、地上デジタル放送なんですけれども、来年の７月２４日から、完全に移行するという形なんですけれども、国の事業を区としてお手伝いをしているという感覚ではいるんですけれども、移行した途端にテレビが見えないとか、いわゆる高齢者を含めて、機械類に弱い方にどういうふうに対処していくか、教えてください。","respondent":"榎本人事課長、伊勢総務課長、金子企画財政課長、久保田行財政改革担当課長","answer":"今後の予定ですけれども、採用の人数が増えてきた関係と、今、区が持っている職員寮の空き状況を勘案しまして。この中で、特に金額的にも大きい特別区人事・厚生事務組合というのは、２３区の事務の一部を共同処理している特別地方公共団体ということで。そういう意味で、私どもとしましては、いつもご指摘いただいておりますけれども、今後とも、予算書、決算書はわかりやすく。私どもとしましては、これまで周知の中、町会長会議や民生委員協議会などでも広く周知を図ってまいりまして。","voiceIndex":67,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"各種分担金なんですけれども、どういう団体かというのはわかっているんですよ。そうではなくて、経費の見直しはしているのかと。していないのであるならば、区として、やっぱり今の状況を考えて、迫っていかないといけないと思うんですけれども、その辺はいかがですかという質問です。","respondent":"伊勢総務課長、久保田行財政改革担当課長","answer":"例えば特別区人事・厚生事務組合の中の費用の内訳で幾つかあるんですけれども、その中で、例えば共同研修というのがありますけれども、この辺の見直しなども、具体的に申し入れをしています。低所得者等につきましては国の補助事業がありますので、そちらのほうをご紹介するなど、万全を期した対応をとっていきたいと考えているところです。","voiceIndex":72,"id":"exchange-025"},{"speaker":"稲川委員","kind":"確認","question":"歩行喫煙防止推進経費についてなんですが、まず１点は、この事業の内容について、主体は品川区だとは思うんですが、改めて、主体はどこなのか、いつからスタートした事業なのか、ちょっと確認のために、教えてください。平成２２年度の予算では桁数がまた増えて、１億円の規模になっているんですが、なぜか、その辺教えてください。","respondent":"矢部生活安全担当課長","answer":"主体につきましては品川区です。開始につきましては、条例の施行されました平成１５年１０月から進めている事業です。平成２１年度の内容ですけれども、平成２１年６月に、５,１２８万円という補正予算をつけていただきました。","voiceIndex":76,"id":"exchange-026"},{"speaker":"稲川委員","kind":"質問","question":"それからお伺いしたいのは、その警備員なんですが、警備員にする必要性があるのか。今、シルバー人材センターの方も結構頑張って、あちらこちらで指導はされていると思うんですが、警備員というと、警備会社に頼むわけですよね。先ほどの話だと、今もやられているわけですよね。その必要性があるのか、どうなのか。ここは見直しをするべきではないかと思うんですが。","respondent":"矢部生活安全担当課長","answer":"警備員をなくした理由なんですけれども、去年、実施したところ、例えばビル会社の警備員の方と同じような感じになって、何の取締りををやっているのかというご意見をいただいたので、今回は、警備員をやめまして。","voiceIndex":80,"id":"exchange-027"},{"speaker":"稲川委員","kind":"意見","question":"全体的に見て、この事業の成果なんですけれども、私も駅前清掃とか、よく早朝からやっていますけれども、２年前、３年前、４年前に比べれば、たばこの数、ポイ捨ての数が減っているんですよね。減っているのは、品川区の取り組みなのか、それとも、喫煙者のマナーの向上なのか、どちらだと思いますか。","respondent":"矢部生活安全担当課長","answer":"確かに、タバコの本数というか、ポイ捨ては減っていると思います。これは、どちらの取り組みかというと、なかなか難しいところはあると思うんですけれども、やはり両方の力が一緒になって初めて減ってきているのではないかなと思っているところです。","voiceIndex":82,"id":"exchange-028"},{"speaker":"稲川委員","kind":"意見","question":"品川区が啓発をして、喫煙者がマナーの向上をしたと。このまま続けていくのであれば、多分、まち全体も整備されてきれいになっていくので、どんどん向上はしていくと思うんですよ。いつまでも、１０年後、２０年後もこういうことをやっていたら、あまりにもちょっとナンセンスな部分だと思うので、その辺をお答えください。","respondent":"矢部生活安全担当課長","answer":"したがいまして、東京都の補助金を使って、できる範囲で、この数年間でやりまして、残りの今後の見直しにつきましては、一般財源の中で、できる範囲で努力をしていきたいと考えています。","voiceIndex":84,"id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"１２１ページの総合区民会館の大ホール吊物機構設備更新工事について、これは全くわからないのですが、細かいことなんですが、平成２０年度には、「更新工事等」と「等」が入っているんですよね。平成２１年度に関しては、この「等」がないんですよ。これは何でなのか。２年間で３億７,０００万円を超える費用がかかっているんですが、何の工事というか、更新なのか、教えていただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"長年の使用によりまして磨耗してくるということで、非常に正確な制御と、それから安全管理の面から補修、点検等をしています。きゅりあんの大ホールにつきましては、４期に分けて更新の工事を行う予定です。","voiceIndex":86,"id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"先ほど、ご答弁の中に、数年使っているとだんだん磨耗してくるとおっしゃっていましたが、大体何年周期なんですか。１０年周期なのか、２０年なのか、それとも５年なのか、５年ではちょっと早過ぎると思うんですが、その辺を。","respondent":"堀越文化スポーツ振興課長","answer":"使用頻度にもよりますけれども、一般的に言われておりますのが、ワイヤー等の部品交換は５年ごと、大規模な工事は１０年から１５年に１回行うというように聞いております。","voiceIndex":88,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１１７ページの公有財産管理費に関連して、第一日野小学校跡のＴＯＣへの貸し付けについて、ちょっと伺いたいと思います。ちょっと伺いたいんですけれども、この決定に至る手続ですね、どういうふうな手続でやってきたのかということを伺いたいと思います。それから、こういう場合の財産を貸し付けるときのルールというのは、どういうふうになっているのか、まず聞きたいと思います。","respondent":"阿部経理課長","answer":"この場合は、普通財産の貸し付けということですので、その場合の方法について、ご説明いたします。これについては、公有財産管理運用委員会という庁内の組織がございまして、そこの中で、貸付料について、適正なのかどうか判断をしていくです。","voiceIndex":91,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、不動産鑑定士の評価の内容ですね、今、鑑定結果に基づいて決定したということでしたけれども、鑑定結果、評価はどうだったのか、その内容を聞きたい。それから、評価に基づいて決定したというのは、その評価がそのままイコールでこの金額になっているのか、どうなのか聞きたい。それから、この金額について、鑑定士は、これは妥当だというふうに言っているのか、どうなのか、どうでしょうか。","respondent":"阿部経理課長","answer":"この場合は、委員のご指摘にもございましたけれども、まず、２年という非常に短い期間の貸し付けであるです。もう１点は、駐車場としての投資をしているという件もあります。","voiceIndex":93,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"今回は考慮したのか、どうか、聞きたいと思います。校庭部分２,０００m2、これが１０９万円なんですけれども、例えば１m2当たりにすると、実に、月５４５円ということになるかと思うんです。私はやっぱり、そういう近隣の値段と、営利目的で貸すということを考えると、どうしてもこの値段が納得できないんですけれども、先ほどの質問とあわせて、お願いいたします。","respondent":"阿部経理課長","answer":"鑑定評価の結果も約１０９万円ですので、ほぼ同金額と申し上げました。もう１点、減価償却の話ですけれども、当然、収益の中で減価償却を見るわけですから、区が貸す場合にも、減価償却がどうなるのか、それは貸付金額の重要な要素になると考えていますので、評価をしているです。","voiceIndex":95,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど、公有財産管理運用委員会ですか、そこで検討したという話なんですけれども、その検討委員会で何をもとにしてやったのかということなんです。もう一度、どういう手続で、どういうふうな評価でやってきたのか伺いたいと思います。１０年間というのは、いつからなのかということが決まっているのか、どうなのか。そうすると、何の経費なのかということを伺いたいと思います。","respondent":"阿部経理課長","answer":"今回の貸し付けが２年ということですので、まさに臨時的な貸し付けであるです。もう１点、適正な価格かどうかということは、再三申し上げておりますけれども、土地鑑定評価を受けて、それを踏まえまして貸付料を決めている、まさに適正に貸付料を決めているです。","voiceIndex":97,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"意見","question":"１０９万円が適正だとは、ちょっとその鑑定士の鑑定が、私自身は鑑定士ではないので、近隣の金額との比較でしか見ていませんので、１０９万円というのは、私はやっぱり、今も納得できないということ。そうしますと、今、駐車場部分は２年間という説明でした。そうして、１０年間貸すということになると、この規則から言ったら、どうなるのかということを聞きたいと思います。","respondent":"久保田行財政改革担当課長","answer":"ただＴＯＣとしましては、本格的な活用について、できるだけ速やかに着手したいという意向をお持ちですので、そういった意味では、できるだけ早く着手した場合には、また別に新たに契約をいたしまして、１０年間の契約をＴＯＣと結びまして、貸付料等も新たに算定いたしまして。","voiceIndex":99,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"公有財産を貸す場合に、適正な金額かどうか、先ほどの不動産鑑定士の評価額の結果に、私は非常に疑問がありますけれども、仮にそういう手続を踏んでいったとしても、しっかり金額を明記し、そこで合意して、それから貸し出すということを決定しないと、今、貸し出すことが先行して決まっているのではないかと思うんですけれども、そこのところはどうなんでしょうか。","respondent":"市岡総務部長","answer":"やや、今回の暫定貸し付けと将来の話とが、今、若干ごっちゃになっているような気がいたしますので、ちょっと説明をさせていただきました。","voiceIndex":101,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、２年間ですよ。その後が、品川区公有財産管理規則とは別の内容で契約するということですかと、聞いているんですよ。そこのところは、どうなのか。それから、住民要望を、本会議でも、安藤議員が紹介しました。こうした行政需要との比較、なぜＴＯＣへの貸し付けが先になるのかということも疑問なんですけれども、あわせて、伺いたいと思います。","respondent":"阿部経理課長、久保田行財政改革担当課長","answer":"品川区公有財産管理規則の中で、臨時的な場合は２年間という定めがありますけれども、そのほかに、さまざまな貸し方を想定しております。それによって期間が、当然異なってくるというものです。ＴＯＣに貸し付ける理由ですけれども、私ども、ＴＯＣの存在は、五反田地区の大きなまちのにぎわい、地域経済の中心的存在だと認識しておりますので、こういったものを確保しながらやっていきたいと考えています、お貸し出しをすると。","voiceIndex":103,"id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１１９ページの近隣セキュリティ運営経費と、１２６ページの災害時要援護者支援経費の２点でお伺いしたいと思います。あわせて、たしか、ある地点で子どもたちの危険な事態が起きた場合に、半径何ｍだったか、そこで何件かの協力者に通報すると思うんですけれども、そのやり方を、もう１回確認させていただきたいと思います。","respondent":"矢部生活安全担当課長、中山防災課長","answer":"協力者の研修会につきましては、先ほど言いましたとおり、１１月２５日、第３庁舎の６階の講堂で実施したいと考えております。委員がおっしゃるとおり、３月２４日、災害時要援護者の安全確保に関する要綱を、区長決定いただいたところです。要綱につきましては、これまで実施してきた内容を全体的に明文化したものです。","voiceIndex":109,"id":"exchange-039"},{"speaker":"武内委員","kind":"質問・要望","question":"近隣セキュリティのことですが、わかりました。私もちょっと定かではないものですから、あれですけれども。もちろん子どものことについてもそうですし、もっと先を見て、何かこれを活用することができないのかということを、今後、少し検討していただくことができないのかなと思うけれども、そこについて教えていただきたいと思います。","respondent":"矢部生活安全担当課長、中山防災課長","answer":"平成２１年度に協力者に通報した事案ですけれども、ありません、０件です。一応、私ども、今年度中に、先進的なモデル地区を選定いたしまして、個人支援プランのあり方について指導するとともに、平成２３年度からは、本格的に全区内の防災区民組織に浸透してまいるように努めてまいりたいと思ってあります。","voiceIndex":112,"id":"exchange-040"},{"speaker":"武内委員","kind":"質問・要望","question":"もう１回、後で答弁いただきます。そういった面では、区が責任持って集めた名簿なわけですから、それをもちろん町会長を含めてお貸し出しできるというか、情報は提供できるようになっていますけれども、その先のところまで、個人情報を守りながらどうやって情報を提供していくか。そうしたことも視野に入れて、早急に取り組んでいただきたいと思うんですが、それぞれお願いいたします。","respondent":"宮地地域振興事業部長、中山防災課長","answer":"ここら辺も、今後の大きな取り組みの課題としまして、力を入れていきたいと考えております。個別支援プランの作成ということで、先ほど申し上げましたけれども、まずモデル町会を実施しまして、その中身を検証し、各町会へ広めていきたいと考えております。既に、個人支援プランの調査票は、私どもでひな型をつくってあります。","voiceIndex":115,"id":"exchange-041"},{"speaker":"渡辺委員","kind":"確認","question":"私は、１１３ページ、国際交流推進事業、１１８ページ、区民まつり経費、１２０ページ、学校温水プール開放、この３点で伺ってまいります。はじめに、国際交流推進事業、ここの項目にもありますし、また、長期基本計画等を拝見した中で、確認で見ていくと、姉妹都市、あるいは友好都市交流の推進が長期基本計画のほうでも掲げられています。そんなところをどうお考えか、まず伺いたいと思います。","respondent":"秋山協働・国際担当課長、中山地域活動課長","answer":"アジアの大都市との交流ということでのご質問ですけれども、これについては、平成２１年度の予算でお認めいただきました、アジアの大都市との交流をどのように進めていくかという調査経費です。ご案内のとおり、各１３地区の実行委員会というのがありまして、ご質問にもあったとおり、地域を代表とした実行委員会ですけれども、基本的には地域センターが事務局として、それをサポートするという形で。","voiceIndex":119,"id":"exchange-042"},{"speaker":"渡辺委員","kind":"質問・要望","question":"区民まつりのところは、よくわかりました。ぜひ、お願いします。最初のアジアの大都市との交流のところで、検討経費で検討が終わっているかと思うので、何か具体的なことが、今後、あるいは報告等が、何か取りまとめ等はどのように見ていくのか。あるいは、その取りまとめの中で、何かポイントがあれば、教えていただきたいと思います。","respondent":"秋山協働・国際担当課長","answer":"アジアとの調査ですけれども、アジアの多様な交流の現況を調査いたしまして、今後の国際交流を進めるにあたっての検討資料とするということで、調査を始めております。","voiceIndex":122,"id":"exchange-043"},{"speaker":"渡辺委員","kind":"確認","question":"今現在、というふうに解釈をします。今、アジアと絞った中での方向性だとか、活用をどう考えているのか、あるいは、アジア以外にも検討がなされているのか、長期基本計画の流れから、全体を含めたことを伺いたいと思います。それから、１２０ページ、学校温水プール開放の項目から伺っていこうと思います。その辺、伺えればと思います。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長","answer":"地域ですけれども、基本的には、アジアの地域を中心に検討を進めてきたものでございまして、アジア以外のものについては、今回は検討の対象とはしてございません。私立学校の部活動とか、グループ単位でご利用いただくような貸し切りも行っていますので、そちらのほうは、人数でいきますと、約８万５,０００人にご利用いただいているという内容です。","voiceIndex":124,"id":"exchange-044"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、こういった整備は、学校が整備されるタイミングもあるでしょうし、利用者の見込みだとか、そういったことも当然反映されていると思いますが、今後、こういった整備の見込み、ここでは４校となっていますが、温水プールという位置づけは、どの程度、これから推移していくのか、伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"今後の見通しの点ですけれども、確かに、利用者から、一般利用の開放枠について、増やしてほしいという要望も聞いております。施設のあり方については、やはり区全体のいろいろな施設に対する行政需要ですとか、そういったことを考えながら進めていかなければなりません。","voiceIndex":127,"id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"今、温水プールはほんとうに、スポーツの枠組みを超えて、いろいろ行政需要という表現がありましたが、需要があるかと思います。そういった中で、生涯学習、そしてスポーツの観点から、活動する場という意味で、整備していく計画に対するポイント、今いろいろありましたが温水プールを例にとって、全般で考えたときの、施設整備へのポイントを幾つか挙げていただければと思います。","respondent":"堀越文化スポーツ振興課長","answer":"公園運動施設等につきましても、防災まちづくり事業部のほうの担当ですけれども、多目的にご利用いただけるような、例えば人工芝化等を進めて、いろいろな種目に対応できるというような形です。","voiceIndex":129,"id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"１１６ページの予算関係事務費、５０８万円余というところで、いろいろいただいた決算だとか、予算書などで、その編成過程がわかる資料を、という観点で、ちょっとお尋ねしたいんです。予算の編成は、積み上げの過程と、要求額が出た後の査定という、大きく二つに分かれると思うんですが、その積み上げ過程がよくわからないので、お尋ねしたいんです。そこをちょっと教えていただきたいと思います。","respondent":"金子企画財政課長","answer":"それに先立ちまして、最近は、隔年になりましたけれども、実施計画の策定も始めております。そういう意味で、実施計画、それから実際の予算編成を、秋から冬の段階にかけて煮詰めていくわけです。","voiceIndex":132,"id":"exchange-047"},{"speaker":"高橋委員","kind":"質問","question":"経常経費が、年間かかるというのはわかるんですが、その大枠をこのぐらいにするようにとか、あるいは、何％カットして要求するようにというような方針や基準が示されるのでしょうか。","respondent":"金子企画財政課長","answer":"先ほど、歳出に関してご説明申し上げたけれども、歳入に関しては、やはりそれまでの過程での実績等々から、翌年度の税収であるとか、あるいは、財政調整の見込みであるとか、そういったものをトータル的に計算しまして。","voiceIndex":134,"id":"exchange-048"},{"speaker":"高橋委員","kind":"質問","question":"各部、課から要求が出た後のお話で、要求額が出ます。先進自治体の品川区では、当然、このような公開を検討されたことがあると思うんですが、それについて検討された結果、公開することによるプラスマイナス、そして、今後、このように編成過程の可視化をするお考えはあるのでしょうか、お願いします。","respondent":"金子企画財政課長","answer":"私どもも、予算編成過程の可視化というのは究極の課題かなと思っているところでありますけれども、いわゆる説明責任、あるいは情報公開化という観点からは見れば、でき得る部分について、できる限り公開していくというのが基本的な考え方かもしれません。","voiceIndex":136,"id":"exchange-049"},{"speaker":"高橋委員","kind":"質問","question":"さまざまな要素があって予算は編成されていくので、公開もいろいろな問題があると思いますが、慎重に検討されるということです。とすると、今すぐに知るとすると、品川区情報公開・個人情報保護条例に基づいて情報公開を請求するという方法はいかがでしょうか。","respondent":"金子企画財政課長","answer":"私ども、これまで行ってきた予算編成というのは、あくまでも内部的な意思決定の過程と考えておりますので、現在の段階では、情報公開にはなじまないものと考えています。","voiceIndex":138,"id":"exchange-050"},{"speaker":"高橋委員","kind":"質問","question":"なじまないということですね。それは、第８条の非公開情報に当たるということでよろしいでしょうか。","respondent":"金子企画財政課長","answer":"委員ご指摘のとおりだと思います。意思決定前の情報ですので、これは非公開情報であると、考えてあります。","voiceIndex":140,"id":"exchange-051"},{"speaker":"高橋委員","kind":"意見","question":"意思決定前の情報ということで、非公開情報。そうすると、その後に幾つかの情報があるわけで、そのとき、例えば第９条か、幾つかの要素が混ざっていて、非公開情報が入っている場合は、それを除いて公開することができるという部分があるんですが、そういう部分は種分けできませんか。","respondent":"金子企画財政課長","answer":"先ほど申し上げました意図は、部分部分ではなくて、トータルとして、あくまでも意思決定過程のものですから、全体として非公開と考えています。","voiceIndex":142,"id":"exchange-052"},{"speaker":"高橋委員","kind":"質問","question":"それとの予算の関係も含めて、先ほども説明責任というお話がありましたけれども、それと情報公開との関連で、こういう理由でこういうことをしたという、区政の方向性や施策の裏付けといいますか、そういうものを説明するという意味においても、予算編成過程を、何らかの形で見える形にしていく方策をお願いしたいと思います。事務事業評価については、一言、どのような扱いをしていくのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価につきましては、評価が終わって、作業が終わった段階で、公開はしたいと考えておりますので、そのときには、議会のほうにもご報告をさせていただきたいと考えています。","voiceIndex":144,"id":"exchange-053"},{"speaker":"井上委員","kind":"提案","question":"私からは、１２７ページの選挙管理委員会費と、１１７ページ、区政アドバイザー会議経費、１１８ページの協働事業提案制度についてと、１１６ページの契約関係事務費について、お伺いいたします。そうった傍聴ができる公開の会議であるにもかかわらず、今回、私は、議事録を請求したときに、情報公開請求を求められました。そのことについて、広報広聴課の見解を伺います。","respondent":"中川原広報広聴課長","answer":"情報公開制度の原則とか、枠組みは共通ですが、その対象となる審議会とか、付属機関等の運営につきましては、それぞれの歴史的な経緯とか、現状がありますので、品川区の場合は、情報公開の運営にあたっては、各事業部長と部長職の方々が判断。","voiceIndex":147,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"今の現状はわかりました。この裁判が終わった後、９月の新聞でもいろいろと報道されているように、日額報酬に変える自治体の動きがあると理解をしたんですけれども、勤務をしている行政委員に対して、こういった厳しい判決が出ていますので、ぜひ、勤務実態のない行政委員の報酬の支払いについては、品川区には厳正に対処していただきたいと思いますけれども、見解を伺います。","respondent":"早津選挙管理委員会事務局長","answer":"条例に沿って、私ども、報酬等の支給をしておりまして、その条例の中では、勤務実態というのが必ずしも、会議に出席するというような規定というわけではございませんで、そうした中で、たまたま病気で休まれていても、減額するというような規定もございませんので。","voiceIndex":149,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"次は、区政アドバイザー会議についてお伺いいたします。ここに決算額が出ているんですけれども、この場合、１２人の委員ということで、会議の設置要綱がありましたが、委員の報酬と、この二、三年の間、会議の開催は何回行われているのかということ、それから、その決算額の内訳を教えてください。","respondent":"久保田行財政改革担当課長","answer":"１点目、委員の報酬ですけれども、これにつきましては、１回出席をしていただきますと５万円の報酬を払っているです。開催回数についてですが、ここ数年ということですから、平成１９年度、平成２０年度、平成２１年度ともに、年３回の開催です。","voiceIndex":151,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"ここで、委員の報酬が、任期ごとの委員選出時に決定するとお聞きしました。でも、地方自治法第２０３条の２の４項では、その金額と、その支給方法は条例で定めなければならないとなっているかと思うんです。ここの部分で、任期ごとの委員会のときに、この報酬額は決定されると伺ったと思うんですが、そこは間違いであるかもしれないので、これが条例で決めていかなくてもよいのだという根拠を教えてください。","respondent":"久保田行財政改革担当課長","answer":"こちらの区政アドバイザーにつきましては、任意の諮問団体ですので、その任期の冒頭に、それぞれ委員のメンバー、また報酬額等を決定して、決裁を取っているです。","voiceIndex":153,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"任意の会ということが、どういうことなのか、ちょっとわからないので、これはまた研究をしたいと思います。この区政アドバイザー会議は、２００４年の６月に初会議が開かれて、今年度、４期目を迎えるんですけれども、改めて、その成果をお伺いいたします。","respondent":"久保田行財政改革担当課長","answer":"例えば、平成２１年度につきましては、インフルエンザ等の危機管理といったものが話題になりましたけれども、そういったときには、危機管理体制、また事業継続計画ということで、民間企業での取り組みや、また。","voiceIndex":155,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"区としては、そういうお考えということで、わかりましたけれども、この会議の設置要綱で示されている目的が、「区の独自性」、「区民の期待に応える区政運営の推進のため、区長の政策形成を支援する」と、そういった明記がされているんですけれども、区長の政策形成を支援するということであれば、区長が今、一生懸命取り組まれているタウンミーティングなんかをもっと活用していただいて。","respondent":"久保田行財政改革担当課長","answer":"区政アドバイザー会議の設置目的につきましては、ただいま、委員のほうからお話があったように、区民の期待に応える先駆性のある区政経営を推進するため、区長の政策形成を支援するといったところで、取り組んでいるところです。","voiceIndex":157,"id":"exchange-059"},{"speaker":"井上委員","kind":"提案","question":"次は、協働事業提案制度なんですけれども、八潮のコミュニティレストランが来年オープンすることについて、生活者ネットワークは大変期待をしているところなんです。この運営者は公募をされていますけれども、公募の状況がどうだったのかということと、また、決まった団体が、どういうところが評価されて決定されたのかということを、お伺いします。","respondent":"秋山協働・国際担当課長","answer":"公募をした結果、手を挙げていただいた団体が１団体ありまして、そこの団体について、協働提案の審査委員会のほうで審査をしていただき、区との協働で、八潮の区民交流施設内においてコミュニティレストランを運営するにふさわしいということで、今回。","voiceIndex":159,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、いろいろとご苦労されていたり、自発的なことができることで、有意義に活動ができているというところを見てきたんです。こういう運営主体となられる方たちの軽微な工事の変更とか、そういったところも、ぜひ、協議を進めていただいて、できた後で、やっぱり使い勝手が悪かったとはなってほしくないと思うんですが、そういったことがうまく協議されているのか、どうか、現状をお伺いします。","respondent":"秋山協働・国際担当課長","answer":"要望ですけれども、ハードの部分については、こちらのほうで、運営に必要なものをそれぞれ用意するということで、また、中の備品等も、区のほうで用意をする予定ですので、お皿ですとか、そういうものについて、どのようなものがいいのかということを、今。","voiceIndex":161,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"最後、ちょっと時間が少ないので端的にお伺いいたします。契約のところなんですけれども、２００９年度で、契約落札率が平均９８％を超えていると、計算をすると、そうなるんですけれども、ちみなに、１０年前の議事録を確認したら、落札率が９５％から９６％で推移しているという答弁があるんですが、９８％を超えている今の状況をどのように思っていらっしゃるのか、見解を伺います。","respondent":"阿部経理課長","answer":"９８％がどこから来た数値か承知はしておりませんけれども、私の手元に持っているのは、制限付一般競争入札ですけれども、落札率が９４.４％です。この落札率については、適正なものだと考えています。","voiceIndex":163,"id":"exchange-062"},{"speaker":"山路委員","kind":"質問","question":"私のほうから、３点ほどお伺いします。１点目は、１１４ページ、奨学金貸付事業について。２点目は、１１８ページ、生活安全推進事業について、３点目は、１２３ページ、歴史館事業についてお伺いいたします。その辺の今後の展開は、どのようになっていくのか。そして、奨学金制度を借りて、かなり歴史も古くなってきたんですが、回収率はどのぐらいであるのか、これについてお伺いいたします。","respondent":"小林青少年育成課長","answer":"振り返ってみますと、平成１７年度、いわゆる我々奨学金と申しますと育英会、これが機構に整理される中で、基本的に、大学の奨学金は国で、高校の奨学金については、一義的には都道府県で、という形の中で、現在、この無償化、そして東京都の動きを見ながら。","voiceIndex":167,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"現場でお母さん方にお話をお伺いしますと、品川区の奨学金というのは、今までも利用する方に非常に役立っていると。高校授業料が無償になったとしても、現実の生活の上で必要な方もまだまだありますので、ぜひ、品川区は品川区なりに続けていただきたいことを要望するものです。それについての、コメント。ご答弁をお願いしたいと思います。","respondent":"小林青少年育成課長","answer":"今後の制度のあり方につきましては、今年度１年間、先ほど、ご報告いたしましたように、国の動き、そして東京都の役割、東京都の奨学金制度も、今年度、また一歩進めて拡充されておりますので、その適用関係等も含めて検討してまいりたいと考えています。","voiceIndex":169,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問","question":"では次に、地域安全のつどい、１０月７日、きゅりあんでございましたが、私も、参加させていただきまして、非常に勉強になりました。昨年も質問いたしましたが、本年度の振り込め詐欺の現状はどのようになっているか、お伺いいたします。","respondent":"矢部生活安全担当課長","answer":"内訳ですけれども、オレオレ詐欺、要は孫とか息子をかたっている被害が４２件、それから、架空請求が９件、融資保証金詐欺が１件で、区役所等を名乗る還付金詐欺については、今年度発生しておりません。","voiceIndex":171,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"品川区でも、警察でも、地域の方も、これほど注意をして、お互いに声をかけ合って、チラシを配って啓発しているのにかかわらず、まだこういう高い数字のオレオレ詐欺事件がある。発想の転換をする必要があると思いますが、これについては、今後、どのようにお考えでしょうか。","respondent":"矢部生活安全担当課長","answer":"今後とも、また発生が多いようであれば、いろいろな手段を考えていかなければならないところがありますが、やはり各警察署との連携も非常に重要になってきますので、各警察署と、今後とも情報交換をしまして、広報活動を推進していきたいと思っています。","voiceIndex":173,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"この中で、ゲストの方が、大阪は一番少ないと。電話がかかってきて、ただ聞くだけではなく、反発するので、かけた人がそこでたじろいでしまうと。品川区の品は口三つ書きますよね、口三つでどんどんしゃべって、相手からの電話を撃退するような新しいものを、町会、または審議会等で徹底して、高齢者が黙って聞かないように、高齢者に伝えていただくことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-067"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは、１１７ページの地域振興費全般的にお伺いします。それから、１２７ページ、まずはこちらの選挙費のほうからお伺いをさせていただきたいと思います。区長、おめでとうあります。４年間、よろしくお願いいたします。この平成２１年度というのは、選挙イヤーといった形で、都議会議員選挙、それから衆議院議員選挙といった、この二つの大きな選挙が行われました。","respondent":"早津選挙管理委員会事務局長","answer":"２３区で、単独選挙で行われたのは、この後、新宿区で予定されておりますが、参議院選挙の前に中野区で行われました。","voiceIndex":177,"id":"exchange-068"},{"speaker":"山内委員","kind":"質問・要望","question":"今、ご答弁がございましたけれども、前回の選挙の投票率といったものが、一つの大きな基準値になってくるといったことをおっしゃいました。来年の４月の統一地方選挙に向けては、せめて、前回の統一地方選挙の投票率よりも、有権者に行ってもらえるといった形での働きかけ、運動は徹底して行っていただきたいと考えていますので、よろしくお願いいたします。それから、掲示板の考え方について伺います。","respondent":"早津選挙管理委員会事務局長","answer":"これは基準があるというよりも、より多くの方がより安全に見れるのはどちらの方向かみたいなことを考えながらやっているわけですが、場合によっては、反対向きのほうがいいのではないかというところを、もしお気づきでしたら、ちょっと具体的にまた教えていただければ。","voiceIndex":179,"id":"exchange-069"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、１１７ページの地域振興費のほうに入らせていただきたいと思います。町会の加入率について。私も区民委員会に所属しておりますので、以前、お伺いさせていただいたことがあります。そういったところで、６割に満たないといった数字を、まずはどのように考えて、または、これに対する対応策というか、そういったものをどういうふうにお考えなのか、まずはその辺をちょっとお伺いさせてください。","respondent":"中山地域活動課長","answer":"したがいまして、一昨年あたりからかなり組織的にやっておりますけれども、町会加入のＰＲから、いろいろな組織運営、助成だけではなくて、そういうものをしっかり運営し、また未加入の方への持ちかけもしっかりやり、一人でも多くの方が入り、１００％に近づくように。","voiceIndex":181,"id":"exchange-070"},{"speaker":"山内委員","kind":"質問・要望","question":"その中で一つ、私ども自民党から要望させていただいた中で、地域コミュニティ活性化の助成金といった形で、町会、自治会に、各１０万円ずつの助成をしていただいたといった予算的な部分、行政のほうにも協力をいただいた過去があります。そうはいっても、予算的な部分も、私も町会に所属しておりますので、いろいろな話をする中で、やっぱり大変だといった話は、いまだに伺っています。","respondent":"中山地域活動課長","answer":"実際には、これを町会だけではなく、横断的に、例えばふれあいサポート活動のような関係機関との連携を持ったような面もありますので、これを一つの目として、ただし現状だけでいいのかということも十分に考えながら、さらにそのネットワークを広げるということを。","voiceIndex":183,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"総務費、人件費全体について、お伺いします。決算説明の中でも、繰り返し不断の行革による健全財政が強調されておりますけれども、現在の職員雇用形態の全体像がどうなっているのか、伺います。２０１０年４月１日現在の常勤職員数、それから非常勤職員数、人材派遣が何人か、臨時職員数、それぞれ教えてください。","respondent":"榎本人事課長","answer":"非常勤職員が１,０２１名、それから人材派遣が１２０名、アルバイトにつきましては、４月１日というところでは統計を持っていないのですけれども、月当たり大体３０人から４０人ぐらいというのが平均値です。","voiceIndex":186,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"区は、これまで健全財政、巨大な基金を、節約により生み出したというように、予算、決算特別委員会で説明してきました。伺いたいんですが、品川区の財調算定人数は、今年の４月１日で何人なのか。そのうち、保育園の部門の人数は何人でしょうか。","respondent":"榎本人事課長","answer":"これは、昨年来、基準が変わりまして、今までの差し引きの超過から逆転をしたものです。すみませんけれども、まだ細かい内訳等、基準等がまだ手元にきておりませんので、その部分は、ちょっと答えられません。","voiceIndex":188,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"そのうち、実際の常勤職員数が何人配置されて、派遣の方は何人で、前回の特別委員会の中でも、給食調理等は委託に置き換えられているので、という話がありましたけれども、その委託などの人数、その内訳、直近の数字でもいいので、教えてください。","respondent":"榎本人事課長、金子企画財政課長","answer":"保育士の数ですけれども、今年４月１日現在で、保育士は新規採用を大幅に増やしました。全部で９３名の新規採用をしていますので、全体として人員数が増えているところです。保育士の人員数が６６８名といった形です。平成２１年４月１日現在の財調人員が、先ほど、人事課長が答弁申し上げたとおり、旧基準でありますので、これで人数を計算しますと、８７１人です。これは保育士だけではなくて、保育所の人数という数字です。","voiceIndex":190,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"８７１人のうち、実際の常勤職員数と、派遣の方ですね。それから、契約期間は、何年になるのでしょうか。あわせて、派遣を保育園に入れているわけですけれども、繰り返しになるかもしれないんですけれども、派遣労働というのは、一時的や臨時的な業務に限定して行われるべきものであって、常用労働の代替禁止という原則があるんですが、派遣保育士を保育園に入れている考え方も、お伺いします。","respondent":"吉岡保育課長","answer":"委託の関係ですけれども、委託については、調理の代行委託ということで、業務内容についての仕様はありますけれども、人数の仕様はございません。それから、派遣会社につきましては、今現在、３社入っております。それから、契約は１年間の契約ということです。","voiceIndex":193,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"考え方です、お伺いします。常用労働の代替にはしてならないという原則がありますので。そのうちの１人が派遣の保育士だというお話でした。そういった点で、担任ということは、かなり重要な役割だと思うんですけれども、その役割に照らして、派遣保育士を常用的に１年間通してそこに充てるというのは、ちょっとそぐわないと思うんですが、そういった点も含めまして、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"区の仕事を、どういう雇用形態で担うのかというところは、大事な区民サービスの質の部分にもかかってくる問題ですので、質問させていただいているんですが、１年という契約期間ということなんですけれども、１年間の契約期間を超えた派遣保育士は、翌年も同じ保育園で働けるのか、どうか、お伺いします。そういった育休代替以外にはいないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"それ以外の実態もあるのではないかと思えて仕方ありませんが、いかがでしょうか。そういった点で、派遣を常用的な労働に充てないで、充てることは禁止されているわけですから、きちんと正規の職員でしっかりと雇用して充てるべきだと思うんです。１年契約を超えた派遣の人が翌年働けないという状況だと、くるくる変わってしまうと思いますし、そこら辺の状況とあわせて、お考えをお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-078"},{"speaker":"安藤委員","kind":"確認","question":"それでしたら、繰り返しになってしまうかもしれないんですけれども、今、雇われている派遣保育士は、育休か、病欠の代替にしか使っていないということなんですか。それだったら、来年、そういう方がもしいらっしゃらない場合は、こういう派遣保育士は、そこら辺がどうなのかということなんですよね。もう一度、そこら辺は確認させてください。","respondent":"榎本人事課長","answer":"人材派遣を使うというのは派遣法に定められていますので、その理由の中で使っているというものです。","voiceIndex":204,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうことを確認させていただいたのであれば、現場では、日常的に子どもを見なければいけない業務に、派遣の方が入って、その派遣の方は１年しかいられないわけですね。どこが喜ぶかというと、人件費を削減できるという区でしかないと思うんです。そこら辺はやっぱり、子どもにとっても、働く人にとっても、それから現場にとってもしっかりと働けるような環境をつくっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-080"},{"speaker":"堺委員","kind":"確認","question":"１１３ページの職員研修費に関連いたしまして、確認をしておきたいと考えています。最初に、職員の採用のほうですが、この３年、４年ほどの採用状況について、お知らせいただければと思うんです。今回の決算書の中でも、平成２１年度決算時期においては、１７８名採用となっておりますけれども、今申し上げましたが、最近の状況を、ちょっと確認をしておきたいと思うんです。","respondent":"榎本人事課長","answer":"ここ三、四年の採用状況ですけれども、平成１９年度が、全体の育児休業の任期付も含めまして９０名、それから、平成２０年度が１２０名、平成２１年度が１２７名、平成２２年度が１９１名ということで、平成２２年度は保育士の関係で大幅増になっているです。","voiceIndex":208,"id":"exchange-081"},{"speaker":"堺委員","kind":"提案","question":"この辺で、さっき私が申し上げました、新卒、いわゆる３年間も該当するという考え方と、２３区の職員の採用の受験資格というんですか、この辺の絡みは、おそらく、２３区の職員の採用のこの要旨からいきますと、要するに学歴のことについて、あるいは新卒が何年間という規定がなくて、年齢、要するに２２歳から２７歳になる人については。","respondent":"榎本人事課長","answer":"ですから、年齢的には、２８歳未満であればということなので、大学卒業後、最大６年ぐらい勤務経験がある方でも受けられるというのがＩ類の試験の現状です。","voiceIndex":210,"id":"exchange-082"},{"speaker":"堺委員","kind":"確認","question":"そうすると、ちょっともう１回、高校卒業者は、この対象に入るのかどうかですね。この年齢に達していれば、高校卒業の人も受験対象と。さっき申し上げた、同等の資格があることを人事委員会が認める人ということですから、そういう理解でいいんですか。ちょっとその辺、もう１回、確認をしておきたいんですが。","respondent":"榎本人事課長","answer":"やはり年齢要件という形になりますので、高校卒業だけの方でも、年齢が年齢要件に達していれば受験資格があると考えております。","voiceIndex":212,"id":"exchange-083"},{"speaker":"堺委員","kind":"質問","question":"わかりました。先ほど、最近の職員の採用状況を教えていただきました。おそらく、それなりの経験を経た人が新たに採用されてくるわけですから、即戦力といいましょうか、非常に重要なパワーというのですか、人材ということになるんだろうと思うんです。その辺を、区はどのように検証されているのか、ちょっと教えていただけますか。","respondent":"榎本人事課長","answer":"これは、平成１９年度の人事委員会の試験から始まりまして、実際に平成２０年４月から採用したということで、平成２０年度１８名、平成２１年度２７名、それから平成２２年度２５名という形で、事務職と土木職、建築職で採用してきております。","voiceIndex":214,"id":"exchange-084"},{"speaker":"堺委員","kind":"質問","question":"時間がなくなってきてしまったので、結論だけ申し上げます。品川区としては、徴収率がいいですから、この辺についてはちょっと難しいのかもしれませんが、新たに研修という面での捉え方で、考え方として、いかがでしょうか。","respondent":"榎本人事課長","answer":"徴収という部分ではやっておりませんけれども、品川区の場合には、清掃の体験研修ですとか、福祉施設での体験研修等をやっているところです。","voiceIndex":216,"id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"私からは、１１４ページの庁有自動車、それから同じく１１４ページの山北町との交流負担金、そして１１９ページ、文化スポーツ振興費、それから、１２８ページの農林業センサスについて、お伺いします。品川区として、このような仕組みを導入することを検討されてはいかがかと思いますが、いかがでしょうか。ないものの統計に約２８万円かかるとは、どういう仕組みなのかなと思いまして、伺います。","respondent":"阿部経理課長、中山地域活動課長、堀越文化スポーツ振興課長","answer":"したがいまして、今すぐということではございませんけれども、庁舎の耐震工事が終わりますと、駐車場がかなり使えるようになりますので。これについては、昨年からも精査して、一定金額を下げてきているわけですが、今後、また、こういうことのありようについてもしっかりと考えていきながら。芸術祭の中では、原美術館とか、そういったところのご協力もいただきまして、芸術祭の期間中。","voiceIndex":219,"id":"exchange-086"},{"speaker":"阿部委員","kind":"質問","question":"確かに、貸しスペースの場所も大切ですから、そういったギャラリー的な意味では需要を満たしているのかもしれないですけれども、区の文化振興策、あるいは芸術政策としては、そういうギャラリー的なスペースは、確かにあっていいかもしれませんが、やはり美術の部門でもきちんと発信していけるようなところは、それはそれで持っていくべきであると考えていますので、改めて、お考えを伺いたいと思います。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"文化振興事業団のほうでも、いろいろな発信のあり方について検討していると聞いていますし、いろいろな方から、そういったご要望が出ているとも聞いておりますので、先ほどのいろいろな部分、発表ですとか。内容ですけれども、基本構想の一つである、暮らしが息づく国際都市品川区を目指していくうえで、在住者に占めるアジア諸国出身者の率が高いわけですから。","voiceIndex":223,"id":"exchange-087"},{"speaker":"阿部委員","kind":"質問","question":"原美術館等々、特に原美術館との連携というのは、とてもいいことだと思います。アジアとの交流なんですが、報告書は何ページぐらいかということも、さっき伺ったと思うんですけれども、教えてください。もし今、お手元にあるのでしたら示していただいても構わないんですが。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"いろいろ区のかかわりといたしましては、例えば芸術祭の中で、どういった形がフレームとして考えられるかということで、美術館は、今まで、文化振興事業団の中で所有して展開してきておりますので、一義的には。一応、考えられるアジアの各都市の状況であるとか、都市の制度であるとか、そういうものを網羅的に調査をさせて、その内容の報告を受けておりますので、総ページとしては３００ページぐらいのものにはなっております。","voiceIndex":226,"id":"exchange-088"},{"speaker":"伊藤委員","kind":"確認","question":"私は、成果報告書の１２７ページ、選挙費に関連をして、それから、午前中に質疑が出ました地上デジタル放送推進について、それから、１１３ページにある人権啓発について、しながわ見守りホットラインについて、質問いたします。そのことの確認をお願いしたい。それから、これがもし合法であるのだったら、我々、それは４月にやりますよ。だから、そのことについての確認を、改めてお願いいたします。","respondent":"早津選挙管理委員会事務局長","answer":"ただ、こういった関係につきましては、具体的に起こった事象ということになりますと、これについては、捜査を担当する警察のほうの所管ということになりますので、念のため追加します。","voiceIndex":231,"id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"前から、そういうお答えをいただくんですよ。それはそれでわかるんですけれども、私たちは候補者になる予定なんですね。やっぱり同じルールにのっとって選挙をやらないとおかしいと、だれもが思うわけですよ。だから、そういうことがもしこれから先にあった場合に、我々はどうしたらいいんですかということを、再度、お答えください、お願いします。","respondent":"早津選挙管理委員会事務局長","answer":"実際に起こった場合には、選挙管理委員会のほうにお話しいただければ、選挙管理委員会として対応できることはいたしますし、あるいは、警察につないで、警察のほうで対応していただくとか、そういうような形になろうかと思われます。","voiceIndex":233,"id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問・要望","question":"地上デジタル放送推進について質問いたします。あれも失敗だったと思っています。だから、そういうことを聞きながら、今度は国に対して、何かしら要望していくとか、これは、本来、国の仕事なんですから、あなた方の責任でやりなさいということぐらい、はっきりと示していかないと、この地上デジタル放送の推進につながっていかないと思うんですが、いかがでしょうか、答弁をお願いいたします。","respondent":"久保田行財政改革担当課長","answer":"高齢者や町会等から要請があれば、個別に相談会や個別の訪問をして、説明もしていただけるといったようなことも聞いておりますので、そういったところ、やはり区としても、きちんと現場の状況を把握したうえで、強く要望してきましたし。","voiceIndex":235,"id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"例えば、今、たしかデジタル放送をアナログ放送に変えて、今のアナログ受像機で見れるシステムもあるということも聞きましたし、そういうさまざまないろいろな末端にまで、テレビをどうこうするかという話ですから、最後の最後は、最も身近な品川区なり、行政が対処していかざるを得ないと思うんです。","respondent":"久保田行財政改革担当課長","answer":"地上デジタル放送の切り替えにつきましては、国のほうで、平成２３年度考えておりますのが、今までＮＨＫ受信料の免除になった世帯について、チューナーとアンテナ工事の設置の助成をしてまいりましたけれども、今度は非課税世帯まで拡大をする予定だと聞いております。","voiceIndex":237,"id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問・要望","question":"しながわ見守りホットラインについて、質問いたします。ほかの自治体で見られたように、児童虐待の大きな問題があったし、それから、悲惨な事件もあったわけですから、これを教訓にしてしっかりと対処する仕組みができたということは、私どもも評価したいと思います。ですから、品川区役所の代表電話番号から、この番号につなぐことはできませんかという確認をひとついただきたい。","respondent":"中山人権啓発課長","answer":"緊急対応のケースの振り分けということになりますが、実は、子育て支援課、それから高齢者福祉課は、これまでもこうした虐待の対応をしておりまして、積み重ねてきているところです。","voiceIndex":239,"id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうですね、この番号のＰＲは必要ですよ。となれば、６６２２と６６９９の電話番号を、いろいろなところで目につくようにしなければいけない。だから、そのことについては、もう１回確認の答弁をいただきたいんですけれども、町会だけではないですよ、いろいろな組織があるわけでしょう、民生委員もあるでしょうし、そういうふうなことについて、どう連携していくかということが一つ。","respondent":"中山人権啓発課長","answer":"その辺につきましては、現場の子育て支援課、高齢者福祉課のほうとも連携をいたしまして、間違いなく対応ができるように、しっかりとやってまいりたいと考えています。","voiceIndex":241,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"私のほうから、決算書の備考の欄を、ちょっとお聞きしたいと思います。地域の方が文化センターはどこにあるんですかと結構聞かれるらしいんです。それらの考え方について、お聞きします。選挙の管理人ということなんでしょうか、区民の方にお願いにしていると思うんですが、人数が多過ぎるので、少なくしても運営できるのではないですかというご意見を聞きましたので、それについてのお考えをお聞きします。","respondent":"金子企画財政課長、中川原広報広聴課長、秋山協働・国際担当課長、早津選挙管理委員会事務局長","answer":"決算書の備考欄の流用等の文言のお尋ねですけれども、一番最初に出てまいりますのが、８５ページの下から４行目、会計管理費。不動前駅からと五反田駅から、合計６カ所について、今、調整をしながら。委員のお話の我孫子市の例ですけれども、事業執行の一つの方法とは考えておりますけれども、品川区では、協働の事業ということで、協働事業提案制度。いずれにしても、複数の目で投票が行われているのをちゃんと見るというような立場から、３人はどうしても必要ではないかというのが。","voiceIndex":244,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"備考欄ですが、ここからここに行ったというのはわかるんですが、どういうものがどこに行ってという、そういう仕組みがあるんですか。そこからの案内。ですから、そういう民間の送り迎えのバス等々があれば、ちょっとそれに相乗りさせてもらうとか、そういう方法は考えられるのではないかということで、いろいろ考えていただきたいと思っています。この民間の活用について、お聞きしたいと思います。","respondent":"金子企画財政課長、久保田行財政改革担当課長","answer":"先ほどの企画調整費より流用というものですけれども、これは、そもそも私ども企画財政課で持っていた企画調整費を、会計管理室のほうで執行するために、この会計管理費というのは、款、項ではなくて、その下の目ですので。ただ、こうしたバスを活用して、そうした施設等を回るのができるかどうかというところは、実はまだ研究等もしていない状況ですので、コストの面とか、バスを走らせるための法律的ないろいろな制約等もあるかと思いますので。","voiceIndex":249,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"時間がないんですが、要は、流用というのは、款の中で終結するものなのか、どこからどういうふうに持ってくるものなのか、そういう仕組みがあるんですか。何か規則があって、その中でのやりくりをしているのかどうかというところを聞きたいんです。","respondent":"金子企画財政課長","answer":"ただ、もちろん、予算の仕組みの中で、款、項を越えることはなくやっていくのが、私どもの基本的なルールです。ちょっと細かい説明になると、非常にたくさんになってしまいます。","voiceIndex":252,"id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"私は、総務費全般について、選挙費と人事を絡めて、質問します。品川区長選挙、区議会議員の補欠選挙において、４年前と比較して、約２％投票率が下がった。要は、区民が望んでいる区政と、品川区が実施している施策がずれているとも考えられるんですが、企画として、これだけ目立つ事業をやっていて、実際にこういう結果が出て、どうなんでしょうか、お答えください。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、長期基本計画の着実な前進、実現というものが、やはり品川区にとっても大きな課題であるというところでございまして、これまで、それに取り組んでまいりましたし、今後もそういった形で着実に推進をして、実現をさせていきたいです。","voiceIndex":255,"id":"exchange-098"},{"speaker":"須貝委員","kind":"意見","question":"今、お話しして、お話もいただきました。でも、おそらく、これだけの事業をやっているというのは、品川区は日本一、ほんとうに予算も使って、新聞、広報についても、これだけ目立っている中で、実際にこうだったというのは、ちょっとどうなのかと。でも実際は、人事院勧告は１.５％だと。でも、実際、１.５％下げようとしている。この実態について、ちょっとご答弁を、ご見解をお聞かせください。","respondent":"榎本人事課長","answer":"それから学歴等の違いも比べて、基準を出しているというのが人事院、特別区人事委員会ですので、あくまでも、それは基準が違うということで、いろいろな調べ方があるのかなと考えています。","voiceIndex":257,"id":"exchange-099"},{"speaker":"須貝委員","kind":"確認","question":"ということは、たかだか１.５％しか下がっていないから、区内経済は、区民の所得は大して下がっていないという解釈になるのではないですか。違いますか。そういうことを考えると、景気がほんとうに悪いというのをちゃんと確認しているのか、そういうこと踏まえて、我々は動かなければいけないのではないか。","respondent":"榎本人事課長","answer":"ですから、民間給与実態統計調査だけの平均値だけから、そういう判断はなかなかできないかなと考えていますし、別の厚生労働省が出している東京都のほうの地域の年額でいきますと、６６１万円とかも出ていますので、そういう調査の基準を一律に踏まえたうえで比較をしないと。","voiceIndex":259,"id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"今、お話がありましたが、でも、実際に、ではほんとうにそうなんですかと。今、統計調査の仕方がああだこうだと、違うとおっしゃっていますよ。でも実態は、企画でも、何でも、みんな大変なんでしょ。区長もおっしゃっています、区内経済は大変だと。皆さんの生活も大変だから、だからいっぱいさまざまな支援をするんだと、そうではないですか。１.５％なら支援することないでしょう。そうではありませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":261,"id":"exchange-101"},{"speaker":"若林委員","kind":"質問","question":"１１９ページのシルバー大学について、お聞きいたします。この事業の目的を伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"シルバー大学の目的です。高齢者の方々が生きがいを持ち、心豊かな生活を送れるよう、シルバー大学という形で、学習事業を体系化しまして、幅広い学習事業を提供しているものです。班別活動等も取り入れまして、学生間の交流も図っている、これを目的としている事業です。","voiceIndex":263,"id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"一つが、ふれあいアカデミーの中で、１年目のふれあいコース、それから、その中で、希望者が上がっていく２年目、３年目のいきいきコース、それからもう一つは、これは単年度のコースになるのでしょうか、うるおい塾という三つのコースがありますが、このコースの設定の仕方が、この事業の目的にどのようにかなっているのか、ここら辺をお聞きしておきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"後ほど、コースの概要についてはご説明しますが、シルバー大学のうるおい塾では、一芸ボランティア講師という、学んだ成果を生かしていただくというような形で、一定の技量をお持ちの方は講師としてご活躍をいただいておりますが、そういった意味で。","voiceIndex":265,"id":"exchange-103"},{"speaker":"若林委員","kind":"確認","question":"ちょっと角度を変えまして、財源について、お聞きをいたしたいと思います。あわせて、平成１９年度、平成２０年度の決算の資料では、当時は、教育費の中で入れ込んでいたと思いますけれども、この財源構成が、そもそも補助金として出ておりませんでしたが、当時はなかったのか、どうかということの確認。それから、補助金のあることによって、事業として何か縛りがどうしても出てくるのか。","respondent":"堀越文化スポーツ振興課長","answer":"実際の運営にも携わっていただいておりますので、どのような学習を進めるのかといった観点、目的意識を持つということからも、そういった成果を得るための工夫を図っているものです。それから、財源の話ですが、東京都の高齢社会対策包括補助を受けております。","voiceIndex":267,"id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"９名体制で四つの事業をやられておりますけれども、例えばシルバー大学をやっていく中で、またそのほかの三つの事業を行っていく中で、この職員体制で、果たして今十分なのかという疑問に、一つお答えいただきたいと思います。そうしますと、例えば区民講座の中で、もう少し広い視野で、よりレベルアップを望む方々、高齢者のニーズにこたえる見直しというのは、どうでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"科目については、シルバー大学に限らず、区民大学等ありますので、そういった中で、さまざまいろいろな教育機関等とも連携しながら、レベルアップについては、現在も検討していますし、常に検討を続けていきたいと考えております。","voiceIndex":269,"id":"exchange-105"},{"speaker":"須藤委員","kind":"質問","question":"１２７ページ、選挙費、１１９ページ、文化スポーツ振興費、１１２ページの職員給与費、退職手当について質問します。最初に、１２７ページの選挙費についてで、過日の区長選挙、いろいろお話がありますけれども、私は、選挙管理委員会の方々が努力して３１％を越える数字を出したと思っているんです。","respondent":"早津選挙管理委員会事務局長","answer":"参議院選挙に投票するような方は投票意識のかなり高い方、そういう方にＰＲをするのが、なかなかつぼを得ているのではないかというような考え方から始めたもので、２カ月前から始めたことがあります。","voiceIndex":272,"id":"exchange-106"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほどのお話のように事前にポスターを張ったり、選挙期間中にのぼりつけたりというようなことは、写真を持ってくれば、こういう形になりますよとか、しっかりその辺は、選挙管理委員会のほうでも、それは警察の事項だから云々ということではなくて、どういう対処をしますということを、ここで言ってくれないと、これから若い人たちが出てくるので、私たちも、そういう人たちに。","respondent":"早津選挙管理委員会事務局長","answer":"事前の段階では、選挙管理委員会としても精いっぱいのことを行いますけれども、一旦起こってしまったものについては、そういう面での制約があるということは、お酌み取りいただきたいと考えています。","voiceIndex":274,"id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"やはり、昨日も華道の先生方が、イベントホールで華道展をやっていたんですけれども、芸術祭参加関連事業とかと銘打っていて、先生方、弟子の方たちも非常に気合が入って、やりましたというお話を伺った。それから、文化芸術・スポーツ活動支援事業というのがあるんですけれども、文化芸術とスポーツと、この辺の１,１００万円ぐらいを、平成２１年度はどういう切り分けでやられたのか、教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"今まで、文化振興事業団で行っていたコンサート、それから、区のほうで行っていたアマチュア団体の発表会の事業を、集中的、一体的に実施して、相乗的な効果による盛り上げを図り、区内全域での取り組みを図っていきたいです。","voiceIndex":276,"id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"その下のほうに、地域スポーツ推進経費というのがあるんですけれども、東京都から委託費がきているんですけれども、これは、国体を目指しての意味で、近年こういう数字なのか、今までもずっときている形なのか。それから同時に、地域スポーツの推進ということで、４事業、高齢者スポーツの普及で１事業、書いてありますけれども、これは何と何なのか、教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"平成１９年度から平成２１年度まで、東京都から委託を受けて、今年の３月、品川・大崎地区に地域スポーツクラブが誕生いたしまして、さまざまな活動、教室、大会、それから各サークルの開放ですとか、そういった形で進めているところです。","voiceIndex":278,"id":"exchange-109"},{"speaker":"須藤委員","kind":"意見","question":"職員費、退職手当のほうで、組織で人というのは、やっぱり人材は確保する、育成する、それから、活用するということなんで、もう１０年ぐらい前に、私たちはやっぱり団塊の世代を迎えて、組織としてトップのほうがだんだん少なくなると、それでどうするんだという話をしたときに、６０歳から６５歳まで定年延長というような、だんだん延びていくという話があったんですけれども、そのあたりは、今。","respondent":"榎本人事課長","answer":"そのプランでいきますと、平成２５年度末の退職者から定年を、６０歳ではなく６１歳に延ばしていくと。以降、３年に１歳ずつ延ばしていくということで、最終的には、平成３７年度末までかけて、定年を６５歳に延ばしていくというのが、今のところの国の案になっています。","voiceIndex":280,"id":"exchange-110"},{"speaker":"須藤委員","kind":"意見","question":"平成２５年度からということですけれども、品川区は、この一、二年でその辺がずっときてしまうので、平成２５年まで待っていれば、またそれなりのメンバーが育ってくるだろうと思うんですけれども、この一、二年をどうするのかなと。","respondent":"本間副区長","answer":"それから一方では、やはり区が出資しております第三セクターとか、区とのかかわりの強い法人からも、優秀な管理職をぜひとも派遣してもらいたいという要請もございまして、ひいては、区民サービスの向上につながるという面もありますから、このような点等を総合的に考えまして。","voiceIndex":282,"id":"exchange-111"},{"speaker":"川西委員","kind":"質問・要望","question":"質問を続けます。この成果、実績について伺います。それから、防災行政無線のことですが、スピーカーの取り替え、１４４台、防災行政無線については、反響が悪いとかいう意見が長年ありまして、これが取り替えられたことによって、どれだけ改善されたか、具体的に町会・自治会、区民の皆さんから、声がどのように挙がってきているのか、伺います。","respondent":"伊勢危機管理室長、榎本人事課長、中山防災課長","answer":"新型インフルエンザの対策ですけれども、基本的には、全庁体制をとりまして、危機管理室が中心になりまして、保健所と連携して、区の窓口等。研修支援ですけれども、幾つかメニューがありますけれども、自己啓発助成ですとか、自主研究グループの助成、それから、公共政策大学院への修学助成。それからもう一つ、光化学スモッグ注意報などをお聞きになっていると思うんですが、以前、私どものところにいた職員が吹き込んだものでございまして。","voiceIndex":285,"id":"exchange-112"},{"speaker":"川西委員","kind":"質問・要望","question":"最後からいきますけれども、スピーカーの取り替えの結果は、今、伺いました。そういうふうに、例えば、防災無線の補完的なものとして、区のホームページへは何分後に掲載されるのか。その辺、伺います。ですから、庁内の横のつながりといいますか、そういうものを、今後、考えていただきたいと思います。これは要望で結構です。ホームページのこと、研修支援のグループのこと、二つだけお願いします。","respondent":"中川原広報広聴課長、榎本人事課長","answer":"ホームページのお知らせですが、行政無線よりもきめ細かな情報をお知らせしております。ほぼ同じぐらいかと思います。発信が本部で決まりますと、その都度、流しているような形になりますが、ちょっと確認させていただきたいと思います。ただし、たしか一つのグループが中止になったところ、また別のグループができてきたりとかして、大体６グループぐらいが、平均して活動している状況です。","voiceIndex":289,"id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"区長は、さきの選挙が終わった後に随所で、選挙中もだったでしょうか、長期基本計画について粛々と進めていくと、そういうお話をされておられました。長期基本計画を改めて読んでみると、随所に、「輝く笑顔住み続けたいまちしながわ」と記されているんですけれども、笑顔輝くとは、どういうことを意味しているのか、まずそこからちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"長期基本計画のご質問ですけれども、長期基本計画は基本構想で掲げます将来像、輝く笑顔、住み続けたいまちしながわの実現を目指すために進めていく、１０年間の行政計画ですので、そうした中で、随所に笑顔とか、輝くという言葉を使わせていただいておりますけれども。","voiceIndex":294,"id":"exchange-114"},{"speaker":"南委員","kind":"質問","question":"しかし、実際はどうか、そこが問題だと思うんです。したがって、区長は、この選挙中に認可保育園２カ所をつくる計画を急遽掲げざるを得なくなった状況もあると、私は認識しておりますので、長期基本計画のこの部分で質問をしたいと思っているんです。その点について、改めて、ご見解を伺いたいと思います。例えば、３カ月から４カ月の赤ちゃんは、音が聞こえれば耳を傾けますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"児童福祉法第１条、第２条、第３条を、きちんと意識して、認識されて、検討されて導き出されているとは思うんですけれども、しかしどうも、この間の区の姿勢を伺っていると、どうもその辺については、そういうふうには思えないんです。したがって、長期基本計画のこの総務費の場面で、そういう質問をしてみましたので、ぜひ、答弁をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":300,"id":"exchange-116"},{"speaker":"鈴木委員長","kind":"質問","question":"私のほうから、答えすると、今の質問自体が、款別の中で民生費に入っている部分だと、皆さんもご理解いただいていると思います。その辺で、今の質問に対するご答弁は、理事者側としても、できないのではないかと思います。南委員、質問の形式を変えていただいた上で、今の内容ですと、ちょっとお答えができないと判断いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-117"},{"speaker":"南委員","kind":"質問","question":"長期基本計画は、この年度が初年度なんですよね。したがって、ここの長期基本計画の問題を実施した年ということで、質問させていただいています。先ほどから申し上げておりますように、〔「何ページなのか」と呼ぶ者あり〕長期基本計画の７６ページということを言っています。総務のところですからいいではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"先ほども申し上げましたように、長期基本計画は、この年からスタートしているわけですね。したがって、この年の総論として、長期基本計画、今日的な問題を含めて、質問しているんですけれども、それを制限するということは、私は、あってはいけないと思いますので、ぜひ、質問を続けさせていただきたいと思います。ぜひ、委員長として計らっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-119"},{"speaker":"南委員","kind":"質問","question":"長期基本計画を策定するにあたって、どういうふうな検討をしたのかと質問しているんですから、だってそうしたら、どこの款だってそういうふうになってしまうではないですか。民生費だからというふうに、民生費に押し込めてしまうというのは、私は違うと思いますよ。どういうふうに検討してきたのかということを聞いているんですから。おかしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-120"},{"speaker":"南委員","kind":"質問・要望","question":"だって、品川区政全般が、長期基本計画に基づいて区政運営をしているわけですから、そこのところを、全然質問できない、民生費だとか、高齢者福祉の部分だとか、ああだとか、こうだとかと狭めるということはおかしいと思いますよ。ぜひ、質問をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":308,"id":"exchange-121"},{"speaker":"南委員","kind":"質問・要望","question":"しかも、区として、長期基本計画の策定にあたっては、全庁を挙げて取り組んできたという点ですから、ぜひとも、どこの問題でも、堂々と受けて答弁をしていただきたいと思います。それだったらできないんですか。総務のところの款別審査、ここのところで、区の一番基本的な区政運営をする長期基本計画のことを聞いているんですから、そんな制限をしないでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-122"},{"speaker":"鈴木委員長","kind":"質問・要望","question":"先ほど来、申し上げておりますように、今までも、款別審査の段階において、ページ数のご指定をいただいて質問をしていただくように、その話も出ておりますが、長期基本計画がこの決算の段階で、どのページに示されているか、そこの部分を、私のほうからお聞きしたいと思います。南委員、その辺をお考えのうえで、質問を続けていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"何回も申し上げておりますように、区の基本姿勢、そこのところの長期基本計画について、どういう角度で策定したのかという質問をしているのに、させていただけないのは、甚だ私は残念です。そのことは申し上げておきたいと思います。そして、これからの審査にあたっては、区の基本姿勢のところですから、やっぱり枠を広げてやっていただけるように、配慮していただきたいと思います。終わります。","respondent":"鈴木委員長","answer":"今、最後に終わられましたが、私のほうは、あくまでも款別審査の中でのお答えだと考えています。ページ数のご指摘もいただいたように、一番最初の副委員長の説明の段階でも、既に皆様のご了解をいただいた部分を、ご指摘いたしておりますので、私は同じように運用してまいります。","voiceIndex":312,"id":"exchange-124"},{"speaker":"三上委員","kind":"質問・要望","question":"昨年の決算特別委員会でも、この件についてどうなっているんでしょうかということで、お伺いをしております。それから、要するに、難視聴対策というよりも、個人の問題で、来年になっても、自分でチューナーだとか、アンテナだとか、つけることができないという方について、今度は区民チャンネルも見れなくなるのではないかと考えるんですけれども、この点はどうお考えでしょうか。","respondent":"榎本人事課長、阿部経理課長、久保田行財政改革担当課長、早津選挙管理委員会事務局長","answer":"実際には、今年２１名受講して、２年目の職員が受講しましたけれども、そういう実演をして。当然のことながら、私どもで所有している約２０台の電動自転車については、今申し上げた充電器で充電をしているです。ケーブルテレビ品川のほうの視聴可能世帯は、今現在、８４.５％ですので、品川区内の８４.５％の方につきましては。「何人も、選挙に関し、得票を得若しくは得しめ又は得しめない目的をもって選挙人に対し署名活動をすることができない」という規定ですが、これには。","voiceIndex":314,"id":"exchange-125"},{"speaker":"三上委員","kind":"質問・要望","question":"ケーブルテレビについても、しっかりと区民チャンネルが見られる体制をつくるためにどうするか、国では、地上デジタル放送で即刻対応できない人には、ＢＳで見られるようにするとかということが発表されておりますけれども、こういうことで見ていっても、結果的には、いずれ時期が来れば対応しなければならないわけですから、そういった点での対応をしていかなければならない。いかがですか。","respondent":"早津選挙管理委員会事務局長","answer":"条文は、ちょっと違ってくる可能性があるということになります。","voiceIndex":319,"id":"exchange-126"},{"speaker":"三上委員","kind":"質問・要望","question":"これについて、もう来年の４月の区議会議員選挙、皆さん対応する期日が決まっていますよ。だけれども、１０月という、突然生じてきたような日程の中でやるとなったら、区民の皆さんも、こういう時期に署名運動をやってはいけないんだという意識を持っていただくような啓発の仕方をやっていっていただきたいと、こう思います。","respondent":"早津選挙管理委員会事務局長","answer":"私ども、公正な選挙が実施されるように、あらゆる機会をとらえてＰＲ等に努めてまいりたいと考えております。","voiceIndex":321,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"騒がしかったですけれども、最後はさわやかにいきたいと思います。第２款総務費、２項の地域振興費、４目の防災対策費、こうやって質問は入らなくてはいけないんです。１２５ページ、中学校消火ポンプ配備、４校、３６９万７,７１０円。同じく１２６ページ、防災関係組織経費の防災訓練経費、５１２万５,４２３円。消火ポンプのほうは安かったのかなと思いますけれども、その辺をお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"今の金額が少なくなった点につきましては、荏原第二地区、荏原第三地区の地区総合防災訓練が、雨のために中止になったため、執行できなくなって、金額が少なくなっております。","voiceIndex":324,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"今年は、小学校の４年生が消火器を持って消火する場面もありました。そしてまた、現実的にも、中学生というと、やはり即戦力というのでしょうか、ほんとうに路地の裏から裏まで知っていますから、いざ災害のときには、自分の家庭の安全を確かめた後は、ほんとうに役に立つのかなということで、このような訓練を子どもたちにしていくというのは、大変重要だなと思っているところです。","respondent":"佐藤防災安全担当課長","answer":"地区総合防災訓練の中学生の参加なんですが、平成２０年度、平成２１年度に配備した８校が、翌年、訓練を実施して参加する形態をとらせていただいております。","voiceIndex":328,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"防災訓練の中で、売りものになっているというのでしょうか、区民消火隊の訓練の披露、消防団のポンプの披露、そして、一斉放水、大変に見た目もきれいなんですけれども、区民消火隊の参加率ですね。各地区に区民消化隊ができていると言いますけれども、この方たちがすべて訓練に参加しているのか、どうか、その辺の参加率というものを、ちょっとお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"全体は、数字としては、７割から８割と推測しているんですが、荏原地区については、まだ実施していない地区もあるんですが、実施予定ということで、ちょっと数字を挙げしますと、７７町会のうち５５町会が、Ｄ級ポンプ、Ｃ級ポンプの放水訓練を披露すると伺っております。","voiceIndex":330,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"ただ、問題は、その参加しないのが、どういう理由なのか。実は、こんな話も聞いたんです。ただ、今回、初めてみんなに話をして、２０年ぶりで参加したという町会がありました。私も、それを見せていただきましたけれども、その辺のポンプが眠ってしまっている、それに対して、しっかりとそれがわかっているのか、どうか、その辺をちょっとお聞きしたいと思います。","respondent":"佐藤防災安全担当課長","answer":"そういう隊につきましては、私たち防災課が、どういう点に問題があるか、具体的に防災区民組織に確認し、例えば、指導を受けづらいということであれば、消防署、消防団と連携して、実際に中学校と一緒に合同訓練をし、隊が組めなかったところについては、今年。","voiceIndex":332,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"披露する機会がなかったものですから、訓練ができなかった、そう思っているんですけれども、やはり、区民消火隊、ある程度ポンプの披露ができますということになれば、やはり参加意識も高まったり、訓練日を設けたりすると思うんです。あるいは、雨で中止になったら、何かそういう訓練をする、そのような手だてというものを考えていかなくちゃいけないと思うんですが、その辺、いかがお考えでしょうか。","respondent":"佐藤防災安全担当課長","answer":"来年度、やはり消防署、消防団と連携して、ある程度目に見えてわかるようなマニュアル等を検討して、区民組織等に配布したいということを、現在、検討しております。","voiceIndex":334,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。よろしくお願いします。そうすると、１週間、２週間前でも、もう準備しなくちゃいけない。区民消火隊ですから、こういうことを区でできるのかどうかという問題は、またあるかと思うんですけれども、区が主催、あるいは協賛でもして、消防署が、こういうのは大事だからと行ったことですから、区も何らかの形で手助けができる方策はなかったかなと思いますが、その辺のお考えをお聞かせください。","respondent":"佐藤防災安全担当課長","answer":"来年以降また、発表会を開催するにあたって、区として、できる限りの支援、協力をしてまいりたいと考えております。","voiceIndex":336,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"荏原のみならず、品川区にはほかにも消防署があるわけですから、これをあまり質問してしまうと、荏原だけが突出していると、消防署が怒られてしまうといけませんので、あまり大きな声では言えませんけれども、やはり、一つ、ある地域でいいことを始めたということでしたら、やはりそれは区が応援して、今回、聞きましたら、お手伝いはしたんだということですけれども、共催ぐらいに格上げしてもらって。","respondent":"佐藤防災安全担当課長","answer":"他の地区については、品川消防署、大井消防署管内についても、同様にやるかどうか確認したところ、やっぱり地域の特性があって、荏原地区については、木造の住宅等が多いということで、延焼拡大防止も含めて、ポンプ操法大会を実施しましたが、品川。","voiceIndex":338,"id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":114475,"voices":341}},{"id":"h22-20101102-8","meetingId":"h22-cm11","date":"2010年11月2日","dateIso":"2010-11-02","committee":"建設委員会","time":"午前１１時０２分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"昨年の決議の内容は見させていただいたんですが、１番目に、外環など首都圏３環状道路の整備の重点的な促進というのがうたわれておりまして、共産党としては賛成できない内容でして、今年もおそらく同様の内容になると思うんですけれども、今年の大会決議案はどんな内容なのか、事前に確認できるのかどうかを伺います。","respondent":"松代都市計画課長","answer":"この大会につきましては、１１時から実行委員会というところで、本日皆様にご提示する宣言案、決議案というのを最終的に決めるという段取りです。その中で決まったものが、今申し上げましたように、１時の大会等でお示しされ、それに賛同いただくという形になっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"少なくとも内容確認できないということなので、おそらく同様の内容になると思うんですけれども、では、大会に参加してから内容を確認して、反対のときに、反対意見を大会で述べることができるのかというと、先ほどの説明でもありましたけれども、趣旨に賛同する方が出席する場だということですので、これまでの説明でも反対意見を言う場はないということでしたので、内容もわからないし、あと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":1877,"voices":12}}]);
